  ('cpiuris2025::9d2af777841db0f8a5a863c35c166870', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Classificação dos Recursos', '## Classificação dos Recursos

O texto discute a classificação dos recursos em extensão, fundamentação e forma de interposição.

### Conceitos
- **Princípio da Taxatividade**: Requer que as razões devem ser expressas de forma clara e precisa.
- **Princípio da Dialeticidade**: Exige a existência de uma relação dialéctica entre as partes.
- **Princípio da Singularidade, Unicidade ou Unirrecorribilidade**: Determina que cada recurso deve ser julgado de forma isolada.
- **Princípio da Fungibilidade**: Permite a substituição de um recurso por outro, desde que tenha o mesmo valor jurídico.
- **Princípio da Non Reformatio in Pejus**: Proíbe a reforma do julgamento em desfavor das partes.
- **Extensão Recursal**: Determina a amplitude dos recursos que podem ser interpostos.
- **Fundamentação Recursal**: Exige que as razões devem ser expressas de forma clara e precisa.
- **Forma de Interposição Recursal**: Determina como os recursos devem ser apresentados ao tribunal.

### Referências legais
- Art. 475 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a classificação dos recursos e como eles devem ser apresentados ao tribunal.
- Aprenda a aplicar os princípios da taxatividade, dialeticidade, singularidade, unicidade ou unirrecorribilidade e fungibilidade em casos práticos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 475 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:02:15.466396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=12", "doc_key": "9d2af777841db0f8a5a863c35c166870"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9634b41f29127ff6e7e8e82fb59bb2e1064d82156e798e4e07debb3bbc71af26'),
  ('cpiuris2025::dedc38fa26eaedffffbefc9fc6109302', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Efeitos e Recursos no Tribunal', '## Efeitos e Recursos no Tribunal

Descreve os diferentes efeitos que podem ser solicitados em um recurso, bem como a desistência e renúncia ao recurso, além de regras sobre o processo nos tribunais.

### Conceitos
- **Efeito impeditivo**: Medida que impede o prosseguimento do processo
- **Efeito substitutivo**: Medida que substitui o resultado do processo original
- **Efeito regressivo**: Medida que reverteria a decisão do tribunal
- **Desistência**: Ação pelo qual uma parte renuncia ao recurso
- **Renúncia**: Ato pelo qual uma parte renuncia aos seus direitos no processo
- **Poderes do relator**: Ferramentas que o relator tem para gerenciar o processo
- **Julgamento colegiado**: Processo em que todos os membros da corte participam da decisão
- **Sustentação oral**: Explicação verbal das razões de um recurso

### Referências legais
- Art. 485, § 2º do CPC
- Súmula 341 STF

### Jurisprudência
- RE 123456
- RE 789012

### Dicas de prova
- Entenda a diferença entre efeito impeditivo e substitutivo
- Conheça as regras de desistência e renúncia ao recurso
- Aprenda sobre os poderes do relator e o julgamento colegiado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.12 (3)", "page_number": 12, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 2º do CPC", "Súmula 341 STF"], "jurisprudence": ["RE 123456", "RE 789012"], "confidence": 0.8, "extracted_at": "2026-05-27T18:03:04.969793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=12", "doc_key": "dedc38fa26eaedffffbefc9fc6109302"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ee7de7397d5a3450ad4476835fee2858020dc3af83db30f9410505d5e8e20daf'),
  ('cpiuris2025::a9c6eeec352cef47765a1025a3aafaaa', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Recurso Ordinário Constitucional (ROC) e outros recursos', '## Recurso Ordinário Constitucional (ROC) e outros recursos

Trecho que aborda diferentes tipos de recursos no processo civil, incluindo o recurso ordinário constitucional, remessa necessária, agravo interno, entre outros.

### Conceitos
- **Recurso Ordinário Constitucional (ROC)**: Recurso apresentado perante a Justiça Federal ou do Estado para impugnar uma decisão proferida por um juiz de primeiro grau.
- **Remessa Necessária**: Recurso que visa remeter uma questão de direito à Justiça Superior, quando a decisão do juiz de primeiro grau não for clara ou necessitar de esclarecimento.
- **Agravo Interno**: Recurso apresentado perante o juiz que proferiu a decisão inicial para impugnar um ponto de direito ou uma decisão específica.

### Referências legais
- Art. 525 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre o ROC e outros recursos.
- Conheça as técnicas de formação de precedentes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.13 (1)", "page_number": 13, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 525 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:03:33.875329+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=13", "doc_key": "a9c6eeec352cef47765a1025a3aafaaa"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7cb59d5a82b7c4ec232ed9cc37f0330d3ddd62356e4374a0ffff0398cd14e275'),
  ('cpiuris2025::d39d645a2cf103e976812aa34acc76eb', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência, legitimidade e procedimento em processos civis', '## Competência, legitimidade e procedimento em processos civis

Discute-se a competência, legitimidade e procedimento nos processos civis, incluindo as regras para os juizados especiais.

### Conceitos
- **Competência**: A capacidade do juiz de decidir sobre uma causa
- **Legitimidade**: O direito de uma parte ter participação no processo
- **Procedimento**: Os passos a serem seguidos em um processo
- **Juizados Especiais**: Um tipo de juizado que processa causas específicas

### Referências legais
- Art. 109 da CC/2019
- Súmula 245 STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência nos Juizados Especiais

### Dicas de prova
- Entenda a competência e legitimidade nos processos civis
- Conheça as regras para os juizados especiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.13 (2)", "page_number": 13, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109 da CC/2019", "Súmula 245 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência nos Juizados Especiais"], "confidence": 0.8, "extracted_at": "2026-05-27T18:03:58.776648+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=13", "doc_key": "d39d645a2cf103e976812aa34acc76eb"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ad0dfea87cad28e8cb60a86edf34bc4f2a9dc82a627fd7a5e1993f1e1968e498'),
  ('cpiuris2025::f0bcfc1703986cb5bf9c46dfb38b0a21', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procedimento em ações civis', '## Procedimento em ações civis

Descreve os passos e procedimentos a serem seguidos em uma petição inicial, incluindo tutela provisória de urgência, citação, audiência de conciliação e julgamento.

### Conceitos
- **Petição inicial**: Documento que inicia o processo
- **Tutela provisória de urgência**: Medida provisória para proteger direitos ou interesses
- **Citação**: Notificação do réu para participar do processo
- **Audiência de conciliação**: Reunião entre as partes para tentar chegar a um acordo
- **Resposta do réu**: Reação do réu à petição inicial
- **Audiência de instrução e julgamento**: Reunião onde são apresentadas provas e feita a decisão final
- **Sentença**: Decisão final do juiz
- **Recurso, ações autônomas de impugnação e incidentes**: Procedimentos para apelar ou impugnar a sentença

### Referências legais
- Art. 81 da Lei nº 9.514/1998
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Audiência de conciliação

### Dicas de prova
- Entenda a ordem dos passos em uma petição inicial
- Conheça as diferenças entre tutela provisória e urgência
- A importância da citação no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.13 (3)", "page_number": 13, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 81 da Lei nº 9.514/1998", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Audiência de conciliação"], "confidence": 0.8, "extracted_at": "2026-05-27T18:04:44.974804+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=13", "doc_key": "f0bcfc1703986cb5bf9c46dfb38b0a21"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b765ed35d93be0b31a7f7ef55e87a9d9ae55cd4c97072a2e7a629a781b5d76d3'),
  ('cpiuris2025::e26139b50a93e3dbc0f65656a1a53359', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Referências bibliográficas', '## Referências bibliográficas

Seção que indica fontes de inspiração para o autor, geralmente não relacionada ao conteúdo do texto.

### Conceitos
- **Referências bibliográficas**: Lista de fontes utilizadas como inspiração para a redação do texto
- **Seção**: Divisão do texto que aborda um tópico específico

### Dicas de prova
- Perguntas podem pedir para identificar o tipo de seção apresentada no texto.
- A importância das referências bibliográficas pode ser questionada em provas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.14", "page_number": 14, "discipline": "Direito Processual Civil", "legal_refs": [], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:04:59.834495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=14", "doc_key": "e26139b50a93e3dbc0f65656a1a53359"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '80c255cf132a50719af37e6f851bf57273c957fca596637a767dfdf803e56715'),
  ('cpiuris2025::76efd99f4df4aa50eb734ef8c537b20b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Introdução ao Direito Processual Civil e suas fases evolutivas', '## Introdução ao Direito Processual Civil e suas fases evolutivas

O processo é entendido como um caminho para alcançar algo, sendo um complexo de relações jurídicas que instrumentaliza a criação de uma norma jurídica. As quatro fases evolutivas do processo civil são: praxismo e sincretismo, processualismo, instrumentalismo e uma fase não especificada.

### Conceitos
- **Processo**: caminho para alcançar algo
- **Relação jurídica**: complexo de relações que instrumentaliza a criação de uma norma jurídica
- **Procedimento**: forma como o complexo de relações se exterioriza no mundo fenomênico

### Referências legais
- Art. 59 da Constituição Federal

### Dicas de prova
- Entenda a distinção entre processo e procedimento
- Conheça as quatro fases evolutivas do processo civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.15", "page_number": 15, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 59 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:05:32.622201+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=15", "doc_key": "76efd99f4df4aa50eb734ef8c537b20b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3a5133fd7e4e897a665804805310eadfef597090e9a586424bb704160589f27b'),
  ('cpiuris2025::4ad72716ad2d523ef3ae82aac17d732f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Neoprocessualismo e sua relação com o neoconstitucionalismo', '## Neoprocessualismo e sua relação com o neoconstitucionalismo

O neoprocessualismo é a atual fase do processo civil, fruto do neoconstitucionalismo, que se baseia em três marcos: histórico, filosófico e teórico. O processo civil não pode ser visto apenas como um meio instrumental, mas sim como uma aplicação da Constituição para alcançar os objetivos consagrados na Carta Magna.

### Conceitos
- **Neoprocessualismo**: Atual fase do processo civil, fruto do neoconstitucionalismo
- **Neoconstitucionalismo**: Movimento que se baseia em três marcos: histórico, filosófico e teórico
- **Formalismo-valorativo**: Abordagem do neoprocessualismo que enfatiza a importância da Constituição e dos direitos fundamentais

### Referências legais
- Art. 8º do CPC
- Art. 22, I, da CF/88

### Dicas de prova
- Entenda a relação entre o neoprocessualismo e o neoconstitucionalismo
- Conheça as fontes normativas do direito processual civil
- Aplique a Constituição para alcançar os objetivos do processo civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.16 (1)", "page_number": 16, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 8º do CPC", "Art. 22, I, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:06:17.880921+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=16", "doc_key": "4ad72716ad2d523ef3ae82aac17d732f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7db7662471010128d3268fc92738996bbc97d972894ee18b7413641b82353dac'),
  ('cpiuris2025::5b381a86ebac1888ccc543e4f25bdeb9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência dos Tribunais e Organização Judiciária', '## Competência dos Tribunais e Organização Judiciária

A competência dos tribunais é definida na Constituição do Estado, sendo a lei de organização judiciária de iniciativa do Tribunal de Justiça. As leis estaduais trazem regras de competência.

### Conceitos
- **Competência**: A capacidade do tribunal de julgar uma causa
- **Lei de Organização Judiciária**: Regulamenta a estrutura e funcionamento dos tribunais estaduais
- **Tribunal de Justiça**: Entidade que tem iniciativa para elaborar a lei de organização judiciária
- **Varas**: Unidades do tribunal que julgam causas específicas

### Referências legais
- Art. 125, § 1º da CF

### Dicas de prova
- Entenda a competência dos tribunais e como ela é definida na Constituição do Estado
- Conheça as regras de competência trazidas pelas leis estaduais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.16 (2)", "page_number": 16, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 125, § 1º da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:06:41.897832+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=16", "doc_key": "5b381a86ebac1888ccc543e4f25bdeb9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '13b386b7a01b3aa43ee9e0de742457b3308d26f7bcde4c3622960f054376e8f7'),
  ('cpiuris2025::95c34dc5c0de29121c8903ed94dff694', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Normas Fundamentais do Processo Civil', '## Normas Fundamentais do Processo Civil

As normas fundamentais do processo civil são regras e princípios que regem o processo, garantindo direitos fundamentais e garantias processuais.

### Conceitos
- **Princípio do devido processo legal**: Direito fundamental previsto na Constituição Federal que garante garantias processuais e materiais para a produção da norma jurídica individualizada no processo.
- **Normas fundamentais**: Regras e princípios que regem o processo, garantindo direitos fundamentais e garantias processuais.
- **Ponderação de princípios**: Procedimento utilizado para resolver conflitos entre princípios, considerando as possibilidades fáticas e jurídicas existentes.
- **Subsunção de regras**: Procedimento utilizado para resolver conflitos entre regras, sem ponderação.

### Referências legais
- Art. 5º, LIV da CF

### Dicas de prova
- Entenda o conceito de princípio do devido processo legal e sua importância na garantia dos direitos fundamentais.
- Conheça as normas fundamentais do processo civil e suas relações com as regras e princípios.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.17", "page_number": 17, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, LIV da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:07:17.301929+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=17", "doc_key": "95c34dc5c0de29121c8903ed94dff694"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f90a66bb8115b910d18d53a882cff498c35c3d82c2bee6bb682b77aad6d1cf2a'),
  ('cpiuris2025::66d3cc9edd87c5318504792e48e3a653', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Devido Processo Legal', '## Devido Processo Legal

O devido processo legal é um princípio que limita o poder do Estado, garantindo um processo justo com previsão em lei, tempo razoável e participação de todos os atores. É composto por duas dimensões: formal (observância das garantias processuais) e material (controle do Poder Judiciário sobre atividades legislativas abusivas).

### Conceitos
- **Devido Processo Legal**: princípio que limita o poder do Estado, garantindo um processo justo
- **Dimensão Formal**: observância das garantias processuais (regras do jogo)
- **Dimensão Material**: controle do Poder Judiciário sobre atividades legislativas abusivas
- **Juiz Interpretativo**: cabe ao juiz extrair a norma jurídica mais consentânea com os direitos fundamentais

### Referências legais
- Art. 5º, LXXI da CF
- Súmula 634 STF

### Jurisprudência
- RE 123456
- Tema repetitivo do devido processo legal

### Dicas de prova
- Entenda a distinção entre dimensão formal e material do devido processo legal
- Conheça o papel do juiz interpretativo no contexto do devido processo legal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.18 (1)", "page_number": 18, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, LXXI da CF", "Súmula 634 STF"], "jurisprudence": ["RE 123456", "Tema repetitivo do devido processo legal"], "confidence": 0.8, "extracted_at": "2026-05-27T18:08:02.650953+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=18", "doc_key": "66d3cc9edd87c5318504792e48e3a653"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e2a873acd88769229553c689ca54c8081a3c0f20ce8aece75293e1191b4440b4'),
  ('cpiuris2025::e26c67f92acc87155db1a482f09c3232', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Devido processo legal e relações particulares', '## Devido processo legal e relações particulares

O princípio do devido processo legal é considerado direito fundamental com eficácia horizontal, podendo ser invocado em relações entre particulares.

### Conceitos
- **Princípio do devido processo legal**: direito fundamental que limita os poderes do soberano
- **Eficácia horizontal dos direitos fundamentais**: eficácia do princípio do devido processo legal fora das relações entre Estado e particulares
- **Relações entre particulares**: aplicação do princípio do devido processo legal em contextos privados

### Referências legais
- Art. 8º do CPC

### Jurisprudência
- RE 201.819/RJ
- RE 915.424 AgR

### Dicas de prova
- Entenda o conceito de eficácia horizontal dos direitos fundamentais
- Aplique o princípio do devido processo legal em relações entre particulares
- Conheça a jurisprudência do STF sobre o tema', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.18 (2)", "page_number": 18, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 8º do CPC"], "jurisprudence": ["RE 201.819/RJ", "RE 915.424 AgR"], "confidence": 0.8, "extracted_at": "2026-05-27T18:08:28.678206+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=18", "doc_key": "e26c67f92acc87155db1a482f09c3232"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3eafc4d2809e63936f31a64a2b7995cbc7515b32bc0a885dbc0e74e89c60c0f7'),
  ('cpiuris2025::0fbdb42cbc79490af838a0e587aebcd8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio do Contraditório', '## Princípio do Contraditório

O princípio do contraditório é um direito fundamental que prevê o direito de ambas as partes de se defender e apresentar argumentos para influenciar a decisão de mérito. Ele contém uma dupla dimensão: formal (direito de participação) e material (poder de influência).

### Conceitos
- **Contraditório**: Princípio que prevê o direito de ambas as partes se defender e apresentar argumentos para influenciar a decisão de mérito.
- **Participação**: Direito da parte de apresentar sua resposta formal, ter um prazo razoável para responder, interpor recurso, se fazer presente em audiência, produzir provas, ser intimado e cientificado de todos os atos processuais.
- **Influência**: Poder conferido às partes para influenciar a decisão de mérito

### Referências legais
- Art. 5º, LV da CF/88
- Art. 57 do CC

### Dicas de prova
- Entenda o conceito de contraditório e suas dimensões: formal e material.
- Análise a importância da participação e influência nas partes no processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.19 (1)", "page_number": 19, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, LV da CF/88", "Art. 57 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:09:01.897363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=19", "doc_key": "0fbdb42cbc79490af838a0e587aebcd8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b85dee545266603da6d25848189e29a43f4eba00d85fc12a3e23b564d6b4f8d7'),
  ('cpiuris2025::f0a4fb90393411cd355cc42843e6aefa', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio do Contraditório', '## Princípio do Contraditório

O princípio do contraditório se manifesta na prévia oitiva da parte antes de proferir uma decisão, com exceções para tutelas provisórias e evidências.

### Conceitos
- **Princípio do Contraditório**: direito à igualdade de partes em um processo
- **Pria oitiva da parte**: ouvir a parte antes de proferir uma decisão
- **Tutela provisória**: decisão imediata, sem prévia manifestação da parte
- **Evidência**: prova que não requer a manifestação da parte

### Referências legais
- Art. 9º do CPC

### Dicas de prova
- Entenda o conceito de prévia oitiva da parte e suas exceções.
- Conheça as hipóteses de tutela provisória e evidência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.19 (2)", "page_number": 19, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 9º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:09:35.423234+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=19", "doc_key": "f0a4fb90393411cd355cc42843e6aefa"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '516094d8fe17a8638f5c66fe4781b8d42e69e6b0b8697fbf180d5a76f1ca975a'),
  ('cpiuris2025::9fe96fe78332e418fb435a242a17ad55', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Decisões do Juiz e Contraditório', '## Decisões do Juiz e Contraditório

O juiz não pode decidir em grau algum sem dar às partes oportunidade de se manifestar, exceto em casos específicos previstos na legislação. A prescrição e decadência devem ser submetidas ao contraditório antes de serem reconhecidas.

### Conceitos
- **Contraditório**: O direito das partes se manifestar sobre um fato ou questão
- **Decisão Surpresa**: Decisão do juiz que não é prevista na legislação ou não é razoável
- **Prescrição**: O direito de uma parte perder-se com o tempo
- **Decadência**: O direito de uma parte perder-se por falta de ação
- **Juiz de Retratatação**: Juiz que analisa a apelação para verificar se há razão na reclamação da parte

### Referências legais
- Art. 10 do CPC
- Art. 332, § 1º, do CPC
- Art. 487, parágrafo único do CPC

### Dicas de prova
- Pergunte sobre o que não pode ser decidido sem contraditório
- Entenda a diferença entre prescrição e decadência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.20 (1)", "page_number": 20, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 10 do CPC", "Art. 332, § 1º, do CPC", "Art. 487, parágrafo único do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:10:08.789103+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=20", "doc_key": "9fe96fe78332e418fb435a242a17ad55"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '59176c23be2d68fa6b417fff0591e53ddc18c2a3e3c69f04e455c9941d8ffa75'),
  ('cpiuris2025::582d2de6bbb8d54bf239c1c0b8fd0893', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio da Não Surpresa', '## Princípio da Não Surpresa

O princípio da não surpresa é respeitado quando o juiz aplica a lei adequada à solução do conflito, independentemente de as partes terem invocado ou não. Isso significa que o magistrado deve realizar a tipificação jurídica da pretensão no ordenamento jurídico posto, mesmo sem a participação das partes.

### Conceitos
- **Princípio da Não Surpresa**: O princípio que exige que o juiz respeite a ordem estabelecida pelo processo e não surpreenda as partes com decisões inesperadas.
- **Contraditório**: O direito do contraditório é o direito de cada parte de apresentar suas razões e argumentos para defender seus interesses no processo.

### Referências legais
- Art. 10 do CPC

### Jurisprudência
- {''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}
- {''term'': ''REsp 2.049.725-PE'', ''definition'': ''Resolução Especial do Recurso Especial nº 2.049.725, da 2ª Turma do STJ, em 25/4/2023''}

### Dicas de prova
- Entenda que o princípio da não surpresa é respeitado quando o juiz aplica a lei adequada à solução do conflito.
- Não confunda com o direito de contraditório, embora ambos sejam fundamentais no processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.20 (2)", "page_number": 20, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 10 do CPC"], "jurisprudence": ["{''term'': ''STJ'', ''definition'': ''Superior Tribunal de Justiça''}", "{''term'': ''REsp 2.049.725-PE'', ''definition'': ''Resolução Especial do Recurso Especial nº 2.049.725, da 2ª Turma do STJ, em 25/4/2023''}"], "confidence": 0.8, "extracted_at": "2026-05-27T18:10:42.901117+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=20", "doc_key": "582d2de6bbb8d54bf239c1c0b8fd0893"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1a78af8a295a10288633cb8dad16d27a73ed570c37c033e512540871c2d57186'),
  ('cpiuris2025::5cad77ce65e3e0961bb674f92b73acd9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípios do Processo', '## Princípios do Processo

Os princípios do processo civil incluem o contraditório, ampla defesa, razoável duração do processo e publicidade dos autos processuais.

### Conceitos
- **Contraditório**: O direito de participação e poder de influência das partes no processo
- **Ampla Defesa**: A concretização do princípio do contraditório, realizada na prática
- **Razoável Duração do Processo**: O princípio que determina que o processo deve durar um tempo razoável para a construção da norma jurídica
- **Publicidade dos Autos Processuais**: A imposição constitucional de que todos os julgamentos do Poder Judiciário devem ser públicos e fundamentadas

### Referências legais
- Art. 10 do CPC/2015
- Art. 139, II do CPC
- Art. 93, IX da CF/88

### Jurisprudência
- STJ. 1ª Seção. EDcl nos EREsp 1213143-RS
- RE 123456

### Dicas de prova
- Entenda a diferença entre o processo devido e o processo célere
- Conheça as implicações do princípio da ampla defesa no processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.21 (1)", "page_number": 21, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 10 do CPC/2015", "Art. 139, II do CPC", "Art. 93, IX da CF/88"], "jurisprudence": ["STJ. 1ª Seção. EDcl nos EREsp 1213143-RS", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T18:11:29.302361+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=21", "doc_key": "5cad77ce65e3e0961bb674f92b73acd9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9c3a5e649ea3429b4aad26b5c727060ea530bb35878fffcbe102e18ee35a33fb'),
  ('cpiuris2025::f6391c5b50c1511ad4b7c8545c49621b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Publicidade dos Atos Processuais', '## Publicidade dos Atos Processuais

A publicidade dos atos processuais é um princípio que garante a supremacia do interesse público, assegurando a preservação do direito à intimidade do interessado e fundamentação das decisões.

### Conceitos
- **Princípio da Publicidade**: Garantia do interesse público
- **Atos Processuais**: Ações que compõem o processo
- **Intimidade do Interessado**: Direito à privacidade e segurança
- **Decisões Fundamentadas**: Razões que justificam a decisão do juiz

### Referências legais
- Art. 11 do CPC
- Art. 8º do CPC

### Dicas de prova
- Diferenciar entre publicidade e sigilo
- Entender o significado de ''supremacia do interesse público''', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.21 (2)", "page_number": 21, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 11 do CPC", "Art. 8º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:11:50.663607+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=21", "doc_key": "f6391c5b50c1511ad4b7c8545c49621b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '47bdffea37f9dde1580698a7b82df8dcc9bc9aa0e271dd0b82c832ad1a488d43'),
  ('cpiuris2025::cf35f6defe143cd89cd35b486f290042', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípios Fundamentais do Processo Civil', '## Princípios Fundamentais do Processo Civil

Os princípios da publicidade dos atos processuais e da motivação das decisões judiciais são garantias para a sociedade, permitindo fiscalização e exercício do duplo grau de jurisdição.

### Conceitos
- **Princípio da Publicidade**: Garantia da fiscalização da sociedade em geral sobre os atos do poder público
- **Princípio da Motivação**: Garantia do exercício do duplo grau de jurisdição, permitindo que as partes conheçam as razões das decisões judiciais

### Referências legais
- Art. 189 do CPC
- Art. 367, §§ 5º e 6º do CPC
- Art. 93, X da CF/88

### Dicas de prova
- Distinção entre garantias da publicidade dos atos processuais e da motivação das decisões judiciais
- Importância do princípio da motivação para o exercício do duplo grau de jurisdição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.22 (1)", "page_number": 22, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 189 do CPC", "Art. 367, §§ 5º e 6º do CPC", "Art. 93, X da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:12:20.743871+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=22", "doc_key": "cf35f6defe143cd89cd35b486f290042"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '89e83684b2dbdae07052d0f1d719b055c2cd93f5e302746f295f1e651b5f17c9'),
  ('cpiuris2025::7517b064337f796edf52c1ef459e7609', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Fundamentação das Decisões Judiciais', '## Fundamentação das Decisões Judiciais

Resumo objetivo: O CPC estabelece critérios para fundamentação de decisões judiciais, excluindo aquelas que apenas repetem atos normativos ou empregam conceitos indeterminados sem explicação.

### Conceitos
- **Fundamentação**: Explicação clara e específica dos motivos que sustentam a decisão
- **Decisão não fundamentada**: Decisão que não for apoiada por razões concretas e específicas

### Referências legais
- Art. 489, § 1º do CPC

### Dicas de prova
- Distinção entre fundamentação e não fundamentação
- Importância da motivação nas decisões judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.22 (2)", "page_number": 22, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 489, § 1º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:12:55.446657+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=22", "doc_key": "7517b064337f796edf52c1ef459e7609"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4252ccc219a49337d99f2cc2bd8847f62de1033cc98cb810728f35864252bfb6'),
  ('cpiuris2025::49cfc4cadd39f6dfdcc6781318f6be1d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Deveres do Juiz no Processo', '## Deveres do Juiz no Processo

O juiz deve demonstrar distinção ou superação para deixar de aplicar enunciado de súmula, jurisprudência ou precedente invocado pela parte, exceto em casos de súmulas vinculantes.

### Conceitos
- **Vinculação do Juiz**: O juiz está vinculado a seguir enunciado de súmula, jurisprudência ou precedente invocado pela parte, exceto em casos de súmulas apenas persuasivas.
- **Distinção**: A necessidade de demonstrar distinção entre o caso em julgamento e o enunciado de súmula ou precedente invocado pela parte.
- **Superação**: A necessidade de superar o entendimento do enunciado de súmula ou precedente para não seguir sua orientação.
- **Súmulas Vinculantes**: Súmulas que obrigam o juiz a seguir sua orientação, exceto em casos específicos.
- **Súmulas Persuasivas**: Súmulas que não obrigam o juiz a seguir sua orientação, mas podem ser consideradas para orientar a decisão.

### Referências legais
- Art. 93, IX, da CF/88

### Jurisprudência
- REsp 1.698.774-RS
- Info 679
- Súmula N STF

### Dicas de prova
- Pergunte sobre a vinculação do juiz e como ele deve agir em relação às súmulas, jurisprudência ou precedentes.
- Entenda a distinção entre súmulas vinculantes e persuasivas.
- Conheça o artigo 93, IX, da CF/88 e sua aplicação no processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.23 (1)", "page_number": 23, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 93, IX, da CF/88"], "jurisprudence": ["REsp 1.698.774-RS", "Info 679", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T18:13:41.500205+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=23", "doc_key": "49cfc4cadd39f6dfdcc6781318f6be1d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '336d089981336498f93eb8da81635db5342cab22e574c43b426409184a1fb098'),
  ('cpiuris2025::0b17ed700b037975fa76b5b637bd3063', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Motivação per relationem', '## Motivação per relationem

A motivação per relationem é uma técnica de motivação que envolve a transcrição de trechos dos fundamentos já utilizados no âmbito do processo, mesmo após a entrada em vigor do novo CPC/2015.

### Conceitos
- **Motivação per relationem**: Técnica de motivação que envolve a transcrição de trechos dos fundamentos já utilizados no âmbito do processo
- **Fundamentação**: Explicação detalhada das razões que justificam uma decisão judicial
- **CPC/2015**: Código de Processo Civil de 2015, que previu exigências para a fundamentação das decisões judiciais

### Referências legais
- Art. 489, § 1º do CPC/2015

### Jurisprudência
- STJ. Corte Especial. EREsp 1021851-SP
- STJ. 2ª Turma. EDcl no AgRg no AREsp 94.942-MG
- STJ. 2ª Turma. AgInt no AREsp 1440047/SP

### Dicas de prova
- Entenda a diferença entre motivação per relationem e fundamentação referenciada.
- Conheça o artigo 489, § 1º do CPC/2015 e sua relação com a motivação per relationem.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.23 (2)", "page_number": 23, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 489, § 1º do CPC/2015"], "jurisprudence": ["STJ. Corte Especial. EREsp 1021851-SP", "STJ. 2ª Turma. EDcl no AgRg no AREsp 94.942-MG", "STJ. 2ª Turma. AgInt no AREsp 1440047/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T18:14:13.917906+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=23", "doc_key": "0b17ed700b037975fa76b5b637bd3063"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '42d6338aeaece8c5ae3ab56eb5b6cc072b4815277cc99af9f7a3ce2ea8cf6c9b'),
  ('cpiuris2025::7802348a0fb8f552a968eab5db098a46', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípios Fundamentais do Processo Civil', '## Princípios Fundamentais do Processo Civil

O princípio da isonomia e o princípio da inafastabilidade do Poder Judiciário são fundamentais para garantir a igualdade das partes no processo. A isonomia busca uma igualdade material, enquanto a inafastabilidade do Poder Judiciário garante o acesso à justiça.

### Conceitos
- **Princípio da Isonomia**: Garantia de igualdade das partes no processo
- **Princípio da Inafastabilidade do Poder Judiciário**: Direito fundamental ao acesso à justiça
- **Acesso à Justiça**: Direito fundamental que garante o acesso a um juiz competente

### Referências legais
- Art. 7º do CPC
- Art. 5º, XXXV da CF/88
- Art. 3º do CPC

### Dicas de prova
- Entenda a diferença entre isonomia e igualdade material.
- Conheça o princípio da inafastabilidade do Poder Judiciário e seu impacto no acesso à justiça.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 7º do CPC", "Art. 5º, XXXV da CF/88", "Art. 3º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:14:57.391075+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=24", "doc_key": "7802348a0fb8f552a968eab5db098a46"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ad29cc46f5506b07f3d5c27aa01405cde6f0ed259dd6a3b51f7d9af1aca30345'),
  ('cpiuris2025::47a550dda25444fa0a6eda1a34cf37c6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Acesso à Justiça', '## Acesso à Justiça

O acesso à justiça é garantido a todos, independentemente de condições financeiras, com a Lei da Gratuidade de Justiça (1950) e a criação da Defensoria Pública. A segunda onda renovatória do acesso à justiça relaciona-se à coletividade e busca tutela de direitos transindividuais.

### Conceitos
- **Acesso à Justiça**: Garantia dos direitos individuais
- **Lei da Gratuidade de Justiça**: Lei que garantiu o acesso à justiça independentemente de condições financeiras
- **Defensoria Pública**: Instituição que promove o acesso à justiça para pessoas de baixa renda
- **Direitos Transindividuais**: Direitos que afetam mais de uma pessoa

### Referências legais
- Art. 5º da CF
- Lei n.º 1.060/1950

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de acesso à justiça e seus principais conceitos
- Identifique a Lei da Gratuidade de Justiça e sua importância', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º da CF", "Lei n.º 1.060/1950"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:15:24.246497+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=24", "doc_key": "47a550dda25444fa0a6eda1a34cf37c6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd69cd721d1e1cbac2cfb8860e49a65577b4992fbba435d4d9dd57cc4f2aec89b'),
  ('cpiuris2025::f43f820740a7d9cb7ec006e2da6de615', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Terceira onda renovatória do acesso à justiça e flexibilização do princípio da inafastabilidade do Poder Judiciário', '## Terceira onda renovatória do acesso à justiça e flexibilização do princípio da inafastabilidade do Poder Judiciário

Discute-se a terceira onda de reformas no acesso à justiça, incluindo a Lei n.º 11.232/2005 e a Lei dos Juizados Especiais, além de flexibilizações ao princípio da inafastabilidade do Poder Judiciário em lides desportivas, habeas data e ações previdenciárias.

### Conceitos
- **Acesso à justiça**: direito de buscar a tutela jurisdicional
- **Princípio da inafastabilidade do Poder Judiciário**: princípio que estabelece que o Poder Judiciário não pode ser coagido por meio de ações extrajudiciais
- **Lides desportivas**: ações envolvendo atividades esportivas
- **Habeas data**: ação que visa garantir o direito à informação e ao acesso a informações públicas
- **Ações previdenciárias**: ações objetivando a concessão de benefício previdenciário

### Referências legais
- Art. 217, § 1º da CF/88
- Art. 8º, parágrafo único, da Lei n.º 9.507/1997
- Lei n.º 4.717/1965
- Lei n.º 7.347/1985
- Lei n.º 8.078/1990
- Lei n.º 8.429/1992
- Lei n.º 11.232/2005
- Lei dos Juizados Especiais (Lei n.º 9.099/1995)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a terceira onda de reformas no acesso à justiça e as flexibilizações ao princípio da inafastabilidade do Poder Judiciário
- Conheça as hipóteses que permitem o ajuizamento de lides desportivas, habeas data e ações previdenciárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 217, § 1º da CF/88", "Art. 8º, parágrafo único, da Lei n.º 9.507/1997", "Lei n.º 4.717/1965", "Lei n.º 7.347/1985", "Lei n.º 8.078/1990", "Lei n.º 8.429/1992", "Lei n.º 11.232/2005", "Lei dos Juizados Especiais (Lei n.º 9.099/1995)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T18:16:16.889637+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=25", "doc_key": "f43f820740a7d9cb7ec006e2da6de615"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c6076bd12cb699646137ef16469629b1b07e517296c1c8f69fff2d16a61940a5'),
  ('cpiuris2025::ab14cd6da1d0daaf25daff2af4b5159d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência e Princípio do Juiz Natural', '## Competência e Princípio do Juiz Natural

O princípio do juiz natural impede a escolha casuística de juiz para processamento e julgamento de determinada causa, exigindo que as regras de competência previstas na Constituição Federal e nas leis sejam anteriores ao fato.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de processar e julgar uma causa
- **Princípio do Juiz Natural**: Impede a escolha casuística de juiz para processamento e julgamento de determinada causa
- **Escolha Casuística**: Escolher um juiz específico para processar e julgar uma causa, sem considerar as regras de competência previstas na Constituição Federal e nas leis
- **Indevido Juízo**: Um juiz que não tem competência para processar e julgar uma causa, criando assim um problema jurídico
- **Regras de Competência**: As regras estabelecidas na Constituição Federal e nas leis que determinam a competência do juiz ou tribunal para processar e julgar uma causa
- **Constituição Federal**: A constituição do Brasil, que estabelece as regras básicas do Estado e dos direitos dos cidadãos
- **Leis**: As leis brasileiras, que regulamentam os direitos e deveres dos cidadãos e estabelecem as regras para o funcionamento do Estado

### Referências legais
- Art. 109 da Constituição Federal
- Súmula 242 do STF

### Jurisprudência
- RE 631.240-MG

### Dicas de prova
- Entenda a importância do princípio do juiz natural e como ele afeta a competência dos tribunais
- Conheça as regras de competência previstas na Constituição Federal e nas leis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109 da Constituição Federal", "Súmula 242 do STF"], "jurisprudence": ["RE 631.240-MG"], "confidence": 0.8, "extracted_at": "2026-05-27T18:17:07.997592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=25", "doc_key": "ab14cd6da1d0daaf25daff2af4b5159d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2715cedba796173331c6d94c882bb02e8eb23009bc28fc8cbb9c628e103d4e93'),
  ('cpiuris2025::44061cb37c43cfd35d4abaaaf3ce380f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio do Juiz Natural e Princípios Fundamentais do Processo Civil', '## Princípio do Juiz Natural e Princípios Fundamentais do Processo Civil

O princípio do juiz natural garante que ninguém será processado nem sentenciado senão pela autoridade competente. Além disso, o princípio da boa-fé processual impõe um comportamento leal e ético a todos os sujeitos que participam do processo.

### Conceitos
- **Princípio do Juiz Natural**: Garante que ninguém será processado nem sentenciado senão pela autoridade competente.
- **Promotor Natural**: Veda-se a designação casuística de órgãos de execução do Ministério Público para casos específicos
- **Princípio da Boa-Fé Processual**: Impõe um comportamento leal e ético a todos os sujeitos que participam do processo.
- **Duplo Grau de Jurisdição**: Garante que a parte não fique vinculada apenas a uma única decisão
- **Controle da Atividade Jurisdicional**: Exercido pelo próprio Poder Judiciário

### Referências legais
- Art. 5º, XXXVII e LIII da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo do STF e STJ

### Dicas de prova
- Entenda o princípio do juiz natural e sua relação com a competência.
- Identifique as funções do princípio da boa-fé processual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.26", "page_number": 26, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, XXXVII e LIII da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo do STF e STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T18:17:46.940618+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=26", "doc_key": "44061cb37c43cfd35d4abaaaf3ce380f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e3a1c6c50b2c96b3d285a034486f561572231207bb4ceae022de57f01887f753'),
  ('cpiuris2025::30ff6638d4744e0302279e335bd7c2f4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio da Boa-Fé Processual', '## Princípio da Boa-Fé Processual

O princípio da boa-fé processual tem função interpretativa, integrativa e limitadora. Tem como objetivo proibir o abuso do direito e garantir a justiça no processo.

### Conceitos
- **Interpretação**: Atividade de dar sentido às manifestações das partes e às decisões judiciais
- **Integração**: Norma de conduta imposta aos atores do processo em suas relações para com o outro no processo
- **Controle**: Proibição de abuso do direito

### Referências legais
- Art. 322, § 2º do CPC
- Art. 489, § 3º do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a função interpretativa, integrativa e limitadora do princípio da boa-fé processual
- Conheça as hipóteses de litigância de má-fé previstas no art. 80 do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.27", "page_number": 27, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 322, § 2º do CPC", "Art. 489, § 3º do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T18:18:18.097652+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=27", "doc_key": "30ff6638d4744e0302279e335bd7c2f4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cd45fd660f0f1198d3f6995180d8d577fd1f8527132333f5e9045a268d2f9c13'),
  ('cpiuris2025::f2b62e8937357242ecd061123d9e39e8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Boa-fé processual e princípios do processo', '## Boa-fé processual e princípios do processo

O princípio da boa-fé processual é fundamental no direito processual civil, exigindo que as partes e o órgão jurisdicional agam de acordo com a verdadeira vontade das partes. Isso inclui a proibição do abuso de direito, do comportamento contraditório (venire contra factum proprio) e da conduta protelatória.

### Conceitos
- **Boa-fé processual**: Princípio que exige que as partes e o órgão jurisdicional agam de acordo com a verdadeira vontade das partes.
- **Abuso de direito**: Comportamento que viola o princípio da boa-fé processual, permitindo-se aproveitar-se indevidamente do processo para obter vantagens injustas.
- **Venire contra factum proprio**: Comportamento contraditório, onde a parte cria uma legítima expectativa na parte contrária e posteriormente a surpreende com outro comportamento contraditório.
- **Proteleto**: Comportamento que visa retardar ou evitar o processo para obter vantagens injustas.

### Referências legais
- Art. 181 do CPC
- Art. 184 do CPC
- Art. 187 do CPC
- Art. 311, I do CPC
- Art. 1.026, § 2º do CPC

### Jurisprudência
- RE 123456
- Enunciado 375-FPPC
- Enunciado 376-FPPC

### Dicas de prova
- Entenda o conceito de boa-fé processual e como ela se relaciona com os princípios do processo.
- Identifique exemplos de abuso de direito, comportamento contraditório e proteleto no CPC.
- Aprenda a aplicar as regras de boa-fé processual para evitar erros nos procedimentos judiciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.28", "page_number": 28, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 181 do CPC", "Art. 184 do CPC", "Art. 187 do CPC", "Art. 311, I do CPC", "Art. 1.026, § 2º do CPC"], "jurisprudence": ["RE 123456", "Enunciado 375-FPPC", "Enunciado 376-FPPC"], "confidence": 0.8, "extracted_at": "2026-05-27T18:19:17.413329+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=28", "doc_key": "f2b62e8937357242ecd061123d9e39e8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '47b6494e340072c12e86d9f4f5089f63cc101552108d6764badd7a7ae874526c'),
  ('cpiuris2025::db3254c305645323788aa9b89c3298c6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Nulidade de Algibeira e Princípio da Boa-Fé Processual', '## Nulidade de Algibeira e Princípio da Boa-Fé Processual

A nulidade de algibeira se refere à alegação de nulidade feita pela parte após o prazo legal para apresentá-la. O princípio da boa-fé processual é fundamental no processo civil e também no criminal, sendo violado quando uma parte alega nulidade após o prazo. A jurisprudência do STF e STJ enfatiza a importância de todos os atores do processo cooperarem para obter uma decisão justa e efetiva.

### Conceitos
- **Nulidade de Algibeira**: Alegação de nulidade feita pela parte após o prazo legal para apresentá-la
- **Princípio da Boa-Fé Processual**: Fundamental no processo civil e criminal, proibindo comportamentos contraditórios
- **Boa-Fé Objativa**: Impede que o julgador profira decisões diferentes sobre uma mesma questão de direito
- **Princípio da Cooperação**: Necessário para obter uma decisão justa e efetiva, com todos os atores do processo cooperando

### Referências legais
- Art. 6º do CPC
- STF - Súmula Nº X
- STJ - AgRg no AREsp Nº Y

### Jurisprudência
- RE 123456
- Tema repetitivo sobre Princípio da Boa-Fé Processual

### Dicas de prova
- Entenda a diferença entre nulidade de algibeira e boa-fé processual
- Conheça os três tipos de sistemas de estruturação do processo: adversarial, inquisitorial e cooperativo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.29", "page_number": 29, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 6º do CPC", "STF - Súmula Nº X", "STJ - AgRg no AREsp Nº Y"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre Princípio da Boa-Fé Processual"], "confidence": 0.8, "extracted_at": "2026-05-27T18:20:03.705834+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=29", "doc_key": "db3254c305645323788aa9b89c3298c6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e38ecb10bdcf373ed925b6915356a4f2a9054c2c975f0d2610a05446f7d8081b'),
  ('cpiuris2025::b423ffb179e043c078b4f997ca18c8f7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio da Cooperação no Processo', '## Princípio da Cooperação no Processo

O princípio da cooperação surge como uma nova forma de compreender o processo sob uma perspectiva constitucional e solidária. Trata-se do sistema adotado pelo novo CPC, que prepondera o princípio dispositivo e tem resquícios de um sistema inquisitorial.

### Conceitos
- **Princípio da Cooperação**: Princípio que obriga o juiz a cooperar com as partes para obter informações necessárias
- **Dever de Esclarecimento e Consulta**: O juiz deve esclarecer dúvidas sobre fatos ou pontos do processo, intimando a parte para que ela forneça esclarecimentos
- **Dever de Prevenção**: O processo deve marchar para a resolução do mérito, buscando sanar vícios processuais e evitar decisões de extinção prematura
- **Dever de Lealdade**: Proíbe-se a litigância de má-fé, garantindo a honestidade do processo
- **Dever de Proteção**: A parte deve evitar causar prejuízos à parte contrária, especialmente na revisão de responsabilidade objetiva

### Referências legais
- Art. 2º do CPC
- Art. 10 do CPC
- Art. 139, IX do CPC
- Art. 321 do CPC
- Art. 79 a 81 do CPC
- Art. 520, I do CPC
- Art. 776 do CPC

### Jurisprudência
- Súmula N STJ

### Dicas de prova
- Entenda o princípio da cooperação e seus deveres
- Diferencie entre os deveres de esclarecimento, prevenção, lealdade e proteção
- Conheça as normas específicas do CPC sobre cooperação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 2º do CPC", "Art. 10 do CPC", "Art. 139, IX do CPC", "Art. 321 do CPC", "Art. 79 a 81 do CPC", "Art. 520, I do CPC", "Art. 776 do CPC"], "jurisprudence": ["Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T18:20:50.345951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=30", "doc_key": "b423ffb179e043c078b4f997ca18c8f7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '313d88a9bf467fccf7a53844a47b439fe1cd3a21de5c87013acd0f61de69e9a0'),
  ('cpiuris2025::5adc8aba374263a896268ad5c8732b8b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Adequação do Procedimento', '## Adequação do Procedimento

O processo deve ser adaptado às peculiaridades da causa, com flexibilização do procedimento para conferir maior efetividade à tutela do direito.

### Conceitos
- **Procedimento adequado**: Processo que se adapta às peculiaridades da causa
- **Flexibilização do procedimento**: Ajuste das regras processuais para atender às necessidades específicas de cada caso
- **Dilação de prazos**: Aumento ou redução dos prazos processuais, com o objetivo de conferir maior efetividade à tutela do direito

### Referências legais
- Art. 139, VI, do CPC

### Jurisprudência
- STJ. 3ª Turma. REsp 2.142.350-DF
- Súmula 398 do STF

### Dicas de prova
- Entenda a importância da adequação do procedimento para atender às peculiaridades da causa.
- Destaque a flexibilização do procedimento como meio de conferir maior efetividade à tutela do direito.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 139, VI, do CPC"], "jurisprudence": ["STJ. 3ª Turma. REsp 2.142.350-DF", "Súmula 398 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T18:21:29.157504+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=30", "doc_key": "5adc8aba374263a896268ad5c8732b8b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '28dc4353e6f237724f5429b5672663c4aa94335df89b1d514af7dc4f81e3bf60'),
  ('cpiuris2025::8b60bdc9daf66266d81f1f1257fbd00e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ordem Cronológica de Conclusão do Processo', '## Ordem Cronológica de Conclusão do Processo

A ordem cronológica de conclusão do processo é uma regra processual que garante o tratamento isonômico às partes, evitando escolhas arbitrárias. No entanto, não pode ser modificada por negócio jurídico processual, pois isso causaria prejuízos às outras partes e criaria um comércio de modificações.

### Conceitos
- **Isonomia**: Garantia de igual tratamento para as partes
- **Ordem Cronológica**: Regra que determina a ordem em que os processos devem ser concluídos
- **Negócio Jurídico Processual**: Convenção entre as partes para ajustar o procedimento do processo

### Referências legais
- Art. 12, § 2º e § 3º, CPC
- Art. 190, CPC

### Dicas de prova
- Entenda a importância da isonomia na ordem cronológica de conclusão do processo.
- Conheça as limitações do negócio jurídico processual para modificar regras processuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 12, § 2º e § 3º, CPC", "Art. 190, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:22:01.473554+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=31", "doc_key": "8b60bdc9daf66266d81f1f1257fbd00e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9fd73e0082bf2d3df823ed521108a4ab82f0136a5747791a6516d46b13fcee0b'),
  ('cpiuris2025::f744000d8009b49b0f5f75d95de6289b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Exceções ao Princípio do Prazo Processual', '## Exceções ao Princípio do Prazo Processual

Resumo objetivo em 2-5 frases: Art. 12 § 2º estabelece exceções ao princípio do prazo processual, excluindo sentenças proferidas em audiência, julgamentos de recursos repetitivos e decisões com base nos arts. 485 e 932. Além disso, o Art. 190 permite que as partes estipulem mudanças no procedimento antes ou durante o processo.

### Conceitos
- **Audiência**: Reunião do juiz com as partes e testemunhas
- **Prazo processual**: Período determinado para a realização de uma ação processual
- **Exceções ao prazo**: Situações em que o prazo processual não é aplicável
- **Autocomposição**: Concordância entre as partes sobre os termos do processo

### Referências legais
- Art. 12 § 2º da LDP
- Art. 190 da LDP

### Dicas de prova
- Entenda a diferença entre audiência e sentença proferida em audiência
- Conheça as exceções ao prazo processual estabelecidas no Código de Processo Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 12 § 2º da LDP", "Art. 190 da LDP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:22:35.731525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=31", "doc_key": "f744000d8009b49b0f5f75d95de6289b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '54e9bb46e8cb7e4e3d6356cc3041940a8eecff2d54546f487e04173d6d9461ef'),
  ('cpiuris2025::c37dc99270e96d7d5835e21256097ebf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Distinção entre direito processual e direito material, autonomia do direito processual', '## Distinção entre direito processual e direito material, autonomia do direito processual

A questão analisa as assertivas sobre a distinção entre direito processual e direito material, bem como a autonomia do direito processual. O texto destaca que o direito processual é uma ciência autônoma desde a publicação da obra de Oskar Von Bülow em 1868.

### Conceitos
- **Instrumentalismo**: Teoria que considera o direito processual como uma ciência autônoma, mas com relação ao direito material
- **Processualismo**: Teoria que reconhece a autonomia do direito processual e sua relação circular com o direito material
- **Direito Processual Civil**: Instrumento de realização do direito material, considerado uma ciência autônoma

### Referências legais
- Art. 2 da Lei nº 9.318/1996

### Dicas de prova
- Entenda a distinção entre instrumentalismo e processualismo
- Conheça a autonomia do direito processual e sua relação com o direito material', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 2 da Lei nº 9.318/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:23:18.415300+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=32", "doc_key": "c37dc99270e96d7d5835e21256097ebf"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5698b96b7942ca6d845b822b2cca34468fd35aa8208751f5f20e12cf1d297562'),
  ('cpiuris2025::aacd07f056ad7e25fe395b58a32e1aee', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Iniciativa da parte e desenvolvimento do processo', '## Iniciativa da parte e desenvolvimento do processo

O processo começa com iniciativa da parte, mas pode ser impulsionado pelo oficial, exceto em casos previstos pela lei.

### Conceitos
- **iniciativa da parte**: Ato de uma das partes que inicia o processo.
- **impulso oficial**: O Poder Judiciário pode impulsionar o processo, mas apenas em casos previstos pela lei.
- **exceções previstas na lei**: Habilidades do Poder Judiciário para excepcionar a regra geral.
- **julgamento público**: O julgamento dos processos é público e aberto ao público.
- **decisão fundamentada**: A decisão do juiz deve estar fundamentada em argumentos claros e precisos.

### Referências legais
- Art. 5º, LIV da CF
- Súmula 282/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Processo público

### Dicas de prova
- Perguntas sobre iniciativa da parte e desenvolvimento do processo.
- Distinção entre impulso oficial e exceções previstas na lei.
- Importância de julgamentos públicos e decisões fundamentadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, LIV da CF", "Súmula 282/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Processo público"], "confidence": 0.8, "extracted_at": "2026-05-27T18:23:47.566600+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=32", "doc_key": "aacd07f056ad7e25fe395b58a32e1aee"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '24d945a1ab41c6c49ef1d0f6582124af63dd8e650bfc48afeeebe6a8861ab27e'),
  ('cpiuris2025::cd20aebbb383ca7a6bf50710b081128c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processualismo e autonomia do Direito Processual', '## Processualismo e autonomia do Direito Processual

O direito processual passou a ser visto como uma ciência autônoma, com institutos próprios que não se confundem com o direito material.

### Conceitos
- **Processualismo**: Teoria que considera o direito processual como uma ciência autônoma
- **Autonomismo**: Teoria que considera o direito processual como uma ciência autônoma, com institutos próprios
- **Instrumentalismo**: Teoria que considera a relação entre os direitos processuais e materiais

### Referências legais
- Oskar Von Bülow - Teoria dos pressupostos processuais

### Dicas de prova
- Entenda o conceito de processualismo e autonomia do direito processual
- Conheça as teorias instrumentalista, praxista e autonomista', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.33", "page_number": 33, "discipline": "Direito Processual Civil", "legal_refs": ["Oskar Von Bülow - Teoria dos pressupostos processuais"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:24:17.153438+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=33", "doc_key": "cd20aebbb383ca7a6bf50710b081128c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ab51ae13b1208a7a17f98e0de9e91c544b9d976b3b7116a2fe58765b8a306bce'),
  ('cpiuris2025::feda13034fefbe1dbc0d6e4a0ae74687', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Neoprocessualismo e fundamentação das decisões judiciais', '## Neoprocessualismo e fundamentação das decisões judiciais

O neoprocessualismo é uma abordagem que busca a aplicação da Constituição ao processo, com base em doutrina e produção jurídica. As decisões judiciais devem ser fundamentadas, explicando sua relação com a causa ou questão decidida.

### Conceitos
- **Neoprocessualismo**: Abordagem que busca a aplicação da Constituição ao processo
- **Fundamentação das decisões judiciais**: Explicar sua relação com a causa ou questão decidida

### Referências legais
- Art. 489, § 1º, CPC
- Art. 3º, § 1º, CPC

### Dicas de prova
- Entenda a importância da fundamentação nas decisões judiciais
- Conheça as regras para fundamentação das decisões judiciais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 489, § 1º, CPC", "Art. 3º, § 1º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:24:55.199561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=34", "doc_key": "feda13034fefbe1dbc0d6e4a0ae74687"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9eb2e5ba1cf6c105325369f66dfe4362a486a09f67928817f6d71e6649acd60b'),
  ('cpiuris2025::111f2ed4c69bdfab9164b3129efe8cee', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Promoção da solução consensual dos conflitos e comportamento em processo', '## Promoção da solução consensual dos conflitos e comportamento em processo

O Estado promove a solução consensual dos conflitos, enquanto aqueles que participam do processo devem comportar-se de acordo com a boa-fé.

### Conceitos
- **boa-fé**: conduta ética e honesta
- **participação no processo**: involvement em qualquer fase do processo

### Referências legais
- Art. 5º da Constituição Brasileira

### Dicas de prova
- Entenda a importância da solução consensual nos conflitos
- Conheça o conceito de boa-fé no contexto do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º da Constituição Brasileira"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:25:11.518624+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=34", "doc_key": "111f2ed4c69bdfab9164b3129efe8cee"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1edc9ca59b34beef1cf3f934a42347c4c747e2fe39d139d17fb6eeca628f6d4d'),
  ('cpiuris2025::9cea308f29e37da5fdd43559d4504f55', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cooperação entre as partes no processo', '## Cooperação entre as partes no processo

O artigo 6º do CPC estabelece que todos os sujeitos do processo devem cooperar para obter uma decisão de mérito justa e efetiva. O texto discute a não surpresa como princípio fundamental, permitindo que o juiz aplique a lei adequada à solução do conflito, mesmo sem a participação das partes.

### Conceitos
- **Cooperação entre as partes**: A obrigação de todos os sujeitos do processo de trabalhar juntos para obter uma decisão justa e efetiva
- **Princípio da não surpresa**: O princípio que permite ao juiz aplicar a lei adequada à solução do conflito, mesmo sem a participação das partes

### Referências legais
- Art. 6º do CPC/2015
- Art. 10 do CPC/2015

### Jurisprudência
- STJ. 1ª Seção. EDcl nos EREsp 1213143-RS
- RE 123456

### Dicas de prova
- Entenda a importância da cooperação entre as partes no processo
- Conheça o princípio da não surpresa e sua aplicação no CPC
- Diferencie os precedentes vinculantes e persuasivos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.35 (1)", "page_number": 35, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 6º do CPC/2015", "Art. 10 do CPC/2015"], "jurisprudence": ["STJ. 1ª Seção. EDcl nos EREsp 1213143-RS", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T18:25:45.635009+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=35", "doc_key": "9cea308f29e37da5fdd43559d4504f55"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'efa54bff1eaf2295e799d593b023703a5fddfd137815e394be6cff18ff7ea54c'),
  ('cpiuris2025::46d4ec17476428e92b159b100097bf20', 'doutrina', 'cp_iuris', 'Direito Processual Civil — nulidade de algibeira', '## nulidade de algibeira

A ''nulidade de algibeira'' é rejeitada pela jurisprudência do STJ, violando a boa-fé processual e a lealdade. É considerada uma postura que a parte guarda para ser utilizada quando quiser.

### Conceitos
- **boa-fé processual**: dever de as partes e dos participantes do processo
- **lealdade**: dever de as partes e dos participantes do processo
- **nulidade de algibeira**: rejeitada pela jurisprudência do STJ

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- STJ. 3ª Turma. REsp 1372802-RJ
- Súmula N STF

### Dicas de prova
- Entenda a importância da boa-fé processual e da lealdade nas partes.
- Conheça o conceito de ''nulidade de algibeira'' e sua rejeição pela jurisprudência do STJ.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.35 (2)", "page_number": 35, "discipline": "Direito Processual Civil", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["STJ. 3ª Turma. REsp 1372802-RJ", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T18:26:19.520829+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=35", "doc_key": "46d4ec17476428e92b159b100097bf20"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '834cada5a9d2839c77b4e6e6b447f93b9d3946b7c34230285f9af6962a27c4e9'),
  ('cpiuris2025::f57bdeebe65aa8028c159493aa769569', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

A jurisdição é o poder, função e atividade do Estado para dizer e realizar o direito no caso concreto. É desempenhada por uma pessoa investida em concurso público ou de acordo com a Constituição federal.

### Conceitos
- **Substitutividade**: O Estado substitui a vontade das partes para solucionar o conflito
- **Ação constitutiva necessária**: Ações que dependem da chancela do Estado para criar, modificar ou extinguir uma situação jurídica

### Referências legais
- Art. 109 da Constituição Federal

### Dicas de prova
- Entenda a substitutividade e ação constitutiva necessária
- Identifique as características da jurisdição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.37", "page_number": 37, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:26:43.884840+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=37", "doc_key": "f57bdeebe65aa8028c159493aa769569"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2d4926f57043858817ca3223520772bd28f4e5e9b1f5c1852c99a65649428514'),
  ('cpiuris2025::97a958300d319f69360df2c34b6bd4ae', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

A jurisdição precisa ser provocada pelo interessado, pois o juiz não pode agir de ofício. É necessária a ocorrência de um litígio ou conflito de interesses para buscar tutela jurisdicional.

### Conceitos
- **Jurisdição**: A capacidade do Estado de exercer seu poder sobre uma pessoa ou coisas
- **Lide**: O conflito de interesses qualificado por uma pretensão resistida ou insatisfeita
- **Princípio da demanda**: O princípio que estabelece que o juiz não pode agir de ofício, mas precisa ser provocado pelo interessado
- **Princípio da congruência**: O princípio que estabelece a necessidade de uma congruência entre a pretensão do interessado e a decisão do juiz

### Referências legais
- art. 2º do CPC
- art. 492 do CPC
- art. 1.723 do CC

### Dicas de prova
- Entenda a noção de lide e como ela se relaciona com a jurisdição.
- Conheça os princípios da demanda e da congruência.
- A jurisdição é uma atividade criativa do juiz, que extrai a norma jurídica mais justa para o caso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direito Processual Civil", "legal_refs": ["art. 2º do CPC", "art. 492 do CPC", "art. 1.723 do CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:27:20.629381+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=38", "doc_key": "97a958300d319f69360df2c34b6bd4ae"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6773ac73d6c0c3cec4683ce97bfb34b941a4fb5178a778b968a0965b3856b8d5'),
  ('cpiuris2025::7e2d081c743c9b7afc15ece5f27eebf6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Definitividade e Terceiro Imparcial', '## Definitividade e Terceiro Imparcial

A definitividade se revela pela aptidão da decisão de mérito para tornar-se imutável, característica exclusiva da jurisdição. O terceiro imparcial é o juiz competente que exerce a jurisdição.

### Conceitos
- **Definitividade**: Característica da jurisdição que torna a decisão de mérito imutável
- **Terceiro Imparcial**: O juiz competente que exerce a jurisdição
- **Jurisdição**: Instituição do Estado que tem como função resolver conflitos
- **Competência**: A capacidade do juiz de decidir sobre um caso específico

### Referências legais
- Art. 1.723 CC

### Dicas de prova
- Entenda a diferença entre definitividade e coisa julgada material
- Identifique o terceiro imparcial na jurisdição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.723 CC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:27:55.554030+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=38", "doc_key": "7e2d081c743c9b7afc15ece5f27eebf6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f3581567cbf65a636aa1c2143d18fde06d240aba1604285f704f911c3e0180e9'),
  ('cpiuris2025::0ecc0429002a9e4ecfff0d9ee765db5b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípios da Jurisdição', '## Princípios da Jurisdição

A jurisdição somente pode ser exercida por juiz investido, com a aprovação em concurso público. A violação ao princípio da investidura atinge a existência do processo.

### Conceitos
- **Investidura**: A função de juiz somente pode ser exercida por aquele que foi aprovado em concurso público.
- **Princípio da Investidura**: Fundamento para o exercício da função jurisdicional do Estado
- **Territorialidade**: A jurisdição é uma e exercida em todo o território nacional, com limites estabelecidos pela Constituição e leis.
- **Indelegabilidade**: O juiz não pode delegar a outrem o exercício da função jurisdicional

### Referências legais
- Art. 102, I, m da CF/88
- Art. 237, I do CPC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da investidura para o exercício da função jurisdicional
- Conheça os limites da competência e a territorialidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 102, I, m da CF/88", "Art. 237, I do CPC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T18:28:29.782124+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=39", "doc_key": "0ecc0429002a9e4ecfff0d9ee765db5b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8c72e99b928e9610777d1f69c802b0c4cef82b391b6624d5d45b4cb0dc2cdc5f'),
  ('cpiuris2025::68904fa4d69c5dcafbf9303960691604', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Carta Precatória e Princípio da Indelegabilidade', '## Carta Precatória e Princípio da Indelegabilidade

A carta precatória não é uma mitigação ao princípio da indelegabilidade, pois a sua expedição decorre do fato de que o juiz deprecante não pode exercer jurisdição no estado onde a testemunha reside.

### Conceitos
- **Carta Precatória**: instrumento processual que autoriza o juiz deprecante a exercer jurisdição em outro estado
- **Princípio da Indelegabilidade**: princípio que estabelece que o juiz deve exercer sua função jurisdicional apenas na sua competência territorial

### Referências legais
- Art. 237, III do CPC

### Dicas de prova
- Entenda a diferença entre carta precatória e delegação de poderes
- Lembre-se de que o juiz não pode exercer jurisdição em outro estado sem a expedição de uma carta precatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 237, III do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:28:53.551337+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=39", "doc_key": "68904fa4d69c5dcafbf9303960691604"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ae41bc6c23a84ecd5f4bf24032f37cbcfab3a18fb85fd38216b72144f3d182fa'),
  ('cpiuris2025::86898acaf39d92bb2d316e82c53eaf25', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

A jurisdição é exercida pelo STF em todo o território nacional, especialmente na carta de ordem. A jurisdição contenciosa pressupõe litígio, enquanto a jurisdição voluntária não há litígio, mas chancela situação jurídica.

### Conceitos
- **Jurisdição Contenciosa**: Pressupõe litígio
- **Jurisdição Voluntária**: Não pressupõe litígio, mas chancela situação jurídica
- **Princípio da Inevitabilidade**: A jurisdição é imperativa e inevitável
- **Princípio da Inafastabilidade da Jurisdição**: O Poder Judiciário tem acesso à justiça
- **Princípio do Juiz Natural**: O juiz natural é o que decide sobre a competência

### Referências legais
- Art. 723, parágrafo único, CPC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Diferenciar entre jurisdição contenciosa e voluntária
- Entender o princípio da inevitabilidade e da inafastabilidade da jurisdição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.40", "page_number": 40, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 723, parágrafo único, CPC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T18:29:40.356901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=40", "doc_key": "86898acaf39d92bb2d316e82c53eaf25"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0c75ab3372298a41af0a170c8dc63d4509c1c8ca18dd15515564da966df6692a'),
  ('cpiuris2025::0be2f6f0954636df3ace4bc2b5c74a0e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

O CPC/2015 instituiu um modelo ''multiportas'' para a pacificação dos conflitos, incluindo meios alternativos de solução dos conflitos como conciliação e mediação.

### Conceitos
- **Autotutela**: Sacrifício de uma pretensão alheia por uma pretensão própria
- **Autocomposição**: Sacrifício mútuo de pretensões, podendo ser total ou parcial, sem o uso da força
- **Mediação**: Meio adequado de resolução do conflito exercido por um terceiro imparcial

### Referências legais
- Art. 334 do CPC/2015
- Art. 1.210, § 1º do CC
- Art. 1.219 do CC
- Art. 9º da CF/88

### Dicas de prova
- Entenda a diferença entre autotutela e autocomposição
- Conheça as hipóteses de autocomposição previstas no art. 487, inciso III do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.41", "page_number": 41, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 334 do CPC/2015", "Art. 1.210, § 1º do CC", "Art. 1.219 do CC", "Art. 9º da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:30:14.105530+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=41", "doc_key": "0be2f6f0954636df3ace4bc2b5c74a0e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6513203e4770c0ace5a2c6a1c68a340c431ef07a40ab52b669fc4632f2635225'),
  ('cpiuris2025::206cee52013b3445c688c87c232930a1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Mediação em Conflitos de Direitos Disponíveis e Indisponíveis', '## Mediação em Conflitos de Direitos Disponíveis e Indisponíveis

A mediação é um meio de resolução de conflitos que pode ser aplicado a direitos disponíveis ou indisponíveis, com ou sem transação. A Lei nº 13.140/2015 estabelece os princípios para a mediação, incluindo imparcialidade, isonomia e busca do consenso.

### Conceitos
- **Mediação**: Méodo de resolução de conflitos que envolve a negociação entre as partes
- **Direitos Disponíveis**: Direitos que podem ser cedidos ou transferidos por meio de um ato jurídico
- **Direitos Indisponíveis**: Direitos que não podem ser cedidos ou transferidos por meio de um ato jurídico
- **Transação**: Negociação entre as partes para alcançar uma solução mútua
- **Parcialidade**: Orientação da mediação em relação a um aspecto específico do conflito

### Referências legais
- Art. 2º, Lei n.º 13.140/2015
- Art. 3º, § 1º, Lei n.º 13.140/2015
- Art. 32, § 1º, Lei n.º 13.140/2015

### Dicas de prova
- Entenda a diferença entre direitos disponíveis e indisponíveis
- Conheça os princípios da mediação estabelecidos pela Lei nº 13.140/2015
- Avalie a importância da parcialidade na mediação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.42", "page_number": 42, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 2º, Lei n.º 13.140/2015", "Art. 3º, § 1º, Lei n.º 13.140/2015", "Art. 32, § 1º, Lei n.º 13.140/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:31:00.964891+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=42", "doc_key": "206cee52013b3445c688c87c232930a1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a82449c979543949170a241c9baa827ece931fc49f8e6521e89da949a7f9e2f6'),
  ('cpiuris2025::033e5eebb6a5209251f0302524a0106f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Conciliação e Arbitragem', '## Conciliação e Arbitragem

Discute-se as diferenças entre conciliação e arbitragem, bem como a necessidade de convenção para resolver litígios pela arbitragem.

### Conceitos
- **Conciliação**: Meio autocompositivo em que um terceiro imparcial auxilia as partes na solução do conflito.
- **Arbitragem**: Meio adequado de solução do conflito por meio do qual um terceiro imparcial (árbitro) será o juiz do caso.
- **Cláusula compromissória**: Convenção que as partes em um contrato comprometem-se a submeter os litígios que possam vir a surgir relativamente a tal contrato à arbitragem.
- **Compromisso arbitral**: Convenção que as partes submetem um litígio à arbitragem de uma ou mais pessoas.

### Referências legais
- Art. 165, § 2º do CPC
- Art. 4º da Lei n.º 9.307/1996

### Dicas de prova
- Entenda a diferença entre conciliação e arbitragem.
- Conheça as condições para a formação de uma convenção de arbitragem.
- Aprenda a distinguir entre cláusula compromissória e compromisso arbitral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 165, § 2º do CPC", "Art. 4º da Lei n.º 9.307/1996"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:31:52.692028+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=43", "doc_key": "033e5eebb6a5209251f0302524a0106f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bb6b897dc12527252c3dcb9826275fb9c562287a97605e1da9a57bedf7b86161'),
  ('cpiuris2025::0ea119ef67226e1d4da85f1effe36e4c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Arbitragem', '## Arbitragem

A arbitragem é celebrada por termo nos autos, perante o juízo ou tribunal, e pode ser de direito ou de equidade. As partes podem escolher as regras de direito a serem aplicadas e convencionar que a arbitragem se realize com base em princípios gerais de direito, usos e costumes e regras internacionais de comércio.

### Conceitos
- **Cláusula compromissória**: Disposição do contrato que estabelece a arbitragem como meio de resolução das disputas
- **Arbitragem de direito**: Aplicação das regras de direito para resolver as disputas
- **Arbitragem de equidade**: Aplicação dos princípios gerais de direito e da justiça para resolver as disputas
- **Cláusula compromissória cheia**: Disposição do contrato que estabelece todas as questões procedimentais, inclusive a escolha do árbitro

### Referências legais
- Art. 9º, § 1º, Lei n.º 9.307/1996

### Jurisprudência
- REsp 1.389.763/PR
- Súmula 287/STJ

### Dicas de prova
- Entenda a diferença entre arbitragem de direito e equidade
- Conheça o conceito de cláusula compromissória cheia e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 9º, § 1º, Lei n.º 9.307/1996"], "jurisprudence": ["REsp 1.389.763/PR", "Súmula 287/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T18:32:26.832902+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=43", "doc_key": "0ea119ef67226e1d4da85f1effe36e4c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6ca1808a1ad19061e20331473dc79c132e9b50ecadb54bdb311b07f5f308e4c4'),
  ('cpiuris2025::b5351de575cc21e9f73c3cd772ea5c5e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência na Arbitragem', '## Jurisdição e Competência na Arbitragem

A arbitragem é admissível no âmbito da Fazenda Pública, respeitando o princípio da publicidade. A autoridade competente para celebrar a convenção de arbitragem é a mesma que a do órgão administrativo. A arbitragem envolvendo a administração pública é sempre de direito e respeita a publicidade.

### Conceitos
- **Competência**: A capacidade do juiz ou tribunal de decidir sobre um caso
- **Arbitragem**: Método alternativo de resolução de disputas, fora do sistema judicial
- **Fazenda Pública**: Administração pública direta e indireta
- **Princípio da Publicidade**: O direito de todos os cidadãos ter acesso a informações públicas
- **Cláusula Compromissória**: Cláusula no contrato que estabelece a arbitragem como meio de resolução de disputas

### Referências legais
- Art. 1º, § 1º da Lei n.º 9.307/1996
- Art. 8º, parágrafo único da Lei n.º 9.307/1996
- Súmula N do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a competência da arbitragem em casos de Fazenda Pública

### Dicas de prova
- Distinção entre a competência do Juízo e a competência do órgão administrativo
- Importância do princípio da publicidade na arbitragem envolvendo a administração pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1º, § 1º da Lei n.º 9.307/1996", "Art. 8º, parágrafo único da Lei n.º 9.307/1996", "Súmula N do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a competência da arbitragem em casos de Fazenda Pública"], "confidence": 0.8, "extracted_at": "2026-05-27T18:33:09.974623+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=44", "doc_key": "b5351de575cc21e9f73c3cd772ea5c5e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '906a4a76cf908ce1611547d5bdf6e27c12441749c1ac28c0ecd862a3ef61a40c'),
  ('cpiuris2025::5388ec255c4ee3cc6cfff2c2aad22b67', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litígios relacionados a obras e contratos', '## Litígios relacionados a obras e contratos

Resumo objetivo: A existência de materiais geológicos no solo que exigem técnicas de extração diferentes pode levar a litígios, paralisar a obra e afetar o contrato.

### Conceitos
- **Litígio**: Disputa entre as partes de uma obra
- **Paralisação da obra**: Interrupção temporária das atividades de construção
- **Revisão do contrato**: Ajuste ou alteração do acordo celebrado pelas partes
- **Arbitragem**: Método de resolução de disputas fora do sistema judiciário

### Referências legais
- Art. 1.236, Código Civil
- ...

### Jurisprudência
- REsp 1.550.260/RS

### Dicas de prova
- Entenda a importância da clareza nos contratos de obras
- Conheça as possíveis consequências de uma disputa sobre a execução de um projeto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1.236, Código Civil", "..."], "jurisprudence": ["REsp 1.550.260/RS"], "confidence": 0.8, "extracted_at": "2026-05-27T18:33:44.525556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=44", "doc_key": "5388ec255c4ee3cc6cfff2c2aad22b67"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '40f8fe488f3f958549cd72b8cbbab01881a80225f38618cc15149fd9078b5fb3'),
  ('cpiuris2025::64550e82141d12667c804712408ac767', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência - Dispute Resolution Board', '## Jurisdição e Competência - Dispute Resolution Board

O dispute resolution board é uma figura jurídica que busca resolver conflitos entre as partes por meio de um comitê de resolução de disputas. A adoção do método é permitida pelo art. 3º, § 2º, do CPC/2015 e tem origem no direito norte-americano.

### Conceitos
- **Dispute Resolution Board**: Comitê de resolução de disputas que busca resolver conflitos entre as partes por meio de um comitê
- **Jurisdição**: Poder do Estado para decidir sobre uma questão ou caso
- **Competência**: A capacidade do juiz ou tribunal de julgar um determinado caso
- **Método extrajudicial**: Método de resolução de conflitos que não envolve o Poder Judiciário
- **Solução consensual**: Resolução de um conflito por meio de acordo entre as partes

### Referências legais
- Art. 3º, § 2º, do CPC/2015

### Jurisprudência
- Enunciado 49 - I Jornada sobre Prevenção e Solução Extrajudicial de Litígios
- Enunciado 76 - I Jornada sobre Prevenção e Solução Extrajudicial de Litígios
- Enunciado 80 - I Jornada sobre Prevenção e Solução Extrajudicial de Litígios

### Dicas de prova
- Entenda a diferença entre os diferentes tipos de dispute boards (review, adjudication e combined).
- Conheça as regras para a adoção do método extrajudicial de resolução de conflitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 3º, § 2º, do CPC/2015"], "jurisprudence": ["Enunciado 49 - I Jornada sobre Prevenção e Solução Extrajudicial de Litígios", "Enunciado 76 - I Jornada sobre Prevenção e Solução Extrajudicial de Litígios", "Enunciado 80 - I Jornada sobre Prevenção e Solução Extrajudicial de Litígios"], "confidence": 0.8, "extracted_at": "2026-05-27T18:34:27.671992+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=45", "doc_key": "64550e82141d12667c804712408ac767"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7f8d5f974d372a5170a1c0a326c4107d0a9430ad3d34363f2f5e8099afbd7ec9'),
  ('cpiuris2025::2b36bc36bbb9dd232f35d3281cfcff99', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Meios Alternativos de Prevenção e Resolução de Controvérsias em Licitações', '## Meios Alternativos de Prevenção e Resolução de Controvérsias em Licitações

A nova lei de licitações prevê meios alternativos para resolução de conflitos, como conciliação, mediação, comitês de resolução de disputas e arbitragem, com critérios isonômicos e transparentes.

### Conceitos
- **Conciliação**: Negociação direta entre as partes para resolver o conflito
- **Mediação**: Intervenção de um terceiro neutro para facilitar a negociação
- **Comitê de Resolução de Disputas**: Grupo de pessoas designadas para resolver disputas de forma independente
- **Arbitragem**: Resolução de conflitos por meio de um juiz ou comissão de especialistas

### Referências legais
- Art. 151 da Lei nº 14.133/2021

### Dicas de prova
- Entenda a diferença entre conciliação e mediação
- Conheça os critérios isonômicos para escolha dos árbitros
- Aprenda sobre o papel do comitê de resolução de disputas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 151 da Lei nº 14.133/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:34:56.249761+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=45", "doc_key": "2b36bc36bbb9dd232f35d3281cfcff99"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd6462725bcc9dfba8cd8c41372e53033f12292c103deaacb0bff67cf3be3978f'),
  ('cpiuris2025::32a9d3aba188f28d17965003232bb9a6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Limites da jurisdição nacional', '## Limites da jurisdição nacional

A jurisdição nacional pode ser concorrente ou exclusiva, dependendo do caso. A competência concorrente é estabelecida nos arts. 21 e 22 do CPC, enquanto o art. 23 elenca as hipóteses de competência exclusiva da jurisdição brasileira.

### Conceitos
- **Competência concorrente**: A competência que permite que a autoridade judiciária brasileira e estrangeira tenham competência para a mesma causa.
- **Competência exclusiva**: A competência que é exclusiva da jurisdição nacional, sem qualquer concorrência com a jurisdição estrangeira.
- **Domicílio no Brasil**: Pessoa jurídica ou física que tem sua sede ou residência no Brasil.
- **Obrigação no Brasil**: Fato ou ato que deve ser cumprido dentro do território nacional.

### Referências legais
- Art. 21 do CPC
- Art. 22 do CPC
- Art. 23 do CPC

### Dicas de prova
- Entenda a distinção entre competência concorrente e exclusiva.
- Conheça as hipóteses de competência concorrente e exclusiva estabelecidas nos arts. 21, 22 e 23 do CPC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 21 do CPC", "Art. 22 do CPC", "Art. 23 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:35:42.608731+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=46", "doc_key": "32a9d3aba188f28d17965003232bb9a6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'da0be66b084bd94d4c0096cc578de28991aa0870aa1eb8e28fad575c9cc90b27'),
  ('cpiuris2025::2e9fb4ab24b67849ae1da87b8662ac94', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Homologação de decisões estrangeiras no Brasil', '## Homologação de decisões estrangeiras no Brasil

A competência para homologar sentenças estrangeiras passou a ser do STJ, com o objetivo de verificar a forma e a competência, mas não o mérito.

### Conceitos
- **Homologação**: Processo pelo qual se confirma a validade de uma decisão estrangeira no Brasil.
- **STJ**: Superior Tribunal de Justiça, que tem competência para homologar sentenças estrangeiras.
- **Mérito**: A parte substancial da lide, que é objeto de julgamento pelo juiz.
- **Competência exclusiva**: O caso em que a sentença estrangeira não pode ser homologada porque não tem aptidão para produzir efeitos no Brasil.
- **Ordem pública**: A ordem social e política do país, que deve ser respeitada pelo Estado.
- **Autenticidade**: A verificação se a sentença estrangeira foi emitida de acordo com as regras legais aplicáveis.
- **Forma**: O procedimento ou forma como a sentença estrangeira foi emitida.
- **Deliberação**: A decisão do juiz sobre a homologação da sentença estrangeira.

### Referências legais
- Art. 103-A do Código de Processo Civil
- Emenda Constitucional n.º 45/2004

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a competência para homologar sentenças estrangeiras e sobre as limitações do STJ.
- Verifique se o STJ analisa apenas a forma e a competência, e não o mérito da sentença estrangeira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 103-A do Código de Processo Civil", "Emenda Constitucional n.º 45/2004"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:36:20.594565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=46", "doc_key": "2e9fb4ab24b67849ae1da87b8662ac94"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'be6cbcb39e720f9aff74bc77b1d584f91abf91cfd5772330daabe66fc0985d9a'),
  ('cpiuris2025::1964bf4bfd8c25d39eca5081637f9e81', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

A homologação da sentença estrangeira é necessária para que o título executivo seja considerado judicial, e não a sentença estrangeira em si. A decisão homologatória é título executivo e deve ser cumprida perante a Justiça Federal de 1º grau.

### Conceitos
- **Homologação**: Processo de reconhecimento da sentença estrangeira como válida no Brasil
- **Título Executivo Judicial**: Decisão que tem força de título executivo e deve ser cumprida perante a Justiça Federal de 1º grau
- **Competência Federal**: Jurisdição da Justiça Federal em casos específicos, como homologação de sentença estrangeira

### Referências legais
- Art. 964 do CPC
- Súmula 347/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Homologação de decisão estrangeira

### Dicas de prova
- Diferenciar entre homologação e cumprimento de decisão
- Entender a competência federal em casos específicos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 964 do CPC", "Súmula 347/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Homologação de decisão estrangeira"], "confidence": 0.8, "extracted_at": "2026-05-27T18:36:52.277623+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=47", "doc_key": "1964bf4bfd8c25d39eca5081637f9e81"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f35abb4b8048ff5bb09356719e2cb43f4ec74c574f32fed8ff730607070dc659'),
  ('cpiuris2025::097644d2f375fbbf9651c514481c3ab2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Auxílio Direto em Medidas Extrajudiciais', '## Auxílio Direto em Medidas Extrajudiciais

Medida judicial ou extrajudicial não proibida pela lei brasileira pode ser objeto de auxílio direto se solicitada por autoridade estrangeira, respeitando a legislação do país estrangeiro.

### Conceitos
- **Auxílio Direto**: Solicitação de medidas extrajudiciais por autoridade estrangeira
- **Medida Extrajudicial**: Atividade realizada fora do processo judicial
- **Lex Diligentiae**: Lei que regula a diligência solicitada

### Referências legais
- Art. 84, § 4º do CPC/2015
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre auxílio direto e auxílio indireto
- Importância da legislação do país estrangeiro responsável pela diligência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 84, § 4º do CPC/2015", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:37:24.998464+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=47", "doc_key": "097644d2f375fbbf9651c514481c3ab2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b68a50eb0307425a49e2bc6d03d1760469e17d454c24ed3cee3975d0dbcf5959'),
  ('cpiuris2025::86103ee0ecfaa574f7fe4cd676993cee', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

A jurisdição e competência em execução de diligências internacionais são reguladas pelo art. 30 do CPC, que estabelece os objetos do auxílio direto e a competência para apreciar pedidos passivos.

### Conceitos
- **Auxílio Direto**: Medida judicial ou extrajudicial adotada em processo estrangeiro, com o objetivo de obter informações ou provas
- **Carta Rogatória**: Pedidos rogatórios enviados por um Estado para outro, com o objetivo de obter informações ou provas
- **Competência Federal**: A competência do juiz federal para apreciar pedidos passivos de auxílio direto

### Referências legais
- Art. 30 do CPC
- Art. 34 do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre auxílio direto e carta rogatória
- Conheça a competência federal para apreciar pedidos passivos de auxílio direto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 30 do CPC", "Art. 34 do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T18:37:54.489198+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=48", "doc_key": "86103ee0ecfaa574f7fe4cd676993cee"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f5c23a932e5411c5e04bc068dfbb9956bb382a09121bad845d351c11133a5be7'),
  ('cpiuris2025::f546d5a54162f1dce0ca5909340d4f79', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Carta Rogatória no STJ', '## Carta Rogatória no STJ

O procedimento da carta rogatória no STJ é de jurisdição contenciosa, com garantias do devido processo legal. A defesa deve se restringir à discussão sobre os requisitos para o pronunciamento judicial estrangeiro produzir efeitos no Brasil.

### Conceitos
- **Carta Rogatória**: instrumento processual que permite a coleta de provas em outro país
- **Jurisdição Contenciosa**: exercício do poder jurisdicional para resolver disputas entre partes
- **Devido Processo Legal**: garantia de que as partes tenham a oportunidade de defender seus interesses
- **Competência**: espazio em que o juiz exerce seu poder jurisdicional

### Referências legais
- Art. 26 do CPC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre jurisdição contenciosa e de competência.
- Conheça os requisitos para o pronunciamento judicial estrangeiro produzir efeitos no Brasil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 26 do CPC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:38:20.289673+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=48", "doc_key": "f546d5a54162f1dce0ca5909340d4f79"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ecaa0f3df5746f37015146f7da6763230ce376d562518637dff9eed2baec86b7'),
  ('cpiuris2025::39644c721af5c237c6ea80eb4ed5e5a2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência e Jurisdição', '## Competência e Jurisdição

A competência tem natureza jurídica de pressuposto processual de validade, sendo absoluta ou relativa, com regras que preservam o interesse público ou particular das partes.

### Conceitos
- **Competência Absoluta**: Pressuposto processual que preserva o interesse público
- **Competência Relativa**: Pressuposto processual que preserva o interesse particular das partes
- **Reconhecimento de Incompetência**: A incompetência pode ser reconhecida de ofício pelo juiz, exceto em casos específicos
- **Alteração da Competência**: A competência absoluta não pode ser alterada pela vontade das partes, mas a relativa pode
- **Conexão e Continência**: A competência absoluta não pode ser modificada por regras de conexão ou continência

### Referências legais
- Art. 62 do CPC
- Súmula 33 do STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da competência absoluta e relativa

### Dicas de prova
- Entenda a distinção entre competência absoluta e relativa
- Conheça as regras de reconhecimento, alteração e conexão/continência da competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.49", "page_number": 49, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 62 do CPC", "Súmula 33 do STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da competência absoluta e relativa"], "confidence": 0.8, "extracted_at": "2026-05-27T18:39:05.743517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=49", "doc_key": "39644c721af5c237c6ea80eb4ed5e5a2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3abf34277e199ae0b1cd5e535aa55caa1fe84bbaf6697f2f621869ddcb9c19dc'),
  ('cpiuris2025::c997470335dd1c6594a3220403843c05', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Incompetência Jurisdicional', '## Incompetência Jurisdicional

A incompetência jurisdicional é alegada como questão preliminar de contestação e pode ser arguida pelo réu ou pelo Ministério Público. A incompetência absoluta é declarada de ofício pelo juiz, enquanto a relativa deve ser alegada pelo réu. O princípio da kompetenz-kompetenz permite ao juiz declarar sua própria incompetência.

### Conceitos
- **Incompetência Jurisdicional**: Alegação de que o juiz não tem competência para julgar um caso
- **Competência Absoluta**: O juiz é absolutamente incompetente para julgar um caso, e os autos são remetidos ao juízo competente
- **Competência Relativa**: O juiz é relativamente incompetente para julgar um caso, e a alegação deve ser feita pelo réu
- **Princípio da Kompetenz-kompetenz**: Princípio que permite ao juiz declarar sua própria incompetência ou a do outro juiz

### Referências legais
- Art. 64, §§ 3º e 4º, do CPC
- Art. 5º, LIV, da CF/88
- Art. 8º, parágrafo único, do Código de Processo Civil

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a diferença entre competência absoluta e relativa
- Conheça o princípio da kompetenz-kompetenz e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 64, §§ 3º e 4º, do CPC", "Art. 5º, LIV, da CF/88", "Art. 8º, parágrafo único, do Código de Processo Civil"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T18:39:46.888503+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=50", "doc_key": "c997470335dd1c6594a3220403843c05"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '25b5815d9668acfb68d5779736a600407d17e006b671da1e8a9cdaff3ecf9215'),
  ('cpiuris2025::0b7a73ceb45e70c7d4b72cafddd96c07', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência e Legitidade na Arbitragem', '## Competência e Legitidade na Arbitragem

A competência do Juízo arbitral é reconhecida pela Lei n.º 9.307/1996, com primazia sobre o Poder Judiciário. A instituição arbitral não possui legitimidade para ser integrada como polo passivo na ação de anulação.

### Conceitos
- **Competência**: A capacidade do Juízo de julgar uma causa
- **Legitimidade**: O direito de uma parte ter participação no processo
- **Arbitragem**: Um meio de resolução de disputas fora do Poder Judiciário
- **Convenção de Arbitragem**: Acordo entre as partes para resolver disputas por arbitramento

### Referências legais
- Art. 8º da Lei n.º 9.307/1996

### Jurisprudência
- STJ, INF 622 – REsp 1.550.260-RS
- STJ, INF 613 - REsp 1.433.940-MG

### Dicas de prova
- Destacar a competência do Juízo arbitral
- Entender a legitimidade da instituição arbitral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 8º da Lei n.º 9.307/1996"], "jurisprudence": ["STJ, INF 622 – REsp 1.550.260-RS", "STJ, INF 613 - REsp 1.433.940-MG"], "confidence": 0.8, "extracted_at": "2026-05-27T18:40:14.211146+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=50", "doc_key": "0b7a73ceb45e70c7d4b72cafddd96c07"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c1ecd4a136962c83435f207e510e96415925f8c32dcbccdb94e48e6067df0213'),
  ('cpiuris2025::9439b2281b07d39e7703d2798d1f86fd', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio da Perpetuatio Jurisdictionis', '## Princípio da Perpetuatio Jurisdictionis

A competência é determinada no momento do registro ou da distribuição da petição inicial, e qualquer alteração superveniente não gera deslocamento da competência, salvo em casos de supressão de órgão judiciário ou alteração absoluta.

### Conceitos
- **Perpetuatio Jurisdictionis**: Princípio que determina a competência no momento do registro ou da distribuição da petição inicial
- **Competência Absoluta**: Competência absoluta é aquela que não pode ser alterada por meio de modificações do estado de fato ou direito
- **Competência Relativa**: Competência relativa é aquela que pode ser alterada por meio de modificações do estado de fato ou direito

### Referências legais
- Art. 43, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o princípio da perpetuatio jurisdictionis e como ele afeta a competência no processo
- Diferencie entre competência absoluta e relativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 43, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:40:55.523082+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=51", "doc_key": "9439b2281b07d39e7703d2798d1f86fd"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '369e966b35a156b7c2931c3646b6a826d39975b274121cb94c390ab6713eb3ea'),
  ('cpiuris2025::df6c2b261d0b65ade719fb13745a3041', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência Jurisdicional e Perpetuatio Jurisdictionis', '## Competência Jurisdicional e Perpetuatio Jurisdictionis

A competência jurisdicional permanece no juízo de origem, mesmo após mudanças no estado de direito, desde que não haja supressão de órgão judiciário ou alteração da competência absoluta.

### Conceitos
- **Competência Jurisdicional**: A capacidade do juiz de decidir sobre um caso
- **Perpetuatio Jurisdictionis**: O princípio que determina a continuidade da competência jurisdicional após mudanças no estado de direito
- **Supressão de Órgão Judiciário**: A extinção de um órgão judiciário e a transferência dos processos para outro órgão
- **Alteração da Competência Absoluta**: Mudança na competência absoluta de um juiz ou tribunal

### Referências legais
- Art. 43 do CPC

### Jurisprudência
- Súmula 343 STF

### Dicas de prova
- Entenda a diferença entre supressão e alteração de competência
- Conheça as exceções à perpetuatio jurisdictionis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 43 do CPC"], "jurisprudence": ["Súmula 343 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T18:41:22.952088+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=51", "doc_key": "df6c2b261d0b65ade719fb13745a3041"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3f515cb1a882e7982a4a22378be2b2cd7a17a902bdac293c0f4a4e16d49e79ff'),
  ('cpiuris2025::d89b635dbf876290cf6bc7088d634032', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência e Jurisdição', '## Competência e Jurisdição

A competência não se limita à competência abstrata, mas também deve considerar a conveniência e adequação do juízo para processar e julgar a causa.

### Conceitos
- **Competência Natural**: O princípio de que o órgão judicial deve ser previamente constituído e individualizado como aquele objetiva e abstratamente competente para a causa.
- **Competência Adequada**: A ideia de existir um forum non conveniens, ou seja, um juízo que não é conveniente e inadequado para processar e julgar a causa.
- **Forum Non Conveniens**: Um juízo que, embora competente, é inadequado ou inconveniente para processar e julgar a causa.

### Referências legais
- Art. 43 do CPC

### Jurisprudência
- RE 123456
- Súmula 345 do STJ

### Dicas de prova
- Entenda a distinção entre competência abstrata e conveniência do juízo.
- Conheça o conceito de forum non conveniens e como ele se relaciona com a competência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 43 do CPC"], "jurisprudence": ["RE 123456", "Súmula 345 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T18:41:54.953332+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=52", "doc_key": "d89b635dbf876290cf6bc7088d634032"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '205ad540bc98b5355770fb8bcaccc8a83d9710eb44dc1aee0a2d01ec6e47ba79'),
  ('cpiuris2025::d3300b4d1766562d6e2822c048783e1b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Perpetuatio jurisdictionis e alteração da competência absoluta após a sentença', '## Perpetuatio jurisdictionis e alteração da competência absoluta após a sentença

Regras para alteração de competência absoluta após a prolação da sentença e desmembramento de comarca.

### Conceitos
- **Competência absoluta**: competência do juiz que tem jurisdição natural sobre o feito
- **Perpetuatio jurisdictionis**: princípio que determina a competência do juiz após a prolação da sentença
- **Remessa dos autos**: envio dos autos para outro juízo competente
- **Desmembramento de comarca**: divisão de uma comarca em duas ou mais comarcas

### Referências legais
- Art. 109, § 3º do CPC/2019
- Súmula 242 STJ

### Jurisprudência
- RE 123456
- Desmembramento de comarca

### Dicas de prova
- Entenda a regra de perpetuatio jurisdictionis e sua aplicação prática.
- Conheça as exceções à regra de remessa dos autos após alteração da competência absoluta.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.52 (2)", "page_number": 52, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109, § 3º do CPC/2019", "Súmula 242 STJ"], "jurisprudence": ["RE 123456", "Desmembramento de comarca"], "confidence": 0.8, "extracted_at": "2026-05-27T18:42:32.604711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=52", "doc_key": "d3300b4d1766562d6e2822c048783e1b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2ff99714dabfb5eeeb3b9636cfe738f0ab8762b8303952d6fa7b2ef97f9689c3'),
  ('cpiuris2025::b57b0bb92b6f59734e2ecf7a8c749758', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

A jurisdição e competência são reguladas pelo CPC, com regras de competência absoluta e relativa. A perpetuatio jurisdictionis é aplicada se o desmembramento das comarcas não alterar a competência absoluta.

### Conceitos
- **Perpetuatio Jurisdictionis**: aplicação da regra de competência absoluta em casos de mudança de comarca
- **Competência Absoluta**: competência do juízo que tem jurisdição sobre a causa de pedir
- **Competência Relativa**: competência do juízo que tem jurisdição sobre o local onde se encontra a parte ou objeto da ação
- **Princípio do Juízo Imediato**: aplicação da regra de competência absoluta em casos de tutela dos interesses de criança e adolescente

### Referências legais
- Art. 47 do CPC
- Art. 147 da Lei n.º 8.069/1990

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre competência absoluta e relativa.
- Conheça o princípio do juízo imediato e sua aplicação em casos de tutela dos interesses de criança e adolescente.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.53", "page_number": 53, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 47 do CPC", "Art. 147 da Lei n.º 8.069/1990"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:43:06.713489+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=53", "doc_key": "b57b0bb92b6f59734e2ecf7a8c749758"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a6f3da839a4c3ce8911af6753924a15abfeb91de2b5db13d61ff2e016e22c24b'),
  ('cpiuris2025::02a60d66c4c615386ab8c11c2f55f672', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência em razão do valor da causa', '## Competência em razão do valor da causa

A competência pode ser determinada com base no valor da causa, sendo um critério funcional que define a competência absoluta ou relativa dos juizados especiais cíveis e estaduais.

### Conceitos
- **Competência absoluta**: A competência absoluta é quando o órgão jurisdicional é competente independentemente do valor da causa.
- **Competência relativa**: A competência relativa é quando a competência depende do valor da causa.
- **Juizados Especiais Cíveis**: São juízos cíveis que têm competência para as ações de menor complexidade cujo valor da causa não exceda 40 (quarenta) salários mínimos.
- **Juizados Especiais Estaduais**: São juízos especiais estaduais que têm competência para as ações de menor complexidade cujo valor da causa não exceda 40 (quarenta) salários mínimos.
- **Competência absoluta nos Juizados Especiais Federais e Fazendeiros**: A competência é absoluta em ambos os casos, independentemente do valor da causa.

### Referências legais
- Art. 3º, I, da Lei n.º 9.099/1995

### Dicas de prova
- Destacar a diferença entre competência absoluta e relativa
- Entender o critério funcional de valor da causa
- Conhecer as regras específicas dos Juizados Especiais Cíveis, Estaduais, Federais e Fazendeiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 3º, I, da Lei n.º 9.099/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:43:47.191458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=54", "doc_key": "02a60d66c4c615386ab8c11c2f55f672"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1a5278d864148bf0949f14d203ea04908c9354bfd17a0e88e675aed19c428963'),
  ('cpiuris2025::b10a97e41e7f9d96902f7bc9c3bc5352', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência dos Tribunais', '## Competência dos Tribunais

O relator submeterá a questão à turma ou câmara competente, após ouvir as partes e o Ministério Público.

### Conceitos
- **Competência dos Tribunais**: A capacidade do tribunal de julgar um caso
- **Turma/Câmara**: Unidade composta por juízes que processa e resolve os casos
- **Órgão Especial**: Comissão formada por juízes especializados em uma área específica

### Referências legais
- Art. 93 da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a competência dos tribunais e as diferenças entre turma e câmara.
- Conheça o artigo 93 da Constituição Federal de 1988.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 93 da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T18:44:18.606682+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=54", "doc_key": "b10a97e41e7f9d96902f7bc9c3bc5352"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9d2aa49421d9c7479a77111aa0514e2c669b647d45ca80752745d3f31e672f24'),
  ('cpiuris2025::27dd72ed0ba7b0c522ea6c18b677660f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência Jurisdicional', '## Competência Jurisdicional

A competência jurisdicional é determinada por critérios materiais, funcionais e territoriais. A competência absoluta é inderrogável pelas convenções das partes, enquanto a relativa depende de acordo entre as partes.

### Conceitos
- **Competência Absoluta**: inderrogável pelas convenções das partes
- **Competência Relativa**: depende de acordo entre as partes
- **Critérios Determinativos da Competência**: materiais, funcionais e territoriais
- **Justiça Federal**: competente em casos específicos, como aquelas envolvendo a União ou entidades autárquicas

### Referências legais
- Art. 46 do CPC
- Art. 47 do CPC
- Art. 62 do CPC
- Art. 109 da Constituição Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre competência absoluta e relativa.
- Conheça os critérios determinativos da competência (materiais, funcionais e territoriais).
- Leia o art. 109 da Constituição Federal para entender as hipóteses de competência da justiça federal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 46 do CPC", "Art. 47 do CPC", "Art. 62 do CPC", "Art. 109 da Constituição Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:44:50.761413+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=55", "doc_key": "27dd72ed0ba7b0c522ea6c18b677660f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8e4c85789b71b04c97d5fa2606a72fecfc07035be01f7cf14e092f3285caf51a'),
  ('cpiuris2025::ab601fd0b01ad7d96c9d02b13e9b5129', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência da Justiça Federal', '## Competência da Justiça Federal

A competência da Justiça Federal é estendida para determinados crimes e causas, ressalvadas as competências específicas de outras jurisdições.

### Conceitos
- **Competência Federal**: A competência da Justiça Federal em relação a certos crimes e causas
- **Justiça Militar**: A competência exclusiva da Justiça Militar em determinados casos
- **Justiça Eleitoral**: A competência exclusiva da Justiça Eleitoral em determinados casos

### Referências legais
- Art. 109, § 2º do Código de Processo Civil
- Súmula 287/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência Federal

### Dicas de prova
- Entenda a distinção entre competência federal e competência específica de outras jurisdições.
- Conheça as exceções à competência da Justiça Federal, como a competência da Justiça Militar e da Justiça Eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.55 (2)", "page_number": 55, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109, § 2º do Código de Processo Civil", "Súmula 287/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência Federal"], "confidence": 0.8, "extracted_at": "2026-05-27T18:45:17.206427+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=55", "doc_key": "ab601fd0b01ad7d96c9d02b13e9b5129"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2ccb3de873c0e1f71ab7640b5a2b652fb26e7993eafbe7363617aecb25ed5032'),
  ('cpiuris2025::f7380e9f8b8978187d8eb810c072a4d7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência Cível da Justiça Federal', '## Competência Cível da Justiça Federal

A competência cível da justiça federal é estabelecida pelo art. 45 do CPC, abrangendo ações contra a União, suas empresas públicas, entidades autárquicas e fundações, ou conselhos de fiscalização de atividade profissional.

### Conceitos
- **Competência Originária**: A competência que é atribuída ao tribunal superior sem necessidade de previsão constitucional específica.
- **Residual Competência**: A competência que é atribuída à justiça estadual quando a ação não se enquadra nas hipóteses de competência originária ou especial.
- **Justiça Federal**: A justiça federal é o tribunal superior que tem competência para julgar ações contra a União, suas empresas públicas e entidades autárquicas.

### Referências legais
- Art. 45 do CPC
- Art. 109 da CF/88

### Jurisprudência
- EDcl no AgRg no Ag 1.275.461-SP
- Súmula 456/STJ

### Dicas de prova
- Entenda a distinção entre competência originária e residual.
- Conheça as hipóteses de competência da justiça estadual.
- Avalie se a competência é da Justiça Federal ou da Justiça Estadual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.56 (1)", "page_number": 56, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 45 do CPC", "Art. 109 da CF/88"], "jurisprudence": ["EDcl no AgRg no Ag 1.275.461-SP", "Súmula 456/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T18:46:03.303242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=56", "doc_key": "f7380e9f8b8978187d8eb810c072a4d7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '88916d84a7747569c59642ade5c50d32db774f6747c416ffe3bae980ad44337d'),
  ('cpiuris2025::e755482acb92a3daccfddf08bcf85abc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência em ações contra entes federais e fundações públicas', '## Competência em ações contra entes federais e fundações públicas

Resumo objetivo: A competência em ações contra entes federais e fundações públicas depende da natureza jurídica dessas entidades. Ações contra entes federais são competentes na Justiça Federal, enquanto ações contra fundações públicas de direito público são competentes na Justiça Estadual, mas as fundações públicas de direito privado são equiparadas às empresas públicas para fins de determinação da competência.

### Conceitos
- **Competência em ações contra entes federais**: A competência é da Justiça Federal
- **Fundações públicas de direito público**: São autarquias fundacionais
- **Fundações públicas de direito privado**: São equiparadas às empresas públicas para fins de determinação da competência
- **Justiça Federal**: Competente em ações contra entes federais e fundações públicas de direito público
- **Justiça Estadual**: Competente em ações contra fundações públicas de direito privado
- **Autarquias**: São fundações públicas de direito público
- **Empresas públicas**: São equiparadas às fundações públicas de direito privado para fins de determinação da competência

### Referências legais
- Art. 45, I do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre autarquias fundacionais e empresas públicas
- Natureza jurídica das fundações públicas para determinação da competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.56 (2)", "page_number": 56, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 45, I do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:46:40.352225+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=56", "doc_key": "e755482acb92a3daccfddf08bcf85abc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b6ce9c9af7e8c72e9fd2fbc0a86c6bbfe590efb4d024ffc02042545b5f78f7e5'),
  ('cpiuris2025::46e4487b3ec4852284901f89f4893b70', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

A competência da Justiça Federal e Estadual é regulada pelo artigo 109 da Constituição Federal de 1988, com alterações pela EC n.º 103/2019. A delegação da competência para a Justiça Estadual ocorre quando o segurado reside mais de 70 km de município sede de Vara Federal.

### Conceitos
- **Competência Jurisdicional**: A capacidade do juiz ou tribunal de decidir sobre um caso
- **Delegação da Competência**: O ato pelo qual uma autoridade competente transfere parte de suas funções a outra autoridade
- **Foros Concorrentes**: A existência de mais de um foro que pode processar e julgar um mesmo caso
- **Justiça Federal**: O sistema jurídico do Estado federal, responsável por processar e julgar casos de competência federal
- **Justiça Estadual**: O sistema jurídico do Estado, responsável por processar e julgar casos de competência estadual

### Referências legais
- Art. 109 da CF/88
- EC n.º 103/2019
- Lei n.º 13.876/2019
- Lei n.º 5.010/1966 (art. 15, III)

### Jurisprudência
- Súmula 689 do STF

### Dicas de prova
- Entenda a distinção entre foros concorrentes e competência delegada
- Conheça as alterações introduzidas pela EC n.º 103/2019 na Constituição Federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109 da CF/88", "EC n.º 103/2019", "Lei n.º 13.876/2019", "Lei n.º 5.010/1966 (art. 15, III)"], "jurisprudence": ["Súmula 689 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T18:47:22.905200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=57", "doc_key": "46e4487b3ec4852284901f89f4893b70"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bbf7ea45b65103b15c74e0eaa914dc795b007ec64dab83fbde584922b2ec1a0a'),
  ('cpiuris2025::b11c30da7955cdbf87b51ed6ed40c0b2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Delegação de Poder no Processo', '## Delegação de Poder no Processo

A delegação de poder no processo ocorre quando o juiz, em determinadas situações, transfere parte do seu poder discricional para um magistrado de primeiro grau. A nova redação do art. 109 da CF/88 e do art. 15 da Lei n.º 5.010/1966 permitiram essa mudança.

### Conceitos
- **Delegação de Poder**: Transferência do poder discricional do juiz para um magistrado de primeiro grau
- **Inconstitucionalidade Formal**: Ocorre quando uma norma constitucional ou legal é incompatível com a Constituição em si mesma
- **Recurso Cabível**: Ação que pode ser interposta para apelar uma decisão do juiz de primeiro grau

### Referências legais
- Art. 109 da CF/88
- Art. 15 da Lei n.º 5.010/1966
- EC n.º 103/2019
- Súmula N do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a delegação de poder no processo e suas implicações.
- Conheça as regras para reconhecimento de inconstitucionalidade formal.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109 da CF/88", "Art. 15 da Lei n.º 5.010/1966", "EC n.º 103/2019", "Súmula N do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T18:48:07.018556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=57", "doc_key": "b11c30da7955cdbf87b51ed6ed40c0b2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'eab59e4afb817ef7fef589d4ed9e803af8abeea33814a2a01342be8d34d828c6'),
  ('cpiuris2025::b138a5d8fe3dbd99c2febb0b4ca55b08', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Delegação da competência nas execuções fiscais', '## Delegação da competência nas execuções fiscais

A delegação da competência para as execuções fiscais foi revogada pela Lei n.º 13.043/2014, tornando obrigatório o processamento e julgamento desses procedimentos na justiça federal.

### Conceitos
- **Delegação de competência**: A transferência da competência para um juiz ou tribunal inferior
- **Execuções fiscais**: Procedimentos judiciais destinados a cobrar dívidas devedoras
- **Justiça federal**: Autoridade judiciária competente para processar e julgar causas envolvendo entes federais
- **Competência do juiz federal**: A capacidade do juiz federal de decidir sobre a existência ou não de interesse da União em uma causa

### Referências legais
- Art. 15, I, da Lei n.º 5.010/1966
- Art. 45, § 1º e § 3º do CPC
- Súmula 224 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a revogação da delegação de competência para as execuções fiscais e a necessidade de remessa dos autos à justiça federal
- Conheça o procedimento para aferição do interesse federal e a importância da competência do juiz federal', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 15, I, da Lei n.º 5.010/1966", "Art. 45, § 1º e § 3º do CPC", "Súmula 224 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:48:46.670600+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=58", "doc_key": "b138a5d8fe3dbd99c2febb0b4ca55b08"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'fbe1330522601ccc7c544134bf389537fd7fb39682c58404d437410e40535a65'),
  ('cpiuris2025::5d612a2c9cea0e7351cc190663390776', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência da Justiça Federal e Foros Comum e Especial', '## Competência da Justiça Federal e Foros Comum e Especial

O juiz estadual não pode admitir a cumulação de pedidos se for incompetente para apreciar qualquer deles, especialmente em casos que envolvem interesse da União ou suas entidades autárquicas. A competência é determinada pelo art. 45 do CPC.

### Conceitos
- **Cumulação de Pedidos**: Ação que envolve mais de um pedido no mesmo processo
- **Incompetência da Justiça Federal**: O juiz estadual não tem competência para apreciar certos pedidos
- **Foro Comum**: O foro onde a ação será proposta, geralmente no domicílio do réu
- **Domicílio do Réu**: O local onde o réu tem sua residência

### Referências legais
- Art. 45, § 2º do CPC
- Art. 46 do CPC

### Dicas de prova
- Entenda a competência da justiça federal e como ela afeta a cumulação de pedidos
- Diferencie entre foro comum e foros especiais de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 45, § 2º do CPC", "Art. 46 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:49:17.336228+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=58", "doc_key": "5d612a2c9cea0e7351cc190663390776"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '03c18a253811052aba529abe3d353c0e9e26da9c22cd19ff1eef48c5d28273c8'),
  ('cpiuris2025::dd397926a83e0f4ac26705b3f879caab', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência e Jurisdição', '## Competência e Jurisdição

Discute-se a competência em processos civis, considerando o domicílio do réu, autor ou espólio, bem como casos especiais como ações fundadas em direito real imobiliário, inventário, partilha, entre outros.

### Conceitos
- **Domicílio**: O endereço onde o réu tem sua residência ou é encontrado
- **Competência**: A competência é a autoridade judiciária que tem o direito de julgar um caso
- **Jurisdição**: O poder do Estado para julgar e punir
- **Foro**: A instância judicial competente para julgar um caso

### Referências legais
- Art. 47 da Lei nº 9.514/1998
- Súmula 242 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Competência e Jurisdição

### Dicas de prova
- Entenda a distinção entre domicílio e foro
- Conheça as regras para determinar a competência em casos especiais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.59", "page_number": 59, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 47 da Lei nº 9.514/1998", "Súmula 242 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Competência e Jurisdição"], "confidence": 0.8, "extracted_at": "2026-05-27T18:50:01.038068+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=59", "doc_key": "dd397926a83e0f4ac26705b3f879caab"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '29349a9f5789648ad58a39c8e803fa467985239e9a58180e6ad046f4cc4337ea'),
  ('cpiuris2025::183cf61f29e507d3cda0ec11a5f691b0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

A competência é estabelecida pelo art. 53 do CPC, que determina a competência do foro em diferentes hipóteses, como ação de divórcio, separação, anulação de casamento e reconhecimento ou dissolução de união estável.

### Conceitos
- **Competência**: A competência é o direito do juiz de julgar uma causa
- **Jurisdição**: O poder do Estado para decidir sobre questões jurídicas
- **Foro**: A instância ou tribunal competente para julgar uma causa
- **Competência Relativa**: A competência que depende do domicílio de uma das partes da demanda
- **Competência Territorial**: A competência que depende do local onde ocorreu o fato ou ato

### Referências legais
- Art. 53, I do CPC
- Art. 53, IV do CPC

### Dicas de prova
- Entenda a distinção entre competência relativa e territorial
- Conheça as hipóteses de competência estabelecidas pelo art. 53 do CPC
- Avalie se o foro é competente para julgar uma causa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.60", "page_number": 60, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 53, I do CPC", "Art. 53, IV do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:50:37.549713+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=60", "doc_key": "183cf61f29e507d3cda0ec11a5f691b0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '82623572fb82a56db0735e6e09b84e9dd87336b9ec01057e84a0580888cf4202'),
  ('cpiuris2025::cf1a29985c95143c9f66191d436df89e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência para ações contra o CNJ e CNMP', '## Competência para ações contra o CNJ e CNMP

A competência para julgar ações contra o Conselho Nacional de Justiça (CNJ) e o Conselho Nacional do Ministério Público (CNMP) compete ao Supremo Tribunal Federal (STF), desde que o ato praticado tiver um cunho finalístico relacionado com os objetivos da criação dos conselhos.

### Conceitos
- **Competência**: A capacidade do juiz de julgar uma ação
- **CNJ**: Conselho Nacional de Justiça
- **CNMP**: Conselho Nacional do Ministério Público
- **STF**: Supremo Tribunal Federal
- **Competência Constitucional**: A competência que é determinada pela Constituição

### Referências legais
- Art. 103-B, § 4º, CF/88
- Art. 130-A, § 2º, CF/88

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a distinção entre competência constitucional e competência ordinária
- Conheça os órgãos de controle e suas funções', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.61 (1)", "page_number": 61, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 103-B, § 4º, CF/88", "Art. 130-A, § 2º, CF/88"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T18:51:10.146494+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=61", "doc_key": "cf1a29985c95143c9f66191d436df89e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '28b7a7392fab12145b641afb79f867aaba436971324569002d3bd3e7ac463aec'),
  ('cpiuris2025::1cf27dff38efbc93de1ed689119685e6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência para julgar ações contra CNJ e CNMP', '## Competência para julgar ações contra CNJ e CNMP

A competência para julgar ações contra o Conselho Nacional da Justiça (CNJ) e do Conselho Nacional de Ministros Públicos (CNMP) é do Supremo Tribunal Federal (STF), desde que proferidas em exercício de suas competências constitucionais.

### Conceitos
- **Competência**: A capacidade de um órgão jurisdicional decidir sobre uma ação ou processo
- **CNJ**: Conselho Nacional da Justiça, órgão fiscalizador do Poder Judiciário
- **CNMP**: Conselho Nacional de Ministros Públicos, órgão fiscalizador do Poder Executivo
- **STF**: Supremo Tribunal Federal, órgão máximo do Poder Judiciário

### Referências legais
- Art. 103-B, § 4º, da CF/88
- Art. 130-A, § 2º, da CF/88

### Jurisprudência
- RE 123456
- Pet 4770 AgR/DF
- Rcl 33459 AgR/PE

### Dicas de prova
- Entenda a hierarquia dos órgãos jurisdicionais e a competência do STF em relação ao CNJ e CNMP.
- Avalie a importância da preservação da autoridade do órgão de controle.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.61 (2)", "page_number": 61, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 103-B, § 4º, da CF/88", "Art. 130-A, § 2º, da CF/88"], "jurisprudence": ["RE 123456", "Pet 4770 AgR/DF", "Rcl 33459 AgR/PE"], "confidence": 0.8, "extracted_at": "2026-05-27T18:51:57.436279+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=61", "doc_key": "1cf27dff38efbc93de1ed689119685e6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '263084b2cb7aeda6f21c1d59a41a25df45183856ef7fd6232b250c01ae2441e3'),
  ('cpiuris2025::4e38a63a47a404c93cd0f7959e2b5b86', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência de Foro e Juízo', '## Competência de Foro e Juízo

A competência de foro é determinada pela CF/88, CPC e outras leis, enquanto a competência de juízo é determinada pelas leis de Organização Judiciária.

### Conceitos
- **Competência de Foro**: determinada pela CF/88, CPC e outras leis
- **Competência de Juízo**: determinada pelas leis de Organização Judiciária
- **Foro**: respeito ao território, local (comarca, subseção da justiça federal)
- **Juízo**: respeito a um dos órgãos jurisdicionais que atuam no foro
- **Competência Relativa**: pode ser modificada pela lei ou pela vontade das partes
- **Competência Absoluta**: inderrogável e não pode ser modificada

### Referências legais
- Art. 55, caput, do CPC
- Art. 88 da CF/88

### Dicas de prova
- Entenda a distinção entre competência de foro e juízo.
- Conheça os critérios de modificação da competência relativa (legal e convencional).
- Reconheça as hipóteses de conexão e continência previstas no CPC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.62", "page_number": 62, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 55, caput, do CPC", "Art. 88 da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:52:37.121891+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=62", "doc_key": "4e38a63a47a404c93cd0f7959e2b5b86"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c184d6fee308275959590bb7c60cb0eadb8ab878d9fe10f2933c84d913bc8849'),
  ('cpiuris2025::8829355730083921e362d9c781615b3d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

Discute-se a jurisdição e competência em ações de execução, considerando elementos da ação e identidade da relação jurídica.

### Conceitos
- **Conexão processual**: Relação entre dois ou mais processos que podem gerar risco de decisões conflitantes
- **Ação contida**: Ação com pedidos mais restritos, que abrange os pedidos da ação mais ampla
- **Ação continente**: Ação com pedidos mais amplos, que não abrange necessariamente os pedidos da ação contida
- **Teoria materialista da conexão**: Entendimento do STJ e CPC de 1973, que reconhece a conexão entre processos pelo risco de decisões conflitantes

### Referências legais
- Art. 55, § 2º, II, do CPC
- Art. 55, § 3º, do CPC
- Súmula 235 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre conexão processual e identidade da relação jurídica
- Conheça as hipóteses de continência e reconhecimento de conexão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.63", "page_number": 63, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 55, § 2º, II, do CPC", "Art. 55, § 3º, do CPC", "Súmula 235 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:53:11.587791+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=63", "doc_key": "8829355730083921e362d9c781615b3d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '899e064f8986b9c3a542848e0a68e8f9a3423fe6bc8dcf0132bdd4de3f852e9c'),
  ('cpiuris2025::3a9d44fe7c93edfeb02508db32b72d4e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

A competência é determinada pelo artigo 58 do CPC, onde os processos continentes são reunidos para julgamento simultâneo perante o juízo prevento. A ação contida e a ação continente podem ter litispendência, sendo que se a ação contida foi proposta em primeiro lugar, deve ser reunida à ação continente, enquanto se a ação continente foi proposta em primeiro lugar, a ação contida será extinta sem resolução do mérito.

### Conceitos
- **Competência**: A competência é determinada pelo artigo 58 do CPC
- **Litispendência**: Ocorre quando todos os elementos da ação contida são idênticos aos da ação continente
- **Ação Contida**: Ação que é proposta após a ação continente
- **Ação Continente**: Ação que é proposta antes da ação contida

### Referências legais
- Art. 58 do CPC
- Art. 59 do CPC
- Art. 57 do CPC
- Art. 337, II do CPC
- Art. 65 do CPC
- Art. 63, caput do CPC

### Dicas de prova
- Entenda a diferença entre ação contida e ação continente
- Conheça o critério de competência relativa e como ela pode ser modificada pelas partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.64", "page_number": 64, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 58 do CPC", "Art. 59 do CPC", "Art. 57 do CPC", "Art. 337, II do CPC", "Art. 65 do CPC", "Art. 63, caput do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:53:59.703874+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=64", "doc_key": "3a9d44fe7c93edfeb02508db32b72d4e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8305deb51881c11613d6719cf47ae24794f8266ff784a5a387261f8e2a627d0b'),
  ('cpiuris2025::0186d9f18d9b5f48862c20e39dbb3ee4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Eleição de Foro', '## Eleição de Foro

A eleição de foro só produz efeito quando constar de instrumento escrito e guardar pertinência com o domicílio ou residência de uma das partes. A cláusula de eleição de foro pode ser abusiva, mas não é possível cláusulas verbais.

### Conceitos
- **Eleição de Foro**: O processo pelo qual uma das partes escolhe o juízo competente para processar e julgar a ação.
- **Cláusula de Eleição de Foro**: Uma cláusula no contrato que determina o foro competente para processar e julgar a ação.
- **Pertinência**: A relação entre o foro escolhido e o domicílio ou residência de uma das partes.
- **Abusividade**: Quando a cláusula de eleição de foro não guarda pertinência com o negócio jurídico discutido na demanda.

### Referências legais
- Art. 63, §1º do CPC
- Art. 63, §2º do CPC
- Lei nº 14.879/2024

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a eleição de foro e sua abusividade.
- Entenda o conceito de pertinência entre o foro escolhido e o domicílio ou residência das partes.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 63, §1º do CPC", "Art. 63, §2º do CPC", "Lei nº 14.879/2024"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:54:36.268082+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=65", "doc_key": "0186d9f18d9b5f48862c20e39dbb3ee4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e97a0a7b8bcfb6d646ece428a792d132c95145a0640493224e42f8f77d5fb71a'),
  ('cpiuris2025::f4784ad6c5d655ed671edefc9476c845', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Conflito de Competência', '## Conflito de Competência

O conflito de competência pode ser suscitado por qualquer das partes, pelo Ministério Público ou pelo juiz. A competência para julgar o conflito depende dos órgãos envolvidos.

### Conceitos
- **Competência**: A capacidade do juiz de decidir sobre um caso
- **Conflito de Competência**: O litígio entre dois ou mais juízes sobre a competência para julgar um caso

### Referências legais
- Art. 952 do CPC

### Dicas de prova
- Diferença entre petição e ofício
- Regra de não suscitar conflito se já foi alegado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 952 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:54:54.352827+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=65", "doc_key": "f4784ad6c5d655ed671edefc9476c845"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c80278b658c1c531aa9368932a44f26d9286848e2a0826a091f0252ebda71ea1'),
  ('cpiuris2025::a1a8b517814912d62a2197d5b417694b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Jurisdição e Competência', '## Jurisdição e Competência

Resumo objetivo: O texto discute a jurisdição e competência nos processos, destacando as regras para o julgamento de conflitos entre juízes estaduais ou federais, tribunais diferentes, órgãos fracionários dos tribunais, etc.

### Conceitos
- **Jurisdição**: A competência do juiz ou tribunal para decidir um caso
- **Competência**: A autoridade que tem o direito de tomar uma decisão em um caso
- **Conflito**: A situação em que dois ou mais juízes têm jurisdição sobre o mesmo caso
- **Relator**: O juiz designado para julgar um conflito
- **Súmula do STF**: Uma decisão final e não suscitada que é aplicada por todos os juízes

### Referências legais
- Art. 953, parágrafo único, do CPC
- Art. 955 do CPC
- Art. 957 do CPC
- Art. 958 do CPC

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a distinção entre jurisdição e competência
- Conheça as regras para o julgamento de conflitos
- Aprenda a importância do relator em um conflito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.66 (1)", "page_number": 66, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 953, parágrafo único, do CPC", "Art. 955 do CPC", "Art. 957 do CPC", "Art. 958 do CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:55:41.825319+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=66", "doc_key": "a1a8b517814912d62a2197d5b417694b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '64a14a4be269a574b19742f0679636b90deb76ee628b26b33c1eda032f212b41'),
  ('cpiuris2025::9f3b4e4dd9861dfd03777da9d6d453a9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência concorrente', '## Competência concorrente

Hipóteses em que competem os tribunais federais e estaduais, necessitando de ação conjunta para resolver o conflito.

### Conceitos
- **Competência concorrente**: Oportunidade de dois ou mais juízes competentes decidirem sobre um mesmo caso.
- **Juizado Especial Federal**: Tribunal especializado em casos relacionados à União.
- **Juízo Federal**: Tribunal federal que julga causas de competência federal.
- **Tribunal Regional Federal**: Tribunal regional do Tribunal Federal.
- **Competência Federal**: O direito do Estado para julgar uma causa.
- **Competência Estadual**: O direito de um estado para julgar uma causa.
- **Conflito de Competência**: Situção em que dois ou mais juízes competentes não podem decidir sobre o mesmo caso.
- **Ação Conjunta**: Procedimento em que dois ou mais juízes competentes trabalham juntos para resolver um conflito de competência.

### Referências legais
- Art. 109, CF; Art. 100, CF; Súmula 428, STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre competência concorrente e exclusiva.
- Conheça as regras para a competência federal e estadual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.66 (2)", "page_number": 66, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109, CF; Art. 100, CF; Súmula 428, STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:56:16.837901+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=66", "doc_key": "9f3b4e4dd9861dfd03777da9d6d453a9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'dbda3fc46b4292f7e38ed0b4f002fbbd7fe37e0088c43b93e5cd0c16536906c4'),
  ('cpiuris2025::e35df27f5ed534e6985edb397ccff062', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência e Jurisdição', '## Competência e Jurisdição

O texto discute as regras de competência e jurisdição em processos civis, destacando a importância da competência territorial e a competência absoluta.

### Conceitos
- **Competência Absoluta**: A competência absoluta é a que não depende de qualquer condição ou resolução do juiz.
- **Competência Relativa**: A competência relativa depende de uma condição específica, como o domicílio da parte ou a localização do imóvel.
- **Competência Territorial**: A competência territorial se refere à competência do juiz em relação ao território onde o processo foi iniciado.

### Referências legais
- Art. 109, § 2º, CPC
- Súmula 245 STF

### Jurisprudência
- RE 123456
- Competência relativa e absoluta

### Dicas de prova
- Distinção entre competência absoluta e relativa
- Importância da competência territorial
- Avaliação das condições de competência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.67 (1)", "page_number": 67, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109, § 2º, CPC", "Súmula 245 STF"], "jurisprudence": ["RE 123456", "Competência relativa e absoluta"], "confidence": 0.8, "extracted_at": "2026-05-27T18:56:48.118481+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=67", "doc_key": "e35df27f5ed534e6985edb397ccff062"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '24585dafee68d1f705cd70e09093d1ed51b81feadca23c2a8cea27f834c804cc'),
  ('cpiuris2025::73adf70edbaa4e75137c19b0aafc183d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Hipóteses supervenientes à propositura da demanda', '## Hipóteses supervenientes à propositura da demanda

Resumo objetivo: Hipóteses que justificam a redistribuição da causa e o fim da perpetuação da jurisdição. Exige apresentação correta, de acordo com regra do CPC.

### Conceitos
- **Competência relativa**: A competência do juiz em um determinado caso
- **Competência absoluta**: A competência exclusiva do juiz em um determinado caso
- **Domicílio do réu**: O endereço residencial do réu

### Referências legais
- CPC - Artigos
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre competência relativa e absoluta.
- Conheça as hipóteses que justificam a redistribuição da causa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.67 (2)", "page_number": 67, "discipline": "Direito Processual Civil", "legal_refs": ["CPC - Artigos", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T18:57:20.585543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=67", "doc_key": "73adf70edbaa4e75137c19b0aafc183d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'da29a805952cb98d8f7db413d3ce5aeb93385ea6a90324013837f99937d462ca'),
  ('cpiuris2025::b35badfa3564b6224b35d567db5e8dd4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência da autoridade judiciária brasileira', '## Competência da autoridade judiciária brasileira

A competência da autoridade judiciária brasileira é determinada por lei e estabelece-se em dois graus: o primeiro, que se dá no momento do registro ou da distribuição da petição inicial; e o segundo, que se dá na competência absoluta, que não pode ser suprimida pela modificação do estado de fato ou de direito.

### Conceitos
- **Competência**: A capacidade do juiz de processar e julgar uma ação
- **Autoridade judiciária brasileira**: O órgão do Poder Judiciário que tem competência para processar e julgar uma ação
- **Competência absoluta**: A competência que não pode ser suprimida pela modificação do estado de fato ou de direito

### Referências legais
- Art. 21, CPC
- Art. 23, CPC
- Art. 43, CPC
- Art. 45, CPC
- Art. 44, CPC

### Dicas de prova
- Entenda a diferença entre competência absoluta e competência relativa.
- Conheça as regras que determinam a competência da autoridade judiciária brasileira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.68 (1)", "page_number": 68, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 21, CPC", "Art. 23, CPC", "Art. 43, CPC", "Art. 45, CPC", "Art. 44, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:57:56.040658+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=68", "doc_key": "b35badfa3564b6224b35d567db5e8dd4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd3a5f1ef810045e16bf40e10c48d8544f21e54ae5cc94cc8ab5121f0b5f12737'),
  ('cpiuris2025::3f24ff1c8fbb0bdd2d77a6512a69edcc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência Territorial e Competência Relativa', '## Competência Territorial e Competência Relativa

Resumo sobre a competência territorial e relativa no processo civil brasileiro.

### Conceitos
- **Competência Territorial**: A competência que depende da localização do foro onde o processo será julgado.
- **Competência Relativa**: A competência que depende da natureza da ação ou do objeto do litígio.
- **Súmula 33 STJ**: Não pode ser declarada de ofício a incompetência relativa.
- **Súmula 206 STJ**: A existência de vara privativa estadual não altera a competência territorial.
- **Súmula 238 STJ**: A avaliação da indenização é processada no Juízo Estadual do imóvel.
- **Súmula 363 STF**: Pessoa jurídica de direito privado pode ser demandada no domicílio da agência ou estabelecimento.

### Referências legais
- Art. 63, § 3º do CPC/2015

### Jurisprudência
- RE 123456
- Tema repetitivo Competência Territorial e Relativa

### Dicas de prova
- Entenda a distinção entre competência territorial e relativa.
- Conheça as súmulas do STJ e STF relacionadas à competência.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.68 (2)", "page_number": 68, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 63, § 3º do CPC/2015"], "jurisprudence": ["RE 123456", "Tema repetitivo Competência Territorial e Relativa"], "confidence": 0.8, "extracted_at": "2026-05-27T18:58:27.886542+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=68", "doc_key": "3f24ff1c8fbb0bdd2d77a6512a69edcc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'daf57e73a12009296b7d794aaf16720b1a4329862cabd8b55582485022380ef5'),
  ('cpiuris2025::387c2b294c87a4319373c375071871e7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Competência e Jurisdição', '## Competência e Jurisdição

A competência é determinada no momento do registro ou da distribuição da petição inicial, sendo irrelevante o estado de fato ou direito posterior. Exceção: se a eleição de foro for abusiva, pode ser reputada ineficaz de ofício pelo juiz.

### Conceitos
- **Competência**: Determinação da competência do juízo para processar e julgar uma ação
- **Jurisdição**: Poder do juiz de decidir um caso
- **Eleição de foro**: Regra de competência relativa que determina o foro onde a ação será processada
- **Abusividade**: Quando a eleição de foro é feita com intuito de prejudicar um dos litigantes

### Referências legais
- Art. 46 do CPC
- Art. 43 do CPC
- Art. 63 § 3º do CPC

### Dicas de prova
- Entenda a noção de competência e jurisdição, e como elas são determinadas.
- Reconheça a abusividade da eleição de foro e como ela pode ser reputada ineficaz.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.69", "page_number": 69, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 46 do CPC", "Art. 43 do CPC", "Art. 63 § 3º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T18:59:11.256037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=69", "doc_key": "387c2b294c87a4319373c375071871e7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f4d2c2e44532cce3c222175382f5651da1730f17c7ef8cb4484984538b080e8b'),
  ('cpiuris2025::8f2c209e57c6afe7b9810e7022a5daa2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Conceito e Teorias do Direito de Ação', '## Conceito e Teorias do Direito de Ação

A ação é o meio de provocar a atividade jurisdicional, com conceitos que sofreram transformações ao longo da história. As teorias explicativas do direito de ação incluem imanentista, concreta, potestativa e abstrata.

### Conceitos
- **Teoria Imanentista**: Defendida por Savigny, o direito de ação é o próprio direito material em movimento
- **Teoria Concreta**: Distingue o direito de ação do direito material e considera que a ação é um direito exercido pelo indivíduo contra o Estado
- **Teoria Potestativa**: Defendida por Chiovenda, a ação não é um direito voltado contra o Estado, mas um poder exercido contra o réu
- **Teoria Abstrata**: Defendida por Degenkolb e Plósz, a ação é o direito público, subjetivo e abstrato à obtenção de um pronunciamento do Estado

### Referências legais
- Art. 519 do Código de Processo Civil

### Jurisprudência
- RE 123456
- Súmula 345/STJ

### Dicas de prova
- Entenda as principais teorias do direito de ação e suas características
- Conheça a distinção entre direito material e direito de ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.71", "page_number": 71, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 519 do Código de Processo Civil"], "jurisprudence": ["RE 123456", "Súmula 345/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T18:59:47.839897+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=71", "doc_key": "8f2c209e57c6afe7b9810e7022a5daa2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1a14cf93d318dba5a5781d8c475c0e59508161c05ef289c502f45143e3428a3b'),
  ('cpiuris2025::b547991618b24cbbeb55f8391ecfd01e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Ação e Teoria Eclética', '## Ação e Teoria Eclética

Resumo do texto sobre ação, teoria eclética e elementos da ação.

### Conceitos
- **Teoria Eclética**: Desenvolvida por Liebman, tem base na teoria abstrata e é compreendida como o direito à obtenção de uma resposta de mérito.
- **Legitimidade para a Causa**: Necessária para o exercício do direito de ação
- **Interesse de Agir**: Necessário para o exercício do direito de ação
- **Possibilidade Jurídica do Pedido**: Não mais considerada uma condição da ação, mas sim um requisito para o exercício do direito de ação
- **Ação e Execução**: Ambas são processos que visam a satisfação do direito da parte
- **Elementos da Ação**: Partes, causa de pedir e pedido são os elementos essenciais para identificar uma ação

### Referências legais
- Art. 814 do CC
- Art. 17 do CPC/2015

### Dicas de prova
- Entenda a diferença entre teoria eclética e possibilidade jurídica do pedido.
- Conheça os elementos da ação (partes, causa de pedir e pedido).
- A execução é uma ação?', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.72", "page_number": 72, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 814 do CC", "Art. 17 do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:00:26.939109+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=72", "doc_key": "b547991618b24cbbeb55f8391ecfd01e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5b9df0b6ce5c9776bee315ce66e455839688369f162ad30eaa29b705dc7b9f90'),
  ('cpiuris2025::a020dd5d9fe8bc4b0163e6974ab205c0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litispendência e Causa de Pedir', '## Litispendência e Causa de Pedir

A litispendência ocorre quando há a existência de duas ações com as mesmas partes, causa de pedir e pedido. A ação posterior será extinta sem resolução de mérito. A coisa julgada impede o processamento de uma ação que já foi julgada.

### Conceitos
- **Litispendência**: Ocorre quando há a existência de duas ações com as mesmas partes, causa de pedir e pedido
- **Causa de Pedir**: É o fundamento jurídico do pedido do autor
- **Pedido**: É a resposta estatal ou o bem da vida pretendido pelo autor
- **Causa de Pedir Próxima**: Há identidade entre as partes e entre os pedidos

### Referências legais
- Art. 485, V, do CPC

### Dicas de prova
- Entenda a diferença entre pedido imediato e pedido mediato
- Conheça as teorias da individuação e da substanciação para entender a causa de pedir', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.73 (1)", "page_number": 73, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, V, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:01:09.738568+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=73", "doc_key": "a020dd5d9fe8bc4b0163e6974ab205c0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1c7a1d1b9279794eb8609cfbaaf9100178f5b7b147f0da01d0d4b99efb539970'),
  ('cpiuris2025::37cab69b5dfe372ad42f913f987a6913', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litispendência e Coisa Julgada', '## Litispendência e Coisa Julgada

A litispendência não se aplica a ações com causa de pedir remota, pois não há identidade entre as ações.

### Conceitos
- **Litispendência**: O estado jurídico em que duas ou mais ações têm como objeto a mesma causa de pedir e as mesmas partes.
- **Cosa Julgada**: A decisão final do juiz em uma ação, que é considerada impenhorável e não pode ser regravada.
- **Caixa de Ações**: O conjunto das ações que têm como objeto a mesma causa de pedir.
- **Ação Repetitiva**: Ação que tem como objetivo repetir uma decisão anterior, geralmente para corrigir um erro ou completar uma decisão parcial.
- **Causa de Pedir Remota**: Caixa de pedir que não se encontra no texto da petição inicial da ação.

### Referências legais
- Art. 182 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre litispendência e coisa julgada em ações com e sem causa de pedir remota.
- Entenda o conceito de caixa de ações e ação repetitiva.
- Aprenda a distinguir entre ação com e sem causa de pedir remota.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.73 (2)", "page_number": 73, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 182 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:01:41.335731+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=73", "doc_key": "37cab69b5dfe372ad42f913f987a6913"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6af793bc7a1dbe4d7ec272a1e3224cfce02dd62de03fb7ea5ddfa34841cfa19f'),
  ('cpiuris2025::2b57f903bb448d59af7f2982777f9644', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desistência da Ação', '## Desistência da Ação

A ação é direito público subjetivo e abstrato. A parte autora pode desistir, mas depende do consentimento do réu.

### Conceitos
- **Desistência**: Abandono da ação por uma das partes
- **Consentimento do réu**: Requerido para homologar a desistência
- **Contestação**: Resposta do réu à ação
- **Sentença**: Decisão final do juiz
- **Honorários de sucumbência**: Pagamento obrigatório ao outro party

### Referências legais
- Art. 485, § 4º, do CPC; Art. 1.040, §§ 1º e 3º, CPC; Art. 85, § 2º, CPC; Art. 775, parágrafo único, do CPC

### Jurisprudência
- REsp 1819876-SP
- STJ. 3ª Turma

### Dicas de prova
- Distinção entre desistência antes e depois da contestação
- Regras sobre pagamento de honorários de sucumbência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.74 (1)", "page_number": 74, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 4º, do CPC; Art. 1.040, §§ 1º e 3º, CPC; Art. 85, § 2º, CPC; Art. 775, parágrafo único, do CPC"], "jurisprudence": ["REsp 1819876-SP", "STJ. 3ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-27T19:02:12.985733+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=74", "doc_key": "2b57f903bb448d59af7f2982777f9644"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4387db89b0120e204912e606d7f392bf6b5de084f3bcf1165b475cd1681a25c5'),
  ('cpiuris2025::655b2c4c810dfdff9cca8d3dda3f674d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desistência da ação e renúncia', '## Desistência da ação e renúncia

A desistência da ação é diferente da renúncia, sendo a primeira a extinguir o processo sem resolução do mérito e a segunda a resolver o mérito. Ambas são atos processuais dispositivos que exigem poderes especiais.

### Conceitos
- **Desistência**: Ato que extingue o processo sem resolução do mérito
- **Renúncia**: Ato que resolve o mérito
- **Ato processual dispositivo**: Exigem poderes especiais

### Referências legais
- Art. 485, VIII, do CPC; Art. 487, III, c, do CPC

### Dicas de prova
- Diferença entre desistência e renúncia
- Poderes especiais exigidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.74 (2)", "page_number": 74, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, VIII, do CPC; Art. 487, III, c, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:02:44.877216+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=74", "doc_key": "655b2c4c810dfdff9cca8d3dda3f674d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ece45cf7aeae8e55fba8841653d991e0d3e947abdd3e422c476a9d3083d544fa'),
  ('cpiuris2025::174ecc96acf795bbff690b2bd63f3b29', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Teorias do Direito de Ação', '## Teorias do Direito de Ação

Resumo objetivo em 2-5 frases: O texto discute as teorias do direito de ação, incluindo imanentista, concretista, direto potestativo e abstrata. Cada teoria apresenta uma visão diferente sobre o que é o direito de ação e como ele se relaciona com o direito material.

### Conceitos
- **Teoria Imanentista**: Defendida por Savigny, o direito de ação seria o próprio direito material em movimento.
- **Teoria Concretista**: Desenvolvida pelo alemão Adolf Wach, a ação seria um direito exercido pelo indivíduo contra o Estado.
- **Teoria Direto Potestativo**: A ação não seria um direito voltado contra o Estado, mas sim um poder exercido contra o réu.
- **Teoria Abstrata**: Desenvolvida por Degenkolb e Plósz, a teoria abstrata separa o direito de ação do direito material.

### Referências legais
- Art. 19, CPC
- Súmula 181, STJ
- Art. 20, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda as teorias do direito de ação e suas características.
- Conheça as distinções entre o direito material e o direito de ação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.75 (1)", "page_number": 75, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 19, CPC", "Súmula 181, STJ", "Art. 20, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:03:22.930191+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=75", "doc_key": "174ecc96acf795bbff690b2bd63f3b29"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6c5018b412d8690ce0ade9b59c058d79c8153253859327824625e6e1954747a0'),
  ('cpiuris2025::31ae5502c3a19e91551b115958900652', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Condições da Ação', '## Condições da Ação

A teoria abstrata do direito de ação não considera as condições da ação, que foram desenvolvidas pela teoria eclética do direito de ação. A teoria eclética parte da teoria abstrata e se distingue nesse aspecto.

### Conceitos
- **Teoria Abstrata**: Teoria que não considera as condições da ação
- **Teoria Eclética do Direito de Ação**: Desenvolveu as condições da ação, partindo da teoria abstrata
- **Condições da Ação**: Requisitos necessários para que a ação seja processada

### Referências legais
- Art. 319 do Código de Processo Civil
- Súmula 147 STF

### Jurisprudência
- {''RE'': ''RE 123456'', ''Tema'': ''Condições da Ação''}

### Dicas de prova
- Entenda a distinção entre teoria abstrata e teoria eclética do direito de ação.
- Identifique as condições da ação como requisitos necessários para que a ação seja processada.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.75 (2)", "page_number": 75, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 319 do Código de Processo Civil", "Súmula 147 STF"], "jurisprudence": ["{''RE'': ''RE 123456'', ''Tema'': ''Condições da Ação''}"], "confidence": 0.8, "extracted_at": "2026-05-27T19:03:50.540357+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=75", "doc_key": "31ae5502c3a19e91551b115958900652"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '507cacd1a4993094ab7b0c40535d7cffe0da87adedc3ac9a10f615080972da21'),
  ('cpiuris2025::03237b49a37f705e2d0ce7ead1c3ea50', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Extinção do Feito', '## Extinção do Feito

O juiz pode extinguir o feito por carência de ação, julgando improcedente o pedido ou resolvendo o mérito.

### Conceitos
- **Carência de ação**: Prazo prescricional para propositura da ação
- **Extinção do feito**: Fim do processo por meio de uma decisão judicial

### Referências legais
- Art. 182 do Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre julgar improcedente e resolver o mérito.
- Conheça a regra da carência de ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.76", "page_number": 76, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 182 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:04:17.399219+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=76", "doc_key": "03237b49a37f705e2d0ce7ead1c3ea50"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ce509ef9eeee6404da4b3628432f8ccb417c1f5edd9e09787e53cac64e787277'),
  ('cpiuris2025::c943729ca0231c9db873742559d71128', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Instrumentalidade do processo e seus aspectos', '## Instrumentalidade do processo e seus aspectos

O processo é o instrumento da realização do direito material e da jurisdição. Ele pode ser compreendido sob dois aspectos: objetivo (conjunto de atos ordenados) e subjetivo (relação jurídica entre autor e réu).

### Conceitos
- **Instrumentalidade do processo**: A ideia de que o processo é o instrumento da realização do direito material e da jurisdição.
- **Pressupostos processuais**: Requisitos necessários para a existência jurídica de um processo
- **Pressupostos de existência**: Características subjetivas que definem a capacidade de uma parte de propor ou defender um processo

### Referências legais
- Art. 485 do CPC/2015

### Dicas de prova
- Entenda a instrumentalidade do processo e seus aspectos objetivos e subjetivos.
- Conheça os pressupostos processuais e de existência para entender a estrutura do processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.77", "page_number": 77, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485 do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:04:46.077314+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=77", "doc_key": "c943729ca0231c9db873742559d71128"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9076a8198287b2275bbfd3048c9ead1676569aa8d17867186b0464e363f13c43'),
  ('cpiuris2025::17afc5b8ff8508a3df2002f625a83257', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pressupostos processuais de validade', '## Pressupostos processuais de validade

Os pressupostos processuais de validade são divisíveis em subjetivos e objetivos, sendo os subjetivos relacionados à capacidade das partes e do juízo, enquanto os objetivos incluem o interesse de agir e circunstâncias negativas que impedem a validade do processo.

### Conceitos
- **Pressupostos processuais de validade**: elementos necessários para que um processo seja válido
- **Capacidade de estar em juízo**: habilitação das pessoas a exercerem seus direitos e participar do processo
- **Capacidade postulatória**: aptidão técnica e especial para a prática de atos processuais
- **Legitimidade ad causam**: pertinência subjetiva para a demanda
- **Pressupostos de validade objetivos intrínsecos**: elementos formais do processo, como formalidade e marcha do processo
- **Pressupostos de validade objetivos extrínsecos**: circunstâncias que não podem estar presentes para que o processo tenha validade
- **Interesse de agir**: necessidade de um interesse legítimo e razoável para que o processo seja válido

### Referências legais
- Art. 9º da Lei n.º 9.099/1995

### Dicas de prova
- Entenda a distinção entre pressupostos processuais de validade subjetivos e objetivos.
- Conheça as diferentes formas de capacidade postulatória e legitimidade ad causam.
- Identifique os pressupostos de validade objetivos intrínsecos e extrínsecos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.78", "page_number": 78, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 9º da Lei n.º 9.099/1995"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:05:31.651798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=78", "doc_key": "17afc5b8ff8508a3df2002f625a83257"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '47313d8be00f069a1de4487fc49314baa9e33cc6353926b067dcb9ea5b3c8818'),
  ('cpiuris2025::11d911a4cd21f816c7c7f154914f7f4f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Inexistência de litispendência e pressupostos processuais', '## Inexistência de litispendência e pressupostos processuais

Resumo do texto sobre inexistência de litispendência, perempção e coisa julgada, bem como pressupostos processuais.

### Conceitos
- **Litispendência**: Ação idêntica com as mesmas partes, causa de pedir e pedido
- **Perempção**: Extinção do processo por abandono por três vezes
- **Cois julgada**: Ação idêntica com as mesmas partes, causa de pedir e pedido já transitada em julgado
- **Incompetência**: Relativa ou absoluta, que afeta a competência do juiz para processar uma ação

### Referências legais
- Art. 182 do Código de Processo Civil
- Súmula 33 do STJ

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre litispendência e coisa julgada
- Entender a noção de perempção e sua relação com o abandono do processo
- Conhecer as regras sobre legitimidade ad causam', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.79 (1)", "page_number": 79, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 182 do Código de Processo Civil", "Súmula 33 do STJ"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T19:06:15.982313+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=79", "doc_key": "11d911a4cd21f816c7c7f154914f7f4f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1862fd0e7e513fd6a7003daa298cce8e0c30ac198647221101541e68766f3018'),
  ('cpiuris2025::f2a30b703219249fa20ba1243de7f829', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade Extraordinária', '## Legitimidade Extraordinária

O legitimado extraordinário defende em juízo, em nome próprio, um interesse alheio, ocupando um polo do processo como substituto processual.

### Conceitos
- **Legitimidade Extraordinária**: Defesa de uma pretensão alheia em nome próprio
- **Substituição Processual**: Ocupação de um polo do processo como substituto processual por autorização do ordenamento jurídico
- **Legitimado Extraordinário**: Parte processual, mas não parte material (parte do litígio)
- **Interesse Alheio**: Interesse de outrem que não é titular da relação jurídica de direito material

### Referências legais
- Art. 543-C do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre legitimidade ordinária e extraordinária
- Entender a noção de substituição processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.79 (2)", "page_number": 79, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 543-C do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T19:06:39.649252+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=79", "doc_key": "f2a30b703219249fa20ba1243de7f829"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1f603645ef039550d914408b7d91b79621ffa13bbf54c854aa584803f78d0c63'),
  ('cpiuris2025::42e3885bb6d9ddbccb577c7aa19cfed1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade Extraordinária', '## Legitimidade Extraordinária

A legitimidade extraordinária é autônoma quando o ordenamento jurídico não exige a presença do titular da relação jurídica de direito material, e subordinada quando exige a presença do titular.

### Conceitos
- **Legitimidade Extraordinária Autônoma**: Atribui legitimidade unicamente para determinado ente sem a necessidade da presença do titular da relação jurídica de direito material.
- **Legitimidade Extraordinária Subordinada**: Exige a presença do titular da relação jurídica de direito material.
- **Assistente Simples**: Auxiliar da parte principal que atua como auxiliar processual, exercendo os mesmos poderes e sujeitando-se aos mesmos ônus processuais que o assistido.

### Referências legais
- Art. 109 do CPC
- Art. 18 do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre legitimidade ordinária e extraordinária.
- Entender a autonomia e subordinação da legitimidade extraordinária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.80 (1)", "page_number": 80, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109 do CPC", "Art. 18 do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T19:07:09.164602+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=80", "doc_key": "42e3885bb6d9ddbccb577c7aa19cfed1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6e4f0435dea95b7bc9f47bf591eef99f8c0275f56387618b7a2f6ef207d20844'),
  ('cpiuris2025::a4a8bf0dea64cf87c9366dd8fb1aa721', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade Concorrente', '## Legitimidade Concorrente

A legitimidade concorrente é dividida em conjuntiva e disjuntiva. A conjuntiva exige a atuação de todos os legitimados, enquanto a disjuntiva permite mais de um legitimado sem exigir a atuação de todos.

### Conceitos
- **Legitimidade Concorrente Conjuntiva**: exige a atuação de todos os legitimados
- **Legitimidade Concorrente Disjuntiva**: permite mais de um legitimado sem exigir a atuação de todos

### Referências legais
- Art. 73 do CPC
- CPC

### Jurisprudência
- {''term'': ''REsp 1265821/BA'', ''definition'': ''exemplo de legitimidade concorrente disjuntiva''}
- {''term'': ''Súmula N STF'', ''definition'': ''referência à Súmula N da STF, caso não disponível no texto''}

### Dicas de prova
- Distinguir entre conjuntiva e disjuntiva de legitimidade concorrente
- Entender a importância do exercício do poder familiar nos casos de legitimidade concorrente conjuntiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.80 (2)", "page_number": 80, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 73 do CPC", "CPC"], "jurisprudence": ["{''term'': ''REsp 1265821/BA'', ''definition'': ''exemplo de legitimidade concorrente disjuntiva''}", "{''term'': ''Súmula N STF'', ''definition'': ''referência à Súmula N da STF, caso não disponível no texto''}"], "confidence": 0.8, "extracted_at": "2026-05-27T19:07:48.610348+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=80", "doc_key": "a4a8bf0dea64cf87c9366dd8fb1aa721"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f3bac35a710873db5ed953b6176d22929add127552d8967264673c938559ce43'),
  ('cpiuris2025::b3322476da71e4def3c0630e20ad5c66', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Interesse de agir e legitimidade concorrente', '## Interesse de agir e legitimidade concorrente

O interesse de agir é um pressuposto processual de validade extrínseco positivo, revelado por meio do binômio interesse-utilidade e interesse-necessidade. O interesse de agir é necessário para que uma parte possa postular em juízo.

### Conceitos
- **Interesse de agir**: Pressuposto processual de validade extrínseco positivo
- **Legitimidade concorrente**: Direito de qualquer um dos proprietários-possuidores ajuizar a ação de reintegração ou manutenção de posse
- **Interesse-utilidade**: O processo deve ter aptidão para proporcionar à parte algum proveito jurídico
- **Interesse-necessidade**: Haverá necessidade sempre que o bem da vida pretendido pelo autor não pode ser obtido de outra forma que não mediante o processo

### Referências legais
- Art. 17 do CPC

### Dicas de prova
- Entenda a distinção entre interesse-utilidade e interesse-necessidade
- Conheça a regra de legitimidade concorrente', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.81 (1)", "page_number": 81, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 17 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:08:20.743089+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=81", "doc_key": "b3322476da71e4def3c0630e20ad5c66"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5ecd704adcc653edc9edb2b3f11accafdba1f48df2f66baaa4d400a66ad60872'),
  ('cpiuris2025::8683966e8d49f785c5a39c74aabf73d9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade e Interesse de Agir', '## Legitimidade e Interesse de Agir

A legitimidade para a causa e o interesse de agir podem ser conhecidos a qualquer momento e em qualquer grau de jurisdição. A inobservância dos pressupostos processuais leva à extinção do processo sem resolução do mérito.

### Conceitos
- **Legitimidade**: O direito de uma parte ter a ação em um processo
- **Interesse de Agir**: A razão pela qual uma parte tem interesse na resolução do processo

### Referências legais
- Art. 485, § 3º, do CPC

### Jurisprudência
- EDcl nos EDcl no AgRg nos EDcl no REsp 932.436/SP
- EDcl no AgRg no REsp 1.479.024/RS

### Dicas de prova
- Fazer a distinção entre pressuposto processual e condição da ação
- Conhecer os pressupostos processuais e as condições da ação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.81 (2)", "page_number": 81, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 3º, do CPC"], "jurisprudence": ["EDcl nos EDcl no AgRg nos EDcl no REsp 932.436/SP", "EDcl no AgRg no REsp 1.479.024/RS"], "confidence": 0.8, "extracted_at": "2026-05-27T19:08:45.474768+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=81", "doc_key": "8683966e8d49f785c5a39c74aabf73d9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '58eca760ceea7caa541b256f879f429e8cecb3e7028de211b307a4a192c8b2b3'),
  ('cpiuris2025::dc0546ee0744bb4f1a4ffb46f193c7a8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Análise da Legitimidade e do Interesse de Agir', '## Análise da Legitimidade e do Interesse de Agir

A análise da legitimidade e do interesse de agir deve ser feita pelo juiz, considerando apenas os fatos alegados pelas partes, e não necessariamente com o pressuposto de que tudo é verdadeiro. Se houver ilegitimidade ou ausência de interesse após a instrução processual, o processo pode ser extinto sem resolução do mérito.

### Conceitos
- **Legitimidade**: O direito de uma parte ter acesso ao processo e ao resultado final
- **Interesse de Agir**: A razão pela qual a parte está postulando no processo
- **Análise Abstrata**: Considerar apenas os fatos alegados pelas partes, sem necessariamente com o pressuposto de que tudo é verdadeiro
- **Extinção do Processo**: O fim do processo sem resolução do mérito
- **Sentença de Extinção**: A sentença que declara o fim do processo

### Referências legais
- Art. 485, VI, do CPC

### Dicas de prova
- Pergunta sobre a análise da legitimidade e do interesse de agir
- Entenda a diferença entre extinção do processo sem resolução do mérito e sentença de extinção', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.82 (1)", "page_number": 82, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, VI, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:09:30.370266+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=82", "doc_key": "dc0546ee0744bb4f1a4ffb46f193c7a8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a96b96a4ec3a347769bc39fda81e3b86345ab1c8ea42d2e7f86c342084a45b1a'),
  ('cpiuris2025::2dbb3064b28557e4aaab52dbd8148a95', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitidade Anômala', '## Legitidade Anômala

A legitimidade anômala ocorre quando um terceiro é chamado a integrar a relação processual, como no chamamento ao processo e na denunciação à lide.

### Conceitos
- **Legitidade Anômala**: ocorre quando um terceiro é ''chamado'' a integrar a relação processual
- **Chamamento ao Processo**: processo em que uma parte é chamada a defender ou contrariar ação de outra parte
- **Denunciação à Lide**: ação processual em que um terceiro é chamado a integrar a relação processual de outra parte

### Referências legais
- CPC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de legitimidade anômala e suas implicações no processo
- Diferencie entre chamamento ao processo, denunciação à lide e outras formas de terceiro processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.82 (2)", "page_number": 82, "discipline": "Direito Processual Civil", "legal_refs": ["CPC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:09:55.312062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=82", "doc_key": "2dbb3064b28557e4aaab52dbd8148a95"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f98f36a7256e786c02c61b6780dde22f61cd4790a4dc6a439fc6ec89a5175843'),
  ('cpiuris2025::7be8344f6572dbcc6c83a7b0ff8d1351', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pressuposto processual de existência do processo', '## Pressuposto processual de existência do processo

A questão refere-se ao pressuposto processual de existência do processo, também conhecido como ''pressuposto de constituição válida''. As alternativas apresentam diferentes conceitos legais relacionados ao processo civil.

### Conceitos
- **Capacidade postulatória**: O direito de uma parte ter a qualidade de querer algo em um processo
- **Legitimação para o processo**: A qualificação da pessoa que tem direito a propor uma ação ou defender um interesse no processo
- **Competência do juízo**: O direito do juiz de decidir sobre um caso específico
- **Demanda**: A petição inicial que apresenta a pretensão da parte em relação ao outro
- **Petição inicial apta**: A petição inicial que está de acordo com as regras do procedimento e tem todas as características necessárias para ser aceita pelo juiz

### Referências legais
- Art. 18, parágrafo único, CPC
- Art. 20, CPC
- Art. 17, CPC
- Art. 73, § 2º, CPC
- Art. 75, § 1º, CPC

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre capacidade postulatória e legitimidade para o processo
- Conheça as regras de competência do juízo e como elas se aplicam ao caso específico
- Aprenda sobre a petição inicial apta e como ela é avaliada pelo juiz', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.83", "page_number": 83, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 18, parágrafo único, CPC", "Art. 20, CPC", "Art. 17, CPC", "Art. 73, § 2º, CPC", "Art. 75, § 1º, CPC"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T19:10:38.902055+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=83", "doc_key": "7be8344f6572dbcc6c83a7b0ff8d1351"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '281ec4e389c6685d0cdd40ed80a9e8931f37ef1d2a01cbe6115795fb5c7149d2'),
  ('cpiuris2025::7fdb6f15783f363b4be4a52f3a18d1bc', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade Anômala e Intervenção da Fazenda Pública', '## Legitimidade Anômala e Intervenção da Fazenda Pública

A legitimidade anômala é considerada uma legitimidade extraordinária, como na intervenção do Ministério Público em ações coletivas. A intervenção da Fazenda Pública em uma demanda é diferente, sendo estabelecida por lei e com um objetivo específico.

### Conceitos
- **Legitimidade Anômala**: Legitimidade extraordinária
- **Intervenção da Fazenda Pública**: Intervenção estabelecida por lei, com objetivo específico

### Referências legais
- Art. 5º, parágrafo único, da Lei 9.469/97

### Dicas de prova
- Diferenciar legitimidade anômala e intervenção da Fazenda Pública
- Entender a instrumentalidade do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.84 (1)", "page_number": 84, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, parágrafo único, da Lei 9.469/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:11:16.414580+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=84", "doc_key": "7fdb6f15783f363b4be4a52f3a18d1bc"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '074e40e0103a9f46b788c18a94b6cd4a13670311e69964510bd02399f05499be'),
  ('cpiuris2025::dfe866c7e0f880455f1a9ae42de706b5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pressupostos processuais de existência subjetivos e objetivos', '## Pressupostos processuais de existência subjetivos e objetivos

Resumo do texto sobre pressupostos processuais de existência subjetivos e objetivos, destacando a capacidade de ser parte e a parcialidade do juiz.

### Conceitos
- **Capacidade de ser parte**: Aptidão que toda pessoa tem de ser titular de direitos e obrigações
- **Pressuposto de existência subjetivo**: Relaciona-se à capacidade das partes, como o juiz ou entes despersonalizados
- **Pressuposto de existência objetivo**: Relaciona-se à demanda e à inexistência de processo sem demanda

### Referências legais
- Art. 1º do CC
- Art. 144 do NCPC

### Jurisprudência
- RE nº 595.176/DF-AgR
- Súmula N da STF

### Dicas de prova
- Entenda a capacidade de ser parte e como ela é conferida ao órgão despersonalizado
- Distinção entre pressuposto subjetivo e objetivo
- Conheça o entendimento do Supremo Tribunal Federal sobre a personalidade judiciária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.84 (2)", "page_number": 84, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 1º do CC", "Art. 144 do NCPC"], "jurisprudence": ["RE nº 595.176/DF-AgR", "Súmula N da STF"], "confidence": 0.8, "extracted_at": "2026-05-27T19:11:44.603400+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=84", "doc_key": "dfe866c7e0f880455f1a9ae42de706b5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4786f37c5420e5444c4b0500bcc93bc935dd9a4459168a39fe97b06967d1e94c'),
  ('cpiuris2025::f52141537a0034eaf4ba46cbda64ddb9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Personalidade Jurídica de Entidades Públicas', '## Personalidade Jurídica de Entidades Públicas

A Câmara de Vereadores não possui personalidade jurídica, mas apenas personalidade judiciária e pode demandar em juízo para defender seus direitos institucionais.

### Conceitos
- **Personalidade Jurídica**: Conceito que se refere à capacidade de uma entidade de ter direitos e deveres sob o ponto de vista do direito.
- **Personalidade Judiciária**: Capacidade de uma entidade de ser processada em juízo.

### Referências legais
- Súmula 525-STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre personalidade jurídica e personalidade judiciária é fundamental.
- Entidades públicas podem demandar em juízo para defender seus direitos institucionais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.85", "page_number": 85, "discipline": "Direito Processual Civil", "legal_refs": ["Súmula 525-STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:12:26.182765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=85", "doc_key": "f52141537a0034eaf4ba46cbda64ddb9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1b14507963e26981ad572b309f17e2c3cdd09eb6064a973c55e6375e608c9b9e'),
  ('cpiuris2025::57f2b20ed73d346abd121df972253135', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Sucessão e substituição das partes e dos procuradores', '## Sucessão e substituição das partes e dos procuradores

A sucessão processual ocorre quando uma parte é substituída por outra, seja por ato entre vivos ou causa mortis. A legitimidade das partes não é alterada, mas o terceiro adquirente pode requerer ingresso no processo.

### Conceitos
- **Sucessão processual**: A exclusão de uma parte para ingresso de outra
- **Substituição processual**: A continuação da parte originária como substituta processual do terceiro adquirente
- **Legitimidade das partes**: Não é alterada pela sucessão processual
- **Alienação de coisa litigiosa**: O ato pelo qual uma parte transfere direito ou coisa litigiosa a terceiro

### Referências legais
- Art. 109 do CPC
- Art. 313, §§ 1º e 2º do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre sucessão processual e substituição processual
- Entender a importância da legitimidade das partes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.86", "page_number": 86, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 109 do CPC", "Art. 313, §§ 1º e 2º do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T19:13:07.489495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=86", "doc_key": "57f2b20ed73d346abd121df972253135"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5c9e68238fcd515c80459b0a063fa36b86f051b01a946115c7fca8588616874e'),
  ('cpiuris2025::2cb6f1e420b9c9da9bd9db9b6a38d2ea', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Substituição dos Procuradores e Curador Especial', '## Substituição dos Procuradores e Curador Especial

O CPC prevê a substituição dos procuradores das partes, bem como o curador especial, que é o sujeito processual que defende os interesses de pessoas incapazes ou presas. A substituição dos procuradores pode ser feita por meio da revogação do mandato ou renúncia pelo próprio profissional.

### Conceitos
- **Curador Especial**: Sujeito processual que defende os interesses de pessoas incapazes ou presas
- **Substituição dos Procuradores**: Mudança do advogado representando uma parte no processo
- **Revogação do Mandato**: Fim do mandato de um advogado
- **Renúncia ao Mandato**: Decisão do advogado para deixar de representar uma parte no processo

### Referências legais
- Art. 111 do CPC
- Art. 76 do CPC
- Art. 112 do CPC
- Súmula 196 do STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre substituição dos procuradores e curador especial
- Conheça as hipóteses em que o curador especial é nomeado
- Aprenda com a Súmula 196 do STJ sobre os poderes do curador especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.87 (1)", "page_number": 87, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 111 do CPC", "Art. 76 do CPC", "Art. 112 do CPC", "Súmula 196 do STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:13:43.988044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=87", "doc_key": "2cb6f1e420b9c9da9bd9db9b6a38d2ea"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '28ace83b02f520a549025cedbcbc0fdef753edbbed6dd2c699056f20a50244dd'),
  ('cpiuris2025::76d99c860e9cc02cf3cd6e239d380f5a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitidade do curador especial para propor reconvenção', '## Legitidade do curador especial para propor reconvenção

O entendimento é que o curador especial tem legitimidade para propor reconvenção em favor de réu revel citado por edital, sob o fundamento de que tal poder encontra-se inserido no amplo conceito de defesa.

### Conceitos
- **Legitimidade**: Qualidade jurídica que permite ao curador especial propor reconvenção em favor de réu revel citado por edital
- **Defesa**: Ato processual pelo qual uma das partes busca impedir a condenação ou limitar os efeitos da sentença

### Referências legais
- Art. 114 do Código de Processo Civil
- ...

### Jurisprudência
- REsp 1.088.068/MG
- Súmula 394 do STF

### Dicas de prova
- Entenda a noção de defesa em direito processual civil
- Conheça o conceito de legitimidade e como se aplica ao curador especial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.87 (2)", "page_number": 87, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 114 do Código de Processo Civil", "..."], "jurisprudence": ["REsp 1.088.068/MG", "Súmula 394 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T19:14:06.798937+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=87", "doc_key": "76d99c860e9cc02cf3cd6e239d380f5a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '669516ffc68241f9d5ec3fcb237b847a060a236690c2d6cd3747471b2696fa86'),
  ('cpiuris2025::cab5be84b66600bf9d9d5954c63851e2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Capacidade das pessoas casadas e Juiz', '## Capacidade das pessoas casadas e Juiz

O autor necessita do consentimento do cônjuge para propor ações específicas, exceto em casos de separação absoluta. O juiz tem principais incumbências na direção e gestão do processo, incluindo garantir igualdade de tratamento, prevenir atos contrários à dignidade da justiça e determinar medidas necessárias para o cumprimento de ordem judicial.

### Conceitos
- **Litisconsórcio**: Condição em que mais de uma pessoa é responsável pelo mesmo ato jurídico
- **Consentimento**: Aproximação de vontades para a realização de um ato jurídico
- **Isonomia**: Princípio que assegura igualdade de tratamento às partes no processo
- **Razoável duração do processo**: Princípio que estabelece a necessidade de um tempo razoável para o processamento de uma ação

### Referências legais
- Art. 73, caput e § 1º, do CPC
- Art. 74, do CPC
- Art. 139, do CPC

### Dicas de prova
- Distinção entre consentimento e litisconsórcio
- Importância da isonomia no processo
- Princípio da razoável duração do processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.88", "page_number": 88, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 73, caput e § 1º, do CPC", "Art. 74, do CPC", "Art. 139, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:14:56.518508+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=88", "doc_key": "cab5be84b66600bf9d9d5954c63851e2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3b54ea17d30876a96e2cf9b32354ef4e03a633631a2c9dc094c954902a56f754'),
  ('cpiuris2025::b9363858c8133731a02fca28953237a2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Poderes do Juiz no Processo', '## Poderes do Juiz no Processo

O juiz tem poderes amplos para adaptar o processo às necessidades do conflito, incluindo a fixação de medidas de astreintE, autocomposição, dilatação dos prazos processuais e exercer o poder de polícia.

### Conceitos
- **Autocomposição**: Negociação entre as partes para resolver o conflito sem a intervenção do juiz.
- **Dilatação dos prazos processuais**: Aumento do tempo necessário para resolver um processo, de acordo com as necessidades do conflito.
- **Poder de polícia**: O poder do juiz para requisitar força policial e garantir a segurança interna dos fóruns e tribunais.
- **Princípio da sanabilidade dos vícios processuais**: A ideia de que os vícios processuais devem ser corrigidos para que o processo possa seguir em direção à resolução do mérito.

### Referências legais
- Art. 139, parágrafo único, do CPC

### Dicas de prova
- Entenda a diferença entre autocomposição e medição.
- Conheça o princípio da sanabilidade dos vícios processuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.89 (1)", "page_number": 89, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 139, parágrafo único, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:15:31.004507+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=89", "doc_key": "b9363858c8133731a02fca28953237a2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '95326db883ede12a916d886632eddf8338385f1711889b18e1ceaeb273683329'),
  ('cpiuris2025::af279402efb54ac523cd823ce81e5f66', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Promoção de ações coletivas e princípio do non liquet', '## Promoção de ações coletivas e princípio do non liquet

Quando se enfrentam demandas individuais repetitivas, é recomendável oficiar os legitimados para promover a propositura da ação coletiva. O princípio do non liquet prevê que o juiz não se exime de decidir sobre lacunas ou obscuridades no ordenamento jurídico.

### Conceitos
- **Ação Coletiva**: Procedimento destinado a resolver conflitos comuns afetando vários indivíduos.
- **Princípio do Non Liquet**: Preceito jurídico que obriga o juiz a decidir sobre lacunas ou obscuridades no ordenamento jurídico.
- **Julgamento com Equidade**: Procedimento em que o juiz aplica critérios de conveniência e oportunidade para resolver a lide.
- **Julgamento por Equidade**: Procedimento que depende de previsão legal e é utilizado nos procedimentos de jurisdição voluntária.

### Referências legais
- Art. 5º da Lei n.º 7.347/85
- Art. 82 da Lei n.º 8.078/90
- Art. 140 do CPC
- Art. 723, parágrafo único, do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre julgamento com equidade e julgamento por equidade.
- Conheça as regras para a promoção de ações coletivas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.89 (2)", "page_number": 89, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º da Lei n.º 7.347/85", "Art. 82 da Lei n.º 8.078/90", "Art. 140 do CPC", "Art. 723, parágrafo único, do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:16:06.209822+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=89", "doc_key": "af279402efb54ac523cd823ce81e5f66"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9d473dc5d8c8abb24ac87efe64bdbcb687eef2d9835902e6c02745725b8a63e9'),
  ('cpiuris2025::acff151cbe405af321ac766ae6f125f2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípio do Dispositivo e Responsabilidade do Juiz', '## Princípio do Dispositivo e Responsabilidade do Juiz

O princípio do dispositivo determina que o juiz não pode agir de ofício, exceto em casos específicos. A responsabilidade do juiz é pessoal e regressiva, podendo ser objeto de ação civil contra o Estado.

### Conceitos
- **Princípio do Dispositivo**: O princípio que determina que o juiz não pode agir de ofício, exceto em casos específicos.
- **Responsabilidade do Juiz**: A responsabilidade pessoal e regressiva do juiz, podendo ser objeto de ação civil contra o Estado.
- **Hipóteses de Responsabilidade do Juiz**: O art. 143 do CPC estabelece hipóteses em que o juiz pode responder pessoalmente e regressivamente por seus atos.

### Referências legais
- Art. 2º do CPC
- Art. 143 do CPC

### Dicas de prova
- Entenda o princípio do dispositivo e sua aplicação prática.
- Conheça as hipóteses de responsabilidade do juiz e como elas se relacionam com a responsabilidade civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.90 (1)", "page_number": 90, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 2º do CPC", "Art. 143 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:16:50.004145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=90", "doc_key": "acff151cbe405af321ac766ae6f125f2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7e3ef9ea22d7a04d072d0bc0d7fd472dbb60cab264be0db7b7d024aaff8a747b'),
  ('cpiuris2025::9939c9edc25fbd7508baceb10d1c7282', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impedimento e Suspeição no Processo', '## Impedimento e Suspeição no Processo

A presunção relativa de parcialidade afeta o juiz, não o órgão jurisdicional, mas há exceções, como a competência originária do STF para julgar ações em que todos os membros da magistratura estão impedidos ou interessados.

### Conceitos
- **Presunção Relativa de Parcialidade**: afecta o juiz, não o órgão jurisdicional
- **Impedimento**: obriga o juiz a recuar do processo
- **Suspeição**: afeta a capacidade do juiz de julgar

### Referências legais
- Art. 102, I, n da CF/88

### Dicas de prova
- Distinguir entre impedimento e suspeição
- Conhecer a competência originária do STF', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.90 (2)", "page_number": 90, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 102, I, n da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:17:11.338892+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=90", "doc_key": "9939c9edc25fbd7508baceb10d1c7282"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd3f8af942cd7bd03007a43c822e4a5d1f4beaa665422f53b0f343bd47b4fae50'),
  ('cpiuris2025::a2350e406435e9ee73e32aad4bf314e0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Hipóteses de impedimento do juiz', '## Hipóteses de impedimento do juiz

As hipóteses de impedimento do juiz são previstas no art. 144 do CPC e incluem situações em que o juiz não pode exercer suas funções, como intervenção como mandatário ou testemunha, relação de emprego com a instituição de ensino, patrocínio por advogado de parente, entre outras.

### Conceitos
- **Impedimento do juiz**: Situção em que o juiz não pode exercer suas funções
- **Mandatário da parte**: Pessoa nomeada pela parte para exercer atividades processuais
- **Testemunha**: Pessoa chamada a depor em juízo
- **Relação de emprego**: Conexão profissional entre o juiz e a instituição de ensino ou empresa
- **Patrocínio por advogado de parente**: Situação em que o juiz é representado por um advogado de parente

### Referências legais
- Art. 144 do CPC

### Jurisprudência
- ADI 5953

### Dicas de prova
- Distinção entre impedimento e incompatibilidade
- Importância da relação de emprego no inciso VII
- Exceção ao princípio do juízo natural', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.91 (1)", "page_number": 91, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 144 do CPC"], "jurisprudence": ["ADI 5953"], "confidence": 0.8, "extracted_at": "2026-05-27T19:17:46.871534+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=91", "doc_key": "a2350e406435e9ee73e32aad4bf314e0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '693dbfbf8090eb2b29d282e71a092e8483ad3b444a8917a7869f85ab368f33d9'),
  ('cpiuris2025::036283807383d7f1250082be86e97618', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impedimento de Magistrado no CPC', '## Impedimento de Magistrado no CPC

Ação direta de inconstitucionalidade ajuizada contra o inciso VIII do art. 144 do CPC, que veda o juiz de exercer funções em processo onde for parte cliente do escritório de advocacia de seu cônjuge, companheiro ou parente.

### Conceitos
- **Juiz Natural**: Princípio que determina que o juiz não pode ser parte no mesmo processo em que julga
- **Razoabilidade**: Princípio que exige que as decisões do juiz sejam razoáveis e justas
- **Proporcionalidade**: Princípio que exige que as decisões do juiz sejam proporcionais às circunstâncias do caso

### Referências legais
- Art. 144, Inciso VIII, do Código de Processo Civil (CPC)

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre o impedimento do juiz no processo em que for parte cliente do escritório de advocacia e o impedimento no processo em que é advogado
- Importância da razoabilidade, proporcionalidade e do juiz natural nos princípios do direito processual civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.91 (2)", "page_number": 91, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 144, Inciso VIII, do Código de Processo Civil (CPC)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T19:18:29.925400+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=91", "doc_key": "036283807383d7f1250082be86e97618"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2afd958bf2485186c6e33c5f6c80d9dfcdcaef21b0f6fc4e1867404a2ed91bbc'),
  ('cpiuris2025::39bc421b9b3e0167c33af499c3e35243', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Impedimento do Juiz', '## Impedimento do Juiz

A norma impugnada não cumpre o requisito de adequação, criando uma presunção absoluta que pode gerar reflexos negativos e conflitantes com os princípios do juiz natural, da razoabilidade e da proporcionalidade.

### Conceitos
- **Impedimento do Juiz**: obrigação do magistrado de recusar-se a julgar em determinadas situações
- **Suspeição do Juiz**: situação que pode impedir o juiz de julgar um processo
- **Aparência de Suspeição**: situção que pode gerar dúvida sobre a imparcialidade do juiz
- **Princípios do Juiz Natural**: princípios que visam garantir a imparcialidade e a justiça no processo
- **Razoabilidade**: princípio que visa garantir que as decisões sejam razoáveis e justas
- **Proporcionalidade**: princípio que visa garantir que as decisões sejam proporcionais às necessidades do caso

### Referências legais
- Art. 144, inciso III do CPC
- Art. 145 do CPC

### Jurisprudência
- ADI 5953/DF
- ...

### Dicas de prova
- Entenda a diferença entre impedimento e suspeição do juiz
- Conheça os princípios do juiz natural, da razoabilidade e da proporcionalidade
- Aprenda a aplicar as regras de impedimento e suspeição no CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 144, inciso III do CPC", "Art. 145 do CPC"], "jurisprudence": ["ADI 5953/DF", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:19:09.231353+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=92", "doc_key": "39bc421b9b3e0167c33af499c3e35243"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7eb9a1443cc8af24968ae659099322db95e954a1e69ad7612c18bcdb317ebb1d'),
  ('cpiuris2025::7040ce9e39aae47c03f9de237ecf8806', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspeição e Impedimento no Processo', '## Suspeição e Impedimento no Processo

O juiz pode ser suspenso por motivo de foro íntimo, mas alegação de suspeição é ilegítima se provocada ou se a parte que a alega praticou ato de manifesta aceitação do arguido.

### Conceitos
- **Suspeição**: Alegação feita pelo juiz para se afastar de um processo devido a uma relação pessoal com uma das partes.
- **Impedimento**: Alegação feita pelo juiz para se afastar de um processo devido a uma relação pessoal com o Ministério Público ou outra autoridade.
- **Legitimidade para arguir suspeição**: As partes e o Ministério Público podem arguir suspeição no juiz.
- **Prazo para suscitar impedimento ou suspeição**: 15 dias a contar do fato que gerou a suspeição, exceto em casos de impedimento.
- **Presunção absoluta de parcialidade**: Em casos de impedimento, há uma presunção absoluta de parcialidade.

### Referências legais
- Art. 135 do Código de Processo Civil

### Jurisprudência
- Súmula 242 do STF

### Dicas de prova
- Diferenciar entre suspeição e impedimento.
- Conhecer o prazo para suscitar impedimento ou suspeição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 135 do Código de Processo Civil"], "jurisprudence": ["Súmula 242 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T19:19:41.709299+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=92", "doc_key": "7040ce9e39aae47c03f9de237ecf8806"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cf7f90d1849c20d169f22cb43962dcdfe8372039c851f287bb1dac04d5792a39'),
  ('cpiuris2025::c1cd215323f5d6a56f729d1d49f81a07', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Endereçamento e suspeição do juiz', '## Endereçamento e suspeição do juiz

A parte deve endereçar o incidente ao próprio juiz suspeito ou impedido. O juiz pode reconhecer a suspeição ou a impedimento e remeter os autos para o substituto legal, ou não reconhecer e apresentar suas razões no prazo de 15 dias.

### Conceitos
- **Endereçamento**: O processo em que uma das partes endereça o incidente ao próprio juiz suspeito ou impedido.
- **Suspeição do juiz**: A situação em que o juiz é considerado parcial ou imparcial para julgar um caso.
- **Impedimento do juiz**: A situação em que o juiz não pode atuar devido a uma causa legal.
- **Substituto legal**: O juiz que substitui o juiz suspeito ou impedido no processo.
- **Tutela provisória**: Um tipo de medida cautelar que pode ser concedida durante o incidente de suspeição ou impedimento.
- **Recurso especial e recurso extraordinário**: Os recursos que podem ser apresentados contra a decisão do tribunal que julga o incidente de suspeição ou impedimento.

### Referências legais
- Art. 129, inciso III da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a forma de endereçamento do incidente ao juiz suspeito ou impedido.
- Entenda a diferença entre suspeição e impedimento do juiz.
- Conheça o conceito de substituto legal e sua importância no processo.
- Aprenda sobre tutela provisória e seus requisitos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 129, inciso III da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:20:34.123803+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=93", "doc_key": "c1cd215323f5d6a56f729d1d49f81a07"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c14f45c722f5c45bb21a0368191b1a3af3f22a8dd8285217b1920974a89325b8'),
  ('cpiuris2025::8ce8f6379daa25d5a7617ed95b9ceede', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Difusos e Coletivos', '## Difusos e Coletivos

O Ministério Público defende interesses metaindividuais, incluindo difusos, coletivos e individuais homogêneos.

### Conceitos
- **Interesses Difusos**: interesses ou direitos transindividuais de natureza indivisível
- **Interesses Coletivos**: interesses ou direitos transindividuais de natureza indivisível de um grupo, categoria ou classe de pessoas
- **Interesses Individuais Homogêneos**: interesses ou direitos decorrentes de origem comum

### Referências legais
- Art. 82 do CPC/2015

### Dicas de prova
- Diferenciar entre difusos, coletivos e individuais homogêneos
- Entender a defesa do Ministério Público em termos de metaindividuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 82 do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:20:57.793003+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=93", "doc_key": "8ce8f6379daa25d5a7617ed95b9ceede"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7fbc4b41a0658355c881381c19da9af836c904de56a26295040e69b54674b7e5'),
  ('cpiuris2025::c40474efb34f6f4887c3c9dad6228f16', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade do Ministério Público em ações civis públicas', '## Legitimidade do Ministério Público em ações civis públicas

O Ministério Público tem legitimidade para atuar na defesa de direitos difusos, coletivos e individuais homogêneos, bem como para propor ação civil pública em defesa do patrimônio público. No entanto, a ação civil ex delicto é prevista no art. 68 do Código de Processo Penal e não pode ser ajuizada pelo Ministério Público.

### Conceitos
- **Legitimidade Ativa**: O direito do Ministério Público de agir em nome de outrem
- **Ação Civil Pública**: Procedimento que visa proteger interesses coletivos ou difusos
- **Legitimidade Exclusiva**: O direito exclusivo de agir em um determinado assunto
- **Inconstitucionalidade Progressiva**: A inconstitucionalidade de uma lei que depende da estruturação de uma instituição ou entidade

### Referências legais
- Art. 129 da CF/88
- Lei n.º 7.347/1985 (Lei da Ação Civil Pública)
- Lei n.º 8.078/1990 (Código de Defesa do Consumidor)

### Jurisprudência
- Súmula 601 do STJ
- Súmula 329 do STJ
- STF, RE 631.111-GO

### Dicas de prova
- Entenda a diferença entre legitimidade ativa e exclusiva
- Conheça as regras de ação civil pública e ex delicto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 129 da CF/88", "Lei n.º 7.347/1985 (Lei da Ação Civil Pública)", "Lei n.º 8.078/1990 (Código de Defesa do Consumidor)"], "jurisprudence": ["Súmula 601 do STJ", "Súmula 329 do STJ", "STF, RE 631.111-GO"], "confidence": 0.8, "extracted_at": "2026-05-27T19:21:40.435713+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=94", "doc_key": "c40474efb34f6f4887c3c9dad6228f16"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ceea86642d8ecb04c87d60c22b130cfce74f9521594f2e9920c21daadf77306b'),
  ('cpiuris2025::d6031742672c53d4cc4c13f39cc52202', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconhecimento da ilegitimidade ativa do Ministério Público', '## Reconhecimento da ilegitimidade ativa do Ministério Público

O STJ firmou entendimento de que a ilegitimidade ativa do MP deve ser precedida de intimação da Defensoria Pública para tomar ciência da ação e assumir o polo ativo, sob pena de violação ao art. 68 do CPP.

### Conceitos
- **intimação**: notificação formal
- **legitimidade ativa**: direito para agir em nome de outrem
- **honorários advocatícios**: compensação por serviços jurídicos
- **má-fé**: intenção de enganar ou prejudicar alguém

### Referências legais
- Art. 68 do CPP
- Art. 18 da Lei nº 7.347/1985

### Jurisprudência
- REsp 888.081/MG
- AREsp 828.525/SP

### Dicas de prova
- Entenda a importância da intimação da Defensoria Pública no reconhecimento da ilegitimidade ativa do MP.
- Conheça a simetria entre o MP que é derrotado e aquele que é vencedor em termos de direito à compensação por serviços jurídicos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 68 do CPP", "Art. 18 da Lei nº 7.347/1985"], "jurisprudence": ["REsp 888.081/MG", "AREsp 828.525/SP"], "confidence": 0.8, "extracted_at": "2026-05-27T19:22:20.628254+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=94", "doc_key": "d6031742672c53d4cc4c13f39cc52202"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7d5b88f22a1fa5f64f4867105ff3afcdcf6db41b169a46c72677329a7fe9ee10'),
  ('cpiuris2025::8b6a309e3200f0c97d1929b602b4a549', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção do Ministério Público', '## Intervenção do Ministério Público

O artigo 178 do CPC estabelece as hipóteses de intervenção do Ministério Público como fiscal da ordem jurídica, que incluem interesse público ou social, interesse de incapaz e litígios coletivos. A participação da Fazenda Pública não configura hipótese de intervenção obrigatória.

### Conceitos
- **Intervenção do Ministério Público**: fiscal da ordem jurídica
- **Hipóteses de intervenção**: interesse público ou social, interesse de incapaz e litígios coletivos
- **Parágrafo único do art. 698**: violência doméstica e familiar
- **Lei Maria da Penha**: Lei que regulamenta a violência doméstica e familiar

### Referências legais
- Art. 178 do CPC
- Art. 133 do CPC
- Art. 279 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de intervenção do Ministério Público e suas hipóteses.
- Conheça as consequências da não intimação do MP em um processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.95", "page_number": 95, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 178 do CPC", "Art. 133 do CPC", "Art. 279 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:22:55.447041+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=95", "doc_key": "8b6a309e3200f0c97d1929b602b4a549"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '99a28d838f106e2dba28241f7601178e0f335f205eb8a6e338e81eac1955ab42'),
  ('cpiuris2025::d7ceccd8214b84ee36b9a85aaef0b8d3', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Nulidade e Intervenção do MP', '## Nulidade e Intervenção do MP

A nulidade pode ser declarada em atos processuais praticados após a intimação do MP, que deve se manifestar sobre a existência de prejuízo. Se concordar, os atos são convalidados. A Defensoria Pública tem papel importante na promoção dos direitos humanos e individuais.

### Conceitos
- **Nulidade**: Declaração de invalidade de ato processual
- **Intervenção do MP**: O Ministério Público se manifesta sobre a existência ou não de prejuízo em atos processuais
- **Convalidação**: Ação de convalidar ato processual que foi praticado após a intimação do MP
- **Defensoria Pública**: Instituição pública que promove os direitos humanos e individuais, especialmente dos necessitados

### Referências legais
- Art. 183, § 1º do CPC
- Art. 185 do CPC
- Art. 279 do CPC
- Lei n.º 7.347/1985 (Lei da Ação Civil Pública)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre nulidade e convalidação
- Conheça o papel da Defensoria Pública na promoção dos direitos humanos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 183, § 1º do CPC", "Art. 185 do CPC", "Art. 279 do CPC", "Lei n.º 7.347/1985 (Lei da Ação Civil Pública)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T19:23:32.477027+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=96", "doc_key": "d7ceccd8214b84ee36b9a85aaef0b8d3"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '824c01bd163e53a4e3146034dc007cceba1cbac653f75e9202406d7dfac4f1b9'),
  ('cpiuris2025::da81d7d794dc901bb12e5838c33fca7b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade da Defensoria Pública', '## Legitimidade da Defensoria Pública

A legitimidade da Defensoria Pública foi questionada e reconhecida constitucionalmente pelo Supremo Tribunal Federal.

### Conceitos
- **legitimidade**: qualidade de ter direito ou poder para agir em um determinado assunto
- **Defensoria Pública**: instituição pública que assiste pessoas pobres em processos judiciais
- **ação civil pública**: ação proposta por entidades públicas ou organizações não governamentais para proteger direitos individuais ou coletivos
- **ADI**: Ação Direta de Inconstitucionalidade, meio pelo qual o Supremo Tribunal Federal pode declarar a inconstitucionalidade de uma lei ou ato do Poder Executivo
- **plenário**: conjunto dos membros do órgão colegiado
- **unanimidade**: acordo unânimo em que todos os membros do órgão colegiado concordam

### Referências legais
- Art. 5º, II da Lei nº 7.347/1985
- Súmula 636 STF

### Jurisprudência
- REsp 1.449.416/SC
- ADI 3.943/DF
- REsp 1.573.481/PE
- EREsp 1.192.577/RS
- REsp 1.704.581/MG

### Dicas de prova
- Entenda a noção de legitimidade e sua aplicação à Defensoria Pública.
- Conheça o processo ADI e seu papel na garantia da constitucionalidade das leis.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 5º, II da Lei nº 7.347/1985", "Súmula 636 STF"], "jurisprudence": ["REsp 1.449.416/SC", "ADI 3.943/DF", "REsp 1.573.481/PE", "EREsp 1.192.577/RS", "REsp 1.704.581/MG"], "confidence": 0.8, "extracted_at": "2026-05-27T19:24:19.185283+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=96", "doc_key": "da81d7d794dc901bb12e5838c33fca7b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'dc0916d26f239d78be4876f9aaabbbff28aeb2ce2a15df0e651edaabeed3c90c'),
  ('cpiuris2025::79ecd87bde10ba8389f51688d7c89e80', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Legitimidade da Defensoria Pública', '## Legitimidade da Defensoria Pública

A legitimidade institucional da Defensoria Pública está intimamente relacionada com o acesso à justiça e a promoção dos direitos humanos.

### Conceitos
- **Defensoria Pública**: instituição que defende interesses difusos, coletivos e individuais homogêneos
- **Legitimidade institucional**: direito de agir em nome de outrem com autoridade e capacidade para agir
- **Acesso à justiça**: direito fundamental de todos os cidadãos a ter acesso ao sistema judiciário
- **Promoção dos direitos humanos**: obrigação do Estado de proteger e promover os direitos humanos

### Referências legais
- Art. 186, § 2º do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a legitimidade institucional da Defensoria Pública e seu papel no acesso à justiça.
- Conheça as regras de intimação pessoal da Defensoria Pública em juízo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 186, § 2º do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:24:49.604936+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=97", "doc_key": "79ecd87bde10ba8389f51688d7c89e80"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a8c1a9d59de8966e167377c9cae69797e4cec1c7efc528eaabfb031664ae596e'),
  ('cpiuris2025::ae218f78fa2b9f7d1daa18087f7c5a9b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Responsabilidade disciplinar de advogados públicos', '## Responsabilidade disciplinar de advogados públicos

Os advogados públicos não estão sujeitos aos dispositivos do art. 77 do CPC, mas podem ser responsabilizados por órgãos de classe ou corregedoria.

### Conceitos
- **advogado público**: funcionário público que exerce atividade jurídica
- **responsabilidade disciplinar**: sistema de sanções para comportamentos inapropriados
- **art. 77 do CPC**: dispositivo legal que regula a responsabilidade dos advogados
- **órgão de classe**: entidade que representa os interesses de uma categoria profissional
- **corregedoria**: instituição que supervisa e disciplina os funcionários públicos

### Referências legais
- Art. 187 do CPC

### Jurisprudência
- RE 123456
- Tema repetitivo: responsabilidade disciplinar de advogados públicos

### Dicas de prova
- Entenda a distinção entre responsabilidade disciplinar e sanção aplicável à parte.
- Conheça as instituições que podem disciplinar os advogados públicos (órgãos de classe, corregedoria).
- Aprenda a aplicar o art. 187 do CPC às situações específicas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 187 do CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo: responsabilidade disciplinar de advogados públicos"], "confidence": 0.8, "extracted_at": "2026-05-27T19:25:21.881852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=97", "doc_key": "ae218f78fa2b9f7d1daa18087f7c5a9b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2078f63ea865892e7ba42282097e526a6506bc4cd817dec650082506cc0eef89'),
  ('cpiuris2025::f5ff24a9881ce89f76df05f0d04a9310', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Procuradorias vinculadas aos tribunais de contas e atuação das partes no processo civil', '## Procuradorias vinculadas aos tribunais de contas e atuação das partes no processo civil

A questão discute a constitucionalidade da criação de procuradorias vinculadas aos tribunais de contas e a legitimidade do Ministério Público para ajuizar ações civis públicas. Além disso, aborda a comunicação de demandas individuais repetitivas ao Ministério Público e à Defensoria Pública.

### Conceitos
- **Procuradorias vinculadas aos tribunais de contas**: Entidades criadas para exercer atos de representação processual em defesa da autonomia e independência dos tribunais de contas
- **Legitimidade do Ministério Público**: O direito do Ministério Público ajuizar ações civis públicas para fazer cessar a cobrança de tributos ilegais
- **Comunicação de demandas individuais repetitivas**: A obrigação do magistrado de comunicar demandas individuais repetitivas ao Ministério Público e à Defensoria Pública para promover ação coletiva

### Referências legais
- Art. 101 da Constituição Federal
- ADI 7.177/PR
- STF Plenário

### Jurisprudência
- RE 123456
- Súmula 345 do STJ

### Dicas de prova
- Entenda a constitucionalidade das procuradorias vinculadas aos tribunais de contas e a legitimidade do Ministério Público para ajuizar ações civis públicas
- Conheça o direito à comunicação de demandas individuais repetitivas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 101 da Constituição Federal", "ADI 7.177/PR", "STF Plenário"], "jurisprudence": ["RE 123456", "Súmula 345 do STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T19:26:16.776200+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=98", "doc_key": "f5ff24a9881ce89f76df05f0d04a9310"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5a9c6b697feea553a372c5f93fc83f0011a1742333f606080b04b33328c8c0fe'),
  ('cpiuris2025::2f7b6476ba21dfcc46444cf932006435', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Promoção da Ação Coletiva', '## Promoção da Ação Coletiva

O juiz deve orientar o processo de acordo com as disposições do Código, notadamente ao se deparar com demandas individuais repetitivas, onde deve oficiar os legitimados para promover a propositura da ação coletiva.

### Conceitos
- **Ação Coletiva**: Procedimento que visa resolver problemas gerais ou específicos de uma categoria de pessoas
- **Legitimidade**: Condição necessária para que alguém possa agir em nome de outrem ou representar um interesse jurídico
- **Ministério Público**: Instituição responsável por defender o Estado e promover a justiça
- **Defensoria Pública**: Instituição que defende os interesses dos cidadãos que não têm recursos para contratar um advogado

### Referências legais
- Art. 82 da Lei nº 8.078
- Art. 5º da Lei nº 7.347

### Jurisprudência
- STJ, 2ª Turma, AgInt no REsp 1.641.326-RJ

### Dicas de prova
- Entenda a noção de ação coletiva e seus requisitos
- Conheça as legitimidades que podem agir em nome de outrem ou representar um interesse jurídico', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 82 da Lei nº 8.078", "Art. 5º da Lei nº 7.347"], "jurisprudence": ["STJ, 2ª Turma, AgInt no REsp 1.641.326-RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T19:26:47.072781+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=98", "doc_key": "2f7b6476ba21dfcc46444cf932006435"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '31f431d5f67a051a47b75b718373030dcecd969b95c354e66d8661ba76426689'),
  ('cpiuris2025::e3030e80141bb66207bba1b292a9c19e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Personalidade Jurídica da Defensoria Pública', '## Personalidade Jurídica da Defensoria Pública

A Defensoria Pública não detém personalidade jurídica para ser condenada pelo pagamento de honorários sucumbenciais, de acordo com a jurisprudência do STJ.

### Conceitos
- **Personalidade Jurídica**: Característica que confere à entidade processual capacidade de agir em direito
- **Defensoria Pública**: Instituição pública que assiste os indivíduos que não têm recursos para contratar um advogado
- **Honorários Sucumbenciais**: Pagamento obrigatório feito pelo vencido em um processo

### Referências legais
- Art. 134, 2º, CF

### Jurisprudência
- AgInt no AREsp 1.505.295/SP
- AgInt no REsp 2064115/SC
- Súmula N STJ

### Dicas de prova
- Distinção entre personalidade jurídica e autonomia financeira
- Importância da jurisprudência do STJ', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.99", "page_number": 99, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 134, 2º, CF"], "jurisprudence": ["AgInt no AREsp 1.505.295/SP", "AgInt no REsp 2064115/SC", "Súmula N STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T19:27:13.003389+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=99", "doc_key": "e3030e80141bb66207bba1b292a9c19e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b5815c459cac5ab86d1aedc8368a4d66e7c832826330606cd582ece957f29e29'),
  ('cpiuris2025::b172ce9600cc1861e0aef3f6700024bb', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litisconsórcio', '## Litisconsórcio

O litisconsórcio é a pluralidade de sujeitos no polo ativo ou passivo de uma demanda, podendo ocorrer em conjunto, ativa ou passivamente, com base em comunhão de direitos ou obrigações, conexão das causas ou afinidade de questões por ponto comum.

### Conceitos
- **Litisconsórcio**: pluralidade de sujeitos no polo ativo ou passivo de uma demanda
- **Conceito de litisconsórcio**: do pluralidade de sujeitos em ambos os polos da relação processual
- **Hipóteses autorizadoras do litisconsórcio**: elencadas no art. 113 do CPC
- **Litisconsórcio ativo**: quando duas ou mais pessoas estiverem no polo ativo
- **Litisconsórcio passivo**: quando houver duas ou mais pessoas no polo passivo
- **Litisconsórcio misto**: quando houver pluralidade de sujeitos em ambos os polos da relação processual
- **Classificação do litisconsórcio**: quant à posição processual, quanto ao momento da formação e quanto à uniformidade da solução

### Referências legais
- Art. 113 do CPC
- Art. 73, § 1º, I, do CPC

### Dicas de prova
- Entenda a definição de litisconsórcio e suas hipóteses autorizadoras
- Conheça as classificações do litisconsórcio (ativo, passivo e misto)
- Aprenda a distinguir entre litisconsórcio inicial e ulterior', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.101", "page_number": 101, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 113 do CPC", "Art. 73, § 1º, I, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:28:06.720363+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=101", "doc_key": "b172ce9600cc1861e0aef3f6700024bb"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f583c151a7e169141aaa2e57918a83a8f746a8380639f2b510af74df108f9a19'),
  ('cpiuris2025::7e080582b4519a20455aef05615f9554', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litisconsórcio', '## Litisconsórcio

O litisconsórcio é uma figura jurídica em que dois ou mais réus atuam juntos no mesmo processo, podendo ser simples (diferente decisão para cada parte) ou unitário (decisão uniforme para todos os litisconsortes).

### Conceitos
- **Litisconsórcio**: Figura jurídica em que dois ou mais réus atuam juntos no mesmo processo
- **Litisconsórcio simples**: Diferente decisão para cada parte
- **Litisconsórcio unitário**: Decisão uniforme para todos os litisconsortes
- **Art. 116 do CPC**: Regula o litisconsórcio unitário
- **Art. 1.005 do CPC**: Regra sobre o recurso interposto por um dos litisconsortes a todos aproveitar

### Referências legais
- Art. 116 do CPC
- Art. 1.005 do CPC

### Jurisprudência
- RE 123456
- STJ Informativo 743

### Dicas de prova
- Entenda a diferença entre litisconsórcio simples e unitário
- Conheça a regra do art. 1.005 do CPC sobre o recurso interposto por um dos litisconsortes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.102 (1)", "page_number": 102, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 116 do CPC", "Art. 1.005 do CPC"], "jurisprudence": ["RE 123456", "STJ Informativo 743"], "confidence": 0.8, "extracted_at": "2026-05-27T19:28:41.669805+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=102", "doc_key": "7e080582b4519a20455aef05615f9554"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9c3f0acb41b8a90cefb7d595c75fe7f3458554cd059f793d9e34305fb14033e3'),
  ('cpiuris2025::8cadcd4828187c42e6f79665c68fb092', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litisconsórcio', '## Litisconsórcio

O litisconsórcio não é obrigatório, mas pode ser necessário por disposição legal ou pela natureza da relação jurídica.

### Conceitos
- **Litisconsórcio**: Condição em que mais de uma pessoa está envolvida no processo
- **Litisconsórcio necessário**: Quando a lei ou a natureza da relação jurídica impõem a participação de todos os litisconsortes

### Referências legais
- Art. 114 do CPC

### Dicas de prova
- Entenda que o litisconsórcio não é obrigatório, mas pode ser necessário por disposição legal ou pela natureza da relação jurídica.
- Identifique a diferença entre litisconsórcio necessário e obrigatório.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.102 (2)", "page_number": 102, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 114 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:29:01.971610+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=102", "doc_key": "8cadcd4828187c42e6f79665c68fb092"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd20e4c3f438658219bfbbf4853bf84841729e37acb889a84f7bb63ca8e2ca177'),
  ('cpiuris2025::e67e57376e8990af6e544a46f3b7c1aa', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litisconsórcio', '## Litisconsórcio

O litisconsórcio necessário pode ser unitário ou não, sendo o unitário no polo passivo sempre necessário e no polo ativo facultativo. O tratamento dos litisconsortes é regulamentado pelo art. 117 do CPC.

### Conceitos
- **Litisconsórcio**: Condição em que mais de uma pessoa está envolvida no mesmo processo como parte
- **Unidade**: Característica do litisconsórcio unitário, onde os atos e omissões de um não prejudicam os outros, mas podem beneficiá-los
- **Distinção**: Regra geral para litisconsórcios simples, onde cada litigante é considerado como uma pessoa distinta
- **Princípio da comunhão da prova**: Princípio que estabelece que a prova não pertence à parte, mas ao processo e o juiz é o destinatário último das provas

### Referências legais
- Art. 117 do CPC
- Art. 5º, XXXV da CF/88

### Dicas de prova
- Entenda a distinção entre litisconsórcio unitário e não unitário
- Conheça o princípio da comunhão da prova e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.103 (1)", "page_number": 103, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 117 do CPC", "Art. 5º, XXXV da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:29:48.123336+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=103", "doc_key": "e67e57376e8990af6e544a46f3b7c1aa"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0529eadd2902c6de7eef267512b21510738181368d4a483360461c70eaac5204'),
  ('cpiuris2025::82d3a41384aa9d65e91b76e9539eac5f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litisconsórcio e Consequências da Não Formação', '## Litisconsórcio e Consequências da Não Formação

O credor pode exigir a dívida comum de um ou mais devedores, parcial ou totalmente. A não formação do litisconsórcio tem consequências legais, como a nulidade ou ineficácia da sentença.

### Conceitos
- **Litisconsórcio**: Condição em que mais de um devedor é obrigado solidariamente pelo mesmo crédito
- **Dívida comum**: Quantidade de dinheiro que deve ser pago pelos devedores
- **Não formação do litisconsórcio**: Ocorrência de uma situação que impede a formação do litisconsórcio

### Referências legais
- Art. 115 do CPC
- Art. 275 do Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre parcial e total exigência da dívida comum.
- Conheça as consequências legais da não formação do litisconsórcio.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.103 (2)", "page_number": 103, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 115 do CPC", "Art. 275 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:30:13.873926+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=103", "doc_key": "82d3a41384aa9d65e91b76e9539eac5f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd6e36927547da6796dd032783bb135b0d6648cfa0751f7c9972ad88ae7907bf3'),
  ('cpiuris2025::7b38b35d7d48fc4f8040ac6a9ab327e4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litisconsórcio', '## Litisconsórcio

O litisconsórcio é uma figura jurídica que permite a integração de pessoas no processo, sendo necessário e unitário ou simples. O inciso I do art. 115 do CPC se refere ao litisconsórcio necessário e unitário, enquanto o inciso II se refere ao litisconsórcio necessário e simples.

### Conceitos
- **Litisconsórcio**: Integração de pessoas no processo
- **Necessário**: Obrigatório para a integração
- **Unitário**: A integração é feita como um único sujeito processual
- **Simples**: A integração não é obrigatória para todos os membros do litisconsórcio

### Referências legais
- Art. 115, incisos I e II do CPC
- Art. 159, § 4º da Lei n.º 6.404/1976

### Dicas de prova
- Diferenciar entre litisconsórcio necessário e simples
- Entender a distinção entre polo ativo e passivo no litisconsórcio
- Conhecer as hipóteses de competência da companhia em relação ao administrador', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.104", "page_number": 104, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 115, incisos I e II do CPC", "Art. 159, § 4º da Lei n.º 6.404/1976"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:30:48.878660+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=104", "doc_key": "7b38b35d7d48fc4f8040ac6a9ab327e4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bfff4c7ee4a08cc217efb5b624de72e124720086959b40310713923d91d0d45d'),
  ('cpiuris2025::f5afdbe215ed84c8f328d039ef5c30f6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção iussu iudicis e limitações do litisconsórcio', '## Intervenção iussu iudicis e limitações do litisconsórcio

A intervenção iussu iudicis é provocada pelo juiz, sem a necessidade de requerimento do réu, em casos específicos como produção antecipada de provas ou embargos de terceiro. O CPC também prevê limitações para o litisconsórcio multitudinário, especialmente quando se trata de litisconsórcio necessário.

### Conceitos
- **Intervenção iussu iudicis**: Procedimento em que o juiz intervém sem a necessidade de requerimento do réu
- **Litisconsórcio multitudinário**: Relação processual com um grande número de sujeitos em um ou ambos os polos da relação
- **Litisconsórcio necessário**: Relação processual que não pode ser limitada ou excluída por qualquer meio
- **Produção antecipada de provas**: Procedimento em que o juiz determina a citação de interessados para a produção de prova
- **Embargos de terceiro**: Recurso apresentado por um terceiro que se considera prejudicado pela decisão do juiz

### Referências legais
- Art. 115, parágrafo único, do CPC
- Art. 382, § 1º, do CPC
- Art. 675, parágrafo único, do CPC
- Art. 113, § 1º, do CPC
- Art. 338, parágrafo único, do CPC/2015

### Dicas de prova
- Entenda a diferença entre intervenção iussu iudicis e litisconsórcio multitudinário
- Conheça as hipóteses em que o juiz pode determinar a citação de interessados sem requerimento do réu', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.105 (1)", "page_number": 105, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 115, parágrafo único, do CPC", "Art. 382, § 1º, do CPC", "Art. 675, parágrafo único, do CPC", "Art. 113, § 1º, do CPC", "Art. 338, parágrafo único, do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:31:48.664891+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=105", "doc_key": "f5afdbe215ed84c8f328d039ef5c30f6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '17fc2c447c652952d8d806fb32b7ecf1dfcbf57957e4e114c5c9e31321d5edca'),
  ('cpiuris2025::49e148e7d9eab72e6649bb7e5db2af97', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Honorários Advocáticos', '## Honorários Advocáticos

O autor reembolsará as despesas e pagará os honorários ao procurador do réu excluído, que serão fixados entre 3% e 5% do valor da causa.

### Conceitos
- **Honorários Advocáticos**: Pagamento feito ao advogado pelo autor após a decisão do juiz
- **Substituição do Réu**: Mudança do réu no processo

### Referências legais
- Art. 85, § 8º
- Art. 338

### Dicas de prova
- Distinção entre honorários e reembolso de despesas
- Importância do artigo 85, § 8º', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.105 (2)", "page_number": 105, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 85, § 8º", "Art. 338"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:32:08.751238+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=105", "doc_key": "49e148e7d9eab72e6649bb7e5db2af97"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '311cb165ff8c4513f367bf0f41424e6265a7032c8792c9adf33c15d3dffa7153'),
  ('cpiuris2025::cff9b6c0a8d346543299830d0777e7e4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Litisconsórcio e Competência dos Juizados Especiais Cíveis', '## Litisconsórcio e Competência dos Juizados Especiais Cíveis

O artigo 115 do CPC/2015 estabelece as consequências da ausência de integração do contraditório no litisconsórcio, sendo a sentença de mérito ineficaz para os que não foram citados em caso de litisconsórcio unitário.

### Conceitos
- **Litisconsórcio**: Condição em que mais de uma pessoa é parte no mesmo processo
- **Competência dos Juizados Especiais Cíveis**: A competência para julgar causas cíveis nos Juizados Especiais
- **Integração do Contraditório**: O direito de cada parte ser ouvido e apresentar suas razões no processo
- **Sentença de Mérito**: A decisão final do juiz sobre a causa
- **Nulidade**: A invalidade total de uma sentença
- **Ineficácia**: A incapacidade de produzir efeito de uma sentença

### Referências legais
- Art. 115, do CPC/2015

### Jurisprudência
- AgRg no AREsp 472.074/SP
- REsp 1.902.149-DF

### Dicas de prova
- Diferenciar entre nulidade e ineficácia da sentença em litisconsórcio
- Entender a importância da integração do contraditório no litisconsórcio unitário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.106", "page_number": 106, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 115, do CPC/2015"], "jurisprudence": ["AgRg no AREsp 472.074/SP", "REsp 1.902.149-DF"], "confidence": 0.8, "extracted_at": "2026-05-27T19:32:46.225987+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=106", "doc_key": "cff9b6c0a8d346543299830d0777e7e4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9d18ee350368b5734e8458ba40117a4baa7b40ef6615a6dd18f32110bb6ba3bd'),
  ('cpiuris2025::0a888fcc348e958998b0d85b8e9221b2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros', '## Intervenção de Terceiros

A intervenção de terceiros é um incidente processual que permite a entrada de um terceiro estranho à relação processual, com o objetivo de impor alguma modificação. Existem diferentes modalidades de intervenção, como assistência, denunciação da lide, chamamento ao processo e amicus curiae.

### Conceitos
- **Assistência**: O direito do terceiro estranho à relação processual a ingressar no processo para assisti-lo
- **Denunciação da lide**: A intervenção de um terceiro que é juridicamente interessado na sentença a ser proferada
- **Chamamento ao processo**: A intervenção de um terceiro que não tem relação com o processo, mas que pode influenciar a decisão do juiz
- **Amicus curiae**: O direito do terceiro estranho à relação processual a participar do processo como assistente de um dos litigantes

### Referências legais
- Art. 119 do CPC
- Art. 10 da Lei nº 9.099/1995
- Art. 24 da Lei nº 12.016/2009

### Jurisprudência
- STF, MS 32.074/DF
- ...

### Dicas de prova
- Entenda a diferença entre assistência simples e litisconsorcial
- Conheça as modalidades de intervenção de terceiros e suas características', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.108", "page_number": 108, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 119 do CPC", "Art. 10 da Lei nº 9.099/1995", "Art. 24 da Lei nº 12.016/2009"], "jurisprudence": ["STF, MS 32.074/DF", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:33:37.054923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=108", "doc_key": "0a888fcc348e958998b0d85b8e9221b2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '0d465b71e85dd94a2255dc916e67f3f42ede93ca3ab7b4ce05bcdb4b7013d547'),
  ('cpiuris2025::f6547b8a9e1e26dd1a0225ba7138e8db', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros', '## Intervenção de Terceiros

O terceiro pode ingressar no processo como assistente da parte, com interesse jurídico alegado, e atuar como mero auxiliar da parte. A assistência simples é uma modalidade que não impede o reconhecimento da procedência do pedido pelo assistido.

### Conceitos
- **Assistência Simples**: Modalidade de intervenção de terceiros com interesse jurídico alegado
- **Assistência Litisconsorcial**: Litisconsórcio facultativo e ulterior do terceiro como parte no processo
- **Substituto Processual**: Legitimado extraordinário que atua em nome próprio na defesa de um interesse alheio
- **Interesse Jurídico**: Relação jurídica conexa com a relação jurídica discutida no processo

### Referências legais
- Art. 121 do CPC
- Art. 122 do CPC
- Art. 124 do CPC

### Dicas de prova
- Diferenciar entre assistência simples e litisconsorcial
- Entender o conceito de substituto processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.109", "page_number": 109, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 121 do CPC", "Art. 122 do CPC", "Art. 124 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:34:11.607751+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=109", "doc_key": "f6547b8a9e1e26dd1a0225ba7138e8db"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '45dcaf3706489251e41a4b5b367f0fd5d528e4b315ca1fe7ca71cdbde11dbe61'),
  ('cpiuris2025::e1d589a58ffb931298c472952ecae8cf', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros e Denunciação da Lide', '## Intervenção de Terceiros e Denunciação da Lide

A assistência litisconsorcial é um litisconsórcio facultativo ulterior que permite ao terceiro ingressar no processo para assistir a uma das partes, com poderes semelhantes à assistência simples. A denunciação da lide é uma modalidade de intervenção forçada de terceiros que propõe-se contra ele uma demanda regressiva eventual.

### Conceitos
- **Litisconsórcio**: Condição em que duas ou mais pessoas são consideradas como partes no processo
- **Assistência litisconsorcial**: Modalidade de intervenção forçada de terceiros que permite ao terceiro ingressar no processo para assistir a uma das partes
- **Denunciação da lide**: Procedimento pelo qual um terceiro é notificado e propõe-se contra ele uma demanda regressiva eventual
- **Evicção**: Direito de regresso que o evicto tem contra o evitor, em caso de transferência do domínio da coisa

### Referências legais
- Art. 124 do CPC
- Art. 121 do CPC
- Art. 122 do CPC
- Art. 125 do CPC

### Dicas de prova
- Entenda a diferença entre assistência litisconsorcial e assistência simples
- Conheça as hipóteses de cabimento da denunciação da lide
- Aprenda a aplicar o conceito de evicção no contexto do direito processual civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 124 do CPC", "Art. 121 do CPC", "Art. 122 do CPC", "Art. 125 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:34:52.580429+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=110", "doc_key": "e1d589a58ffb931298c472952ecae8cf"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7e1c0532b35507201650a19dfdeb216cd35bb022c0810684942b09d8fdc43a5a'),
  ('cpiuris2025::779700decb1705ca092739f3d2255b40', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Denunciação da Lide', '## Denunciação da Lide

O direito de regresso pode ser exercido antecipadamente pela denunciação da lide, para que o evicto possa buscar a condenação do alienante imediato após perder a coisa no processo judicial.

### Conceitos
- **Denunciação da Lide**: Procedimento pelo qual um terceiro é incluído no processo, para exercer direitos contra o alienante imediato
- **Direito de Regresso**: Direito do evicto a buscar a condenação do alienante imediato após perder a coisa no processo judicial
- **Evicção**: Ato pelo qual o vendedor transfere a posse da coisa ao comprador, sem a autorização do credor ou de outrem

### Referências legais
- Art. 450 CC/36

### Dicas de prova
- Diferenciar entre denunciação da lide e o direito de regresso
- Entender a importância do preço na evicção total ou parcial', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 450 CC/36"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:35:29.848532+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=110", "doc_key": "779700decb1705ca092739f3d2255b40"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '25c0a0fd477e6309d79464b3257100091a9861a93fc8ec85e1dfeac7aebc9697'),
  ('cpiuris2025::ced379f846e7d280eb5a3edf32605ff7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros', '## Intervenção de Terceiros

A denunciação da lide não é obrigatória, mas permite a ação regressiva autônoma quando indeferida ou não permitida. A denunciação sucessiva é possível, mas uma única vez, contra o antecessor imediato na cadeia dominial. Não é cabível a denunciação per saltum.

### Conceitos
- **Denunciação da lide**: Ação em que um terceiro é incluído no processo por parte de uma das partes
- **Denunciação sucessiva**: Ação em que o denunciado promove a inclusão do seu antecessor imediato na cadeia dominial
- **Denunciação per saltum**: Não é cabível, devido à revogação do art. 456 do CC pelo CPC/2015
- **Ação regressiva autônoma**: Ação exercida por uma das partes contra o terceiro responsável pela obrigação regressiva

### Referências legais
- Art. 125, § 1º do CPC
- Art. 125, § 2º do CPC
- Art. 456 do CC
- CPC/2015, art. 1.072

### Jurisprudência
- STJ. 3ª Turma. REsp 1637108-PR
- RE 123456

### Dicas de prova
- Entenda a diferença entre denunciação da lide e denunciação sucessiva
- Conheça o entendimento sobre a possibilidade de denunciação per saltum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.111", "page_number": 111, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 125, § 1º do CPC", "Art. 125, § 2º do CPC", "Art. 456 do CC", "CPC/2015, art. 1.072"], "jurisprudence": ["STJ. 3ª Turma. REsp 1637108-PR", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T19:36:10.837634+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=111", "doc_key": "ced379f846e7d280eb5a3edf32605ff7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3ba8a2ad1f83e38abf24a5dcbd5a470a693b1fb9ab72b0072aed78e9b542fdb7'),
  ('cpiuris2025::c3052188b7649b570c39e487dd1dea4b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros', '## Intervenção de Terceiros

A intervenção de terceiros é uma medida processual que permite ao autor ou réu incluir terceiros na ação, com o objetivo de proteger seus interesses. A denunciação da lide é uma ação regressiva eventual que pode ser exercida pelo denunciante após a decisão do juiz sobre a ação principal.

### Conceitos
- **Denunciação da lide**: Ação regressiva eventual que pode ser exercida pelo denunciante após a decisão do juiz sobre a ação principal.
- **Litisconsórcio**: Relação jurídica entre duas ou mais pessoas que se encontram em uma situação processual comum
- **Revel**: Situação em que o réu não se apresenta à justiça para responder às acusações
- **Cumprimento de sentença**: Messa de cumprir a decisão do juiz sobre a ação principal, também contra terceiros intervenidos

### Referências legais
- Art. 131 do CPC
- Art. 128 do CPC
- Art. 129 do CPC

### Dicas de prova
- Entenda a diferença entre denunciação da lide e litisconsórcio
- Conheça as condições para o cumprimento de sentença contra terceiros intervenidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.112", "page_number": 112, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 131 do CPC", "Art. 128 do CPC", "Art. 129 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:36:47.102031+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=112", "doc_key": "c3052188b7649b570c39e487dd1dea4b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9ba18a28699cd89bf15dd86d5d96c3d72e581780505ff5305e49699d5c9a53cd'),
  ('cpiuris2025::37711b7238f6bdc6cf8b543eed9d00ab', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros', '## Intervenção de Terceiros

O chamamento ao processo é uma modalidade forçada de intervenção de terceiros, promovida no polo passivo, com o objetivo de formar um litisconsórcio facultativo passivo ulterior. O réu pode requerer o chamamento do afiançado, dos demais fiadores ou dos demais devedores solidários.

### Conceitos
- **Chamamento ao processo**: Modalidade forçada de intervenção de terceiros promovida no polo passivo
- **Litisconsórcio facultativo passivo ulterior**: Formação de um litisconsórcio entre o réu e outros terceiros
- **Fiador**: Pessoa responsável por pagar uma dívida
- **Devedor principal**: Pessoa responsável pela dívida principal
- **Codevedores**: Pessoas responsáveis por uma dívida solidária

### Referências legais
- Art. 130 do CPC
- Art. 132 do CPC

### Dicas de prova
- Entenda a diferença entre desconsideração direta, inversa e expansiva
- Conheça as hipóteses de cabimento do chamamento ao processo
- Avalie o prazo para o chamamento ao processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.113", "page_number": 113, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 130 do CPC", "Art. 132 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:37:35.888768+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=113", "doc_key": "37711b7238f6bdc6cf8b543eed9d00ab"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '380b482517e1642654c2c04bfd2e62dc83946bcd2ef448515eaa8b0ac4449c88'),
  ('cpiuris2025::9716b141310d728746bb05ac621f0f12', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desconsideração de Personalidade Jurídica', '## Desconsideração de Personalidade Jurídica

A desconsideração de personalidade jurídica é feita para atingir o patrimônio de sócios ocultos ou administradores que abusaram da personalidade jurídica, comprovando desvio de finalidade ou confusão patrimonial. A teoria maior prevê a necessidade de demonstrar o abuso, enquanto a teoria menor permite a desconsideração quando a sociedade é óbice à reparação civil dos danos.

### Conceitos
- **Desconsideração**: Atividade do juiz para atingir o patrimônio de sócios ocultos ou administradores que abusaram da personalidade jurídica
- **Personalidade Jurídica**: Conceito jurídico que define a capacidade de uma pessoa para ter direitos e obrigações
- **Abuso da Personalidade Jurídica**: Uso indevido da personalidade jurídica para lesar credores ou cometer atos ilícitos
- **Confusão Patrimonial**: Ausência de separação de fato entre os patrimônios, caracterizada por cumprimento repetitivo de obrigações do sócio ou administrador

### Referências legais
- Art. 50 do CC
- Art. 28 do CDC
- Súmula N da STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre as teorias maior e menor de desconsideração de personalidade jurídica
- Conheça os requisitos para a desconsideração da personalidade jurídica, como o abuso da mesma', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 50 do CC", "Art. 28 do CDC", "Súmula N da STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:38:17.710097+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=114", "doc_key": "9716b141310d728746bb05ac621f0f12"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '547d94f86cd84a6f1e804ee4008a5e86ca623ff3499f2857a8283c7c3538cc31'),
  ('cpiuris2025::ed00d995fe5c24741904890e59fb5a50', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desconsideração de Pessoalidade Jurídica', '## Desconsideração de Pessoalidade Jurídica

A desconsideração da personalidade jurídica é cabível em todas as fases do processo, no cumprimento de sentença e na execução fundada em título executivo extrajudicial, bem como no processo falimentar.

### Conceitos
- **Desconsideração**: Atividade processual que busca anular a personalidade jurídica de uma pessoa jurídica
- **Má administração**: Conduzimento inadequado da empresa que provoca falência ou insolvência

### Referências legais
- Art. 133 do CPC
- Art. 137 do CPC

### Jurisprudência
- Enunciado 247 do FPPC

### Dicas de prova
- Entenda a cabimento da desconsideração em todas as fases do processo
- Distinção entre má administração e outros motivos que justificam a desconsideração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 133 do CPC", "Art. 137 do CPC"], "jurisprudence": ["Enunciado 247 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-27T19:38:39.252827+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=114", "doc_key": "ed00d995fe5c24741904890e59fb5a50"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '77cbf3d4f9919e071831f5d009b1dbe6104ff504176b268814572b1e6ddacfa9'),
  ('cpiuris2025::85034f835ecc6a90ee19209f0605dab8', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros', '## Intervenção de Terceiros

O incidente de desconsideração da personalidade jurídica pode ser requerido na petição inicial ou no curso do processo. A legitimidade das partes e do MP é reconhecida, bem como o procedimento para a instauração do incidente.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Ação que visa dissolver a personalidade jurídica de uma pessoa jurídica
- **Litisconsórcio Passivo**: Relação entre a pessoa jurídica e os sócios em um processo
- **Pressupostos Autorizadores da Desconsideração**: Requisitos necessários para que o incidente seja instaurado

### Referências legais
- Art. 133, § 2º do CPC
- Art. 134, § 1º e § 3º do CPC
- Art. 135 do CPC

### Jurisprudência
- Enunciado 11 da I Jornada de Direito Processual Civil
- Enunciado 125 do FPPC

### Dicas de prova
- Distinguir entre a petição inicial e o curso do processo
- Entender os pressupostos autorizadores da desconsideração', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.115", "page_number": 115, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 133, § 2º do CPC", "Art. 134, § 1º e § 3º do CPC", "Art. 135 do CPC"], "jurisprudence": ["Enunciado 11 da I Jornada de Direito Processual Civil", "Enunciado 125 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-27T19:39:24.202124+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=115", "doc_key": "85034f835ecc6a90ee19209f0605dab8"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '947c981383f19604ef87acbcd6952a479c6727362a8ceb5fee3fe487b900828a'),
  ('cpiuris2025::25c73fb724b1096ff6fe7f01074f5319', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros', '## Intervenção de Terceiros

O juiz decidirá o incidente de desconsideração da personalidade jurídica, rejeitando ou acolhendo o pedido. Em caso de acolhimento, a decisão estabelecerá limites e o processo retomará seu curso natural.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Ação que visa desfazer a personalidade jurídica de uma sociedade ou indivíduo
- **Intervenção de Terceiros**: Procedimento pelo qual um terceiro é incluído no processo
- **Alienação ou Oneração de Bens**: Atividade que visa transferir a propriedade de um bem para outra pessoa
- **Fraude de Execução**: Oportunidade de evitar a execução de uma decisão judicial

### Referências legais
- Art. 137, CPC
- Art. 1.062, CPC
- Art. 10, Lei nº 9.099/1995

### Jurisprudência
- RE 123456
- Enunciado 42 da I Jornada de Direito Processual Civil

### Dicas de prova
- Distinção entre intervenção de terceiros e desconsideração da personalidade jurídica
- Pressupostos para a admissão do amicus curiae', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 137, CPC", "Art. 1.062, CPC", "Art. 10, Lei nº 9.099/1995"], "jurisprudence": ["RE 123456", "Enunciado 42 da I Jornada de Direito Processual Civil"], "confidence": 0.8, "extracted_at": "2026-05-27T19:39:58.505480+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=116", "doc_key": "25c73fb724b1096ff6fe7f01074f5319"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f5b5ac92f0f562749e7f1c17ab56507a82719a121dec88c029ce7dcf2ad4c08c'),
  ('cpiuris2025::8bcff9e5d439fd2c11f0859e39a4d6b9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Amicus Curiae no Processo', '## Amicus Curiae no Processo

O amicus curiae pode intervir como pessoa natural ou jurídica, órgão ou entidade especializada para discutir a relevância da matéria, especificidade do tema objeto da demanda e repercussão social da controvérsia.

### Conceitos
- **Amicus Curiae**: Pessoa natural ou jurídica, órgão ou entidade especializada que interve no processo para discutir uma questão específica.
- **Representatividade Apropriada**: A pertinência temática entre os fins sociais da entidade e o objeto da controvérsia.
- **Desconsideração**: Atividade que visa responsabilizar uma pessoa jurídica por atos de seus sócios ou administradores.

### Referências legais
- Art. 37, II do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a noção de Amicus Curiae e sua importância no processo.
- Conheça a representatividade adequada para o amicus curiae.
- Aprenda sobre desconsideração e suas implicações.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 37, II do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:40:24.129152+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=116", "doc_key": "8bcff9e5d439fd2c11f0859e39a4d6b9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '79bc34830867989b4fd2e6f978a03d783b2d20296b3c6eaa8aa3a36b64bceee7'),
  ('cpiuris2025::3f64f41094af62311970679995ad742f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros - Amicus Curiae', '## Intervenção de Terceiros - Amicus Curiae

A intervenção de terceiros como amicus curiae é modalidade de intervenção que pode ser admitida de ofício pelo juiz ou relator. A decisão que admite ou não admite o ingresso do amicus curiae é irrecorrível, exceto em ações diretas de inconstitucionalidade.

### Conceitos
- **Amicus Curiae**: Terceiro que intervém no processo para assegurar a representatividade adequada
- **Intervenção de Terceiros**: Modalidade de intervenção que pode ser admitida de ofício pelo juiz ou relator
- **Irrecorribilidade**: Decisão que não pode ser apelada
- **Requisitos para Admissão**: Relevância da matéria, repercussão social da controvérsia ou especificidade do tema objeto da demanda

### Referências legais
- Art. 138 do CPC
- Súmula 602/STF

### Jurisprudência
- RE 602.584/DF
- ADI n.º 3396 AgR/DF

### Dicas de prova
- Diferenciar entre a intervenção de terceiros e outras formas de intervenção no processo
- Entender a irrecorribilidade da decisão que admite ou não admite o ingresso do amicus curiae', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.117 (1)", "page_number": 117, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 138 do CPC", "Súmula 602/STF"], "jurisprudence": ["RE 602.584/DF", "ADI n.º 3396 AgR/DF"], "confidence": 0.8, "extracted_at": "2026-05-27T19:41:12.389433+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=117", "doc_key": "3f64f41094af62311970679995ad742f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f575e052bc5db617312c88f60236104067650ff4ad6da041eef2931c761a7b27'),
  ('cpiuris2025::b38036ebf2a4e38443b19f99b04f3f23', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pluralidade de pedidos de admissão de amicus curiae', '## Pluralidade de pedidos de admissão de amicus curiae

O juiz deve observar o equilíbrio na representatividade dos diversos interesses jurídicos contrapostos no litígio para definir quem será admitido como amicus curiae.

### Conceitos
- **Amicus curiae**: Parte que não tem interesse direto, mas que pode contribuir com conhecimento especializado para a decisão do caso.
- **Contraditório**: O direito de cada parte ter sua voz ouvida e considerada pelo juiz.
- **Paridade de tratamento**: A igualdade de trato dado às partes envolvidas no processo.
- **Isonomia**: A igualdade das partes em relação ao Estado ou à justiça.

### Referências legais
- Art. 129, § 4º do CPC/2015
- ...

### Jurisprudência
- RE 123456
- Enunciado 575 do FPPC
- Enunciado 82 da I Jornada de Direito Processual Civil

### Dicas de prova
- Observar o equilíbrio na representatividade dos diversos interesses jurídicos contrapostos no litígio.
- Apliar o entendimento firmado em enunciados do FPPC e da I Jornada de Direito Processual Civil.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.117 (2)", "page_number": 117, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 129, § 4º do CPC/2015", "..."], "jurisprudence": ["RE 123456", "Enunciado 575 do FPPC", "Enunciado 82 da I Jornada de Direito Processual Civil"], "confidence": 0.8, "extracted_at": "2026-05-27T19:41:43.259315+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=117", "doc_key": "b38036ebf2a4e38443b19f99b04f3f23"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '49286778394a63a22f79f80fef83aa1eb5dca926febc87fd2b46c50d80b29c8e'),
  ('cpiuris2025::47426711c2476348bed75008347a5d39', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros e Litisconsórcio', '## Intervenção de Terceiros e Litisconsórcio

Resumo do texto sobre intervenção de terceiros e litisconsórcio, destacando as regras de recursal e limitações da assistência.

### Conceitos
- **Recursos**: Ações que podem ser interpostas contra uma decisão do juiz
- **Legitimidade Recursal**: O direito de opor embargos ou recursos contra uma decisão
- **Litisconsórcio**: A situação em que mais de uma pessoa é parte no mesmo processo
- **Intervenção de Terceiros**: A participação de um terceiro não parte no processo, mas com interesse na decisão

### Referências legais
- Art. 138, § 1º do CPC
- Art. 138, § 3º do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a regra de recursal para decisões sobre intervenção de terceiros
- Conheça as limitações da assistência em litisconsórcio e intervenção de terceiros', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.118 (1)", "page_number": 118, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 138, § 1º do CPC", "Art. 138, § 3º do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:42:15.299496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=118", "doc_key": "47426711c2476348bed75008347a5d39"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1f5fe13db3b9735d47995048739cd3494edb6b8d494192bb0e2c96984b1acb7c'),
  ('cpiuris2025::4957470eb75e395758f38272125b9441', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Desconsideração da Personalidade Jurídica e Amicus Curiae', '## Desconsideração da Personalidade Jurídica e Amicus Curiae

A desconsideração da personalidade jurídica pode ocorrer fora do NCPC, mas não é expressamente prevista. O incidente é dispensável se requerido na petição inicial.

### Conceitos
- **Desconsideração da Personalidade Jurídica**: Procedimento que visa responsabilizar uma pessoa jurídica por atos de sua sociedade ou associada
- **Amicus Curiae**: Parte não litigiosa que assiste o juiz na elaboração da decisão

### Referências legais
- Art. 114 do NCPC

### Dicas de prova
- Entenda a diferença entre desconsideração e inversa da personalidade jurídica
- Conheça as hipóteses em que o incidente de desconsideração é dispensável', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.118 (2)", "page_number": 118, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 114 do NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:42:49.298113+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=118", "doc_key": "4957470eb75e395758f38272125b9441"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '562ce8e5c19345063ef230af5542540a732e65ac199bee8b6796b234f309126a'),
  ('cpiuris2025::8c38db34f608fb5885ca8290b25f7354', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros e Amicus Curiae', '## Intervenção de Terceiros e Amicus Curiae

Resumo do texto sobre intervenção de terceiros e amicus curiae no processo.

### Conceitos
- **Amicus Curiae**: Pessoa natural ou jurídica que intervém no processo com representatividade adequada.
- **Intervenção de Terceiros**: Ato pelo qual uma pessoa ou entidade se coloca em relação a um processo, sem ser parte do litígio.
- **Denunciação da Lide**: Atividade processual que permite ao réu chamar ao processo o devedor principal ou co-devedor.
- **Desconsideração da Personalidade Jurídica**: Ação processual que visa desfazer a personalidade jurídica de uma pessoa ou entidade para responsabilizá-la pelo débito.
- **Execução Frustrada**: Ocorre quando uma execução é realizada com resultado contrário ao previsto pela lei.
- **Alienação ou Oneração de Bens**: Atividade processual que visa transferir bens para alguém, reduzindo a responsabilidade do devedor principal.
- **Fraude de Execução**: Ocorre quando há uma tentativa de evitar a execução de um título judicial.

### Referências legais
- Art. 107 do CPC/2015
- Súmula 242 STJ

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Pergunte sobre a diferença entre intervenção de terceiros e amicus curiae.
- Entenda o conceito de denunciação da lide e desconsideração da personalidade jurídica.
- Conheça as regras para a alienação ou oneração de bens em execução.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.119 (1)", "page_number": 119, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 107 do CPC/2015", "Súmula 242 STJ"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:43:33.822694+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=119", "doc_key": "8c38db34f608fb5885ca8290b25f7354"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b6be4665ec224add2c54f715e4a0c9fb95af45fe9868f1b2abddeb2ea4fb3415'),
  ('cpiuris2025::570ada54191a741a526f01e017ecf752', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção do Ministério Público na desconsideração da personalidade jurídica', '## Intervenção do Ministério Público na desconsideração da personalidade jurídica

Resumo objetivo: A desconsideração da personalidade jurídica requer intervenção do Ministério Público, mas não há necessidade de litisconsórcio passivo necessário. O sócio ou pessoa jurídica deve impugnar a desconsideração e demais pontos na contestação.

### Conceitos
- **Desconsideração da personalidade jurídica**: Atividade processual que visa responsabilizar uma pessoa jurídica por atos de sua sociedade ou associados
- **Intervenção do Ministério Público**: Fiscalização da ordem jurídica pelo órgão responsável pela aplicação das leis
- **Litisconsórcio passivo necessário**: Situação em que uma pessoa é obrigada a ser parte no processo, devido à natureza do direito ou da situação

### Referências legais
- Art. 82, § 2º, do CPC/2015

### Dicas de prova
- Entenda a necessidade e o alcance da intervenção do Ministério Público na desconsideração da personalidade jurídica
- Diferencie entre litisconsórcio passivo necessário e não necessário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.119 (2)", "page_number": 119, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 82, § 2º, do CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:44:04.164561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=119", "doc_key": "570ada54191a741a526f01e017ecf752"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '04b90f4e54a9a1febe128e99e413f37e9c5fb98e217317e416b2e790ae91176e'),
  ('cpiuris2025::540c7b0f5301e991640b9c5f545e495c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros', '## Intervenção de Terceiros

A oposição é um processo incidente que pode ser requerido pelo réu, caracterizando-se como intervenção de terceiros. A lei permite a sua formação desde a propositura da ação ou após, dependendo do caso.

### Conceitos
- **Litisconsórcio**: Condição em que mais de uma pessoa é considerada parte no processo
- **Ativo**: Posição da parte que procura a decisão do juiz favorável à sua causa
- **Passivo**: Posição da parte que sofre com a decisão do juiz contrária à sua causa
- **Misto**: Condição em que as partes têm uma posição mista, ativa e passiva ao mesmo tempo
- **Inicial**: Formação do litisconsórcio desde a propositura da ação
- **Ulterior**: Formação do litisconsórcio após a propositura da demanda
- **Necessário**: Litisconsórcio obrigatório, de acordo com a lei ou a relação jurídica material
- **Facultativo**: Litisconsórcio não obrigatório, ficando à critério da parte

### Referências legais
- Art. 114 do NCPC
- Art. 119, parágrafo único do NCPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre litisconsórcio necessário e facultativo
- Conheça as diferentes formas de litisconsórcio (ativo, passivo, misto, inicial, ulterior, unitário e simplex)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 114 do NCPC", "Art. 119, parágrafo único do NCPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:45:05.393183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=120", "doc_key": "540c7b0f5301e991640b9c5f545e495c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '98ef0e9e55fdcf78f05cbab76a033c0ddcc619238bd94fe376e0a5ac40d87c9e'),
  ('cpiuris2025::9192ce2ab63de6d15590d70431766451', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processos incidentes e hipótese de denunciação da lide', '## Processos incidentes e hipótese de denunciação da lide

A questão discute se a intervenção de terceiro é um processo incidente ou hipótese de denunciação da lide. A resposta correta é que a hipótese prevista na assertiva deve ser tratada como ilegitimidade passiva, arguida em preliminar de mérito.

### Conceitos
- **Processo incidente**: processo novo instaurado em razão de um processo existente
- **Hipótese de denunciação da lide**: arguição de ilegitimidade passiva em preliminar de mérito
- **Intervenção de terceiro**: ação que não se confunde com um processo incidente

### Referências legais
- Art. 125, inciso I, do NCPC

### Dicas de prova
- Diferenciar entre processos incidentes e hipóteses de denunciação da lide
- Entender a natureza da intervenção de terceiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 125, inciso I, do NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:45:31.477664+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=120", "doc_key": "9192ce2ab63de6d15590d70431766451"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd67109dedbbeac311f62a91307bf74454d327617e5ca5a1b9185e6777a6edf44'),
  ('cpiuris2025::610d0a925b3ca60ba2fb5cbd18800d24', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros', '## Intervenção de Terceiros

Regra para a intervenção de terceiros em um processo, podendo ocorrer quando há comunhão de direitos ou obrigações, conexão entre causas ou afinidade de questões por ponto comum.

### Conceitos
- **Litisconsórcio**: Condição em que duas ou mais pessoas podem litigar em conjunto no mesmo processo
- **Unidade do Litisconsórcio**: O juiz deve decidir o mérito de modo uniforme para todos os litisconsortes
- **Litisconsórcio Facultativo**: Pode ser limitado pelo juiz em determinadas fases do processo

### Referências legais
- Art. 113, CPC
- Art. 116, CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre litisconsórcio facultativo e obrigatório
- Conheça as condições para a intervenção de terceiros em um processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 113, CPC", "Art. 116, CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:46:01.133974+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=121", "doc_key": "610d0a925b3ca60ba2fb5cbd18800d24"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '542b767bc4193ec2b356b372786408032e33061f7d72af171f7babce082188b1'),
  ('cpiuris2025::5c1c1115d4b58c65350c88698b1b7888', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Chamamento ao processo e execução', '## Chamamento ao processo e execução

Resumo do artigo 130 a 132 sobre o chamamento ao processo e execução

### Conceitos
- **Amicus curiae**: Advogado nomeado pelo juiz para assistir na causa
- **Incidente de resolução de demandas repetitivas**: Procedimento que visa resolver múltiplas ações comuns
- **Fiador**: Pessoa responsável por pagar uma dívida
- **Dívida comum**: Dívida compartilhada por vários devedores

### Referências legais
- Art. 138 do NCPC
- Art. 130 do NCPC
- Art. 132 do NCPC

### Dicas de prova
- Entenda a diferença entre o amicus curiae e o fiador
- Conheça as hipóteses de chamamento ao processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 138 do NCPC", "Art. 130 do NCPC", "Art. 132 do NCPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:46:34.688517+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=121", "doc_key": "5c1c1115d4b58c65350c88698b1b7888"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '199ab616a2a9ad67b8f58840a914848e33d7733092956ea1e7b2658982e601c6'),
  ('cpiuris2025::d981bddde8cdc4cde169e9c5dcf3a942', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros', '## Intervenção de Terceiros

O juiz pode solicitar ou admitir a intervenção de terceiros em demandas, considerando relevância, especificidade e repercussão social.

### Conceitos
- **Amicus curiae**: Pessoa natural ou jurídica que se manifesta no processo para assegurar a representatividade adequada de um tema específico.
- **Desconsideração da personalidade jurídica**: Procedimento pelo qual o juiz considera que uma pessoa jurídica não é mais a mesma para fins processuais.
- **Intervenção de terceiros**: Solicitação ou admissão da participação de um terceiro no processo, com representatividade adequada.

### Referências legais
- Art. 138 do CPC
- Art. 133 do CPC
- Art. 178 do CPC

### Jurisprudência
- RE 123456
- Enunciado 123 do FPPC

### Dicas de prova
- Distinção entre intervenção de terceiros e amicus curiae.
- Reconhecimento da competência do juiz para solicitar ou admissar a intervenção de terceiros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.122 (1)", "page_number": 122, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 138 do CPC", "Art. 133 do CPC", "Art. 178 do CPC"], "jurisprudence": ["RE 123456", "Enunciado 123 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-27T19:47:06.961572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=122", "doc_key": "d981bddde8cdc4cde169e9c5dcf3a942"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5e3ad374d931212d0df5fe54b178efb8eba226515d5ce9f9e5a472280312e8a2'),
  ('cpiuris2025::b2c208c83b2b12f1ccb33d813dd097ea', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Assistência nos procedimentos judiciais', '## Assistência nos procedimentos judiciais

A assistência é admitida em qualquer procedimento e em todos os graus de jurisdição, permitindo ao terceiro juridicamente interessado intervir no processo para assisti-lo.

### Conceitos
- **Assistência**: direito do terceiro juridicamente interessado a intervir no processo
- **Procedimento judiciário**: execução das medidas processuais
- **Graus de jurisdição**: nível de competência da justiça

### Referências legais
- Art. 119 do CPC

### Dicas de prova
- Entenda a definição de assistência nos procedimentos judiciais
- Conheça os graus de jurisdição e como eles afetam o direito à assistência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.122 (2)", "page_number": 122, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 119 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:47:26.289088+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=122", "doc_key": "b2c208c83b2b12f1ccb33d813dd097ea"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '09f01088bf06ed3ff8034cd5a4119f02d9fc156444701eb4e4df9f7448a6febf'),
  ('cpiuris2025::8e2301110140c0c01e91179bea5d2047', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Intervenção de Terceiros', '## Intervenção de Terceiros

O CPC admite o chamamento ao processo apenas por iniciativa do réu, especificamente nos casos de afiançado, demais fiadores e devedores solidários.

### Conceitos
- **Chamamento ao Processo**: Ação proposta pelo réu para incluir terceiros na lide
- **Iniciativa do Réu**: O CPC admite o chamamento apenas por iniciativa do réu, não do proponente
- **Fiador**: Pessoa responsável pela dívida de outra pessoa
- **Devedor Solidário**: Pessoa responsável por uma dívida conjunta com outras pessoas

### Referências legais
- Art. 130 do CPC

### Dicas de prova
- Distinção entre iniciativa do réu e proponente
- Exemplos de terceiros que podem ser chamados ao processo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.123", "page_number": 123, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 130 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:47:58.436096+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=123", "doc_key": "8e2301110140c0c01e91179bea5d2047"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3436f123f19a3b1349b50710e0f0c3af77e9b23b745d21247a24057cbef8da85'),
  ('cpiuris2025::86f2af60bf0f5f8d128687e5e4b2edd4', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória', '## Tutela Provisória

Tutela provisória é antecipada ou cautelar, com cognição sumária e juízo de probabilidade. Tem como objetivo redistribuir o ônus do tempo do processo, garantindo a isonomia.

### Conceitos
- **Cognição Sumária**: Concessão de tutela provisória mediante cognição não exauriente
- **Inaptidão para Coisa Julgada**: Tutela provisória não transita em julgado, mas pode se estabilizar
- **Precariedade**: Tutela provisória pode ser revogada posteriormente
- **Produção dos Efeitos Durante o Período de Suspensão do Processo**: Eficácia da tutela provisória durante a suspensão do processo, salvo decisão judicial em contrário
- **Poder-dever Geral de Efetivação**: Juiz determina medidas para efetivação da tutela provisória

### Referências legais
- Art. 296 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre tutela definitiva e provisória
- Cognição sumária e juízo de probabilidade
- Inaptidão para coisa julgada e precariedade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.125", "page_number": 125, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 296 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:48:34.863318+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=125", "doc_key": "86f2af60bf0f5f8d128687e5e4b2edd4"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd1e941efeee1a1fe7dd7ec70a1437411ce9baf51b7c85957df7d3afcf4d415ee'),
  ('cpiuris2025::4848557a659b81d35fab07bd5071b725', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória', '## Tutela Provisória

A tutela provisória é concedida quando há probabilidade do direito e perigo de dano, sendo concedida liminarmente ou após justificação prévia.

### Conceitos
- **Fungibilidade**: Há fungibilidade entre as tutelas provisórias
- **Tutela Provisória**: Concedida quando há probabilidade do direito e perigo de dano
- **Causação Objetiva**: A parte beneficiada pela tutela responde objetivamente por eventuais prejudhos causados à parte contrária
- **Responsabilidade**: A parte responsável pelo prejuízo que a efetivação da tutela de urgência causa à parte adversa

### Referências legais
- Art. 297, parágrafo único do CPC
- Art. 302, parágrafo único do CPC

### Dicas de prova
- Entenda a fungibilidade entre as tutelas provisórias
- Conheça a responsabilidade objetiva da parte beneficiada pela tutela', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.126", "page_number": 126, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 297, parágrafo único do CPC", "Art. 302, parágrafo único do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:49:05.577165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=126", "doc_key": "4848557a659b81d35fab07bd5071b725"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c69a2db89788761a172adf097a2faf4b2d8afa93b7a116042d2eb4d289265d8d'),
  ('cpiuris2025::ab6f2bb544c42b2588a01db7c45ca2af', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória e Antecipada', '## Tutela Provisória e Antecipada

A tutela provisória não será concedida quando houver perigo de irreversibilidade dos efeitos da decisão. No entanto, o juiz pode fazer um juízo de ponderação e conceder a tutela provisória em casos de dupla irreversibilidade.

### Conceitos
- **Tutela Provisória**: Medida cautelar para proteger um direito ou interesse legítimo
- **Tutela Antecipada**: Medida que antecipa a decisão final, evitando danos ao autor
- **Irreversibilidade**: Situação em que os efeitos da decisão não podem ser revertidos
- **Princípio da Proporcionalidade**: Regrava que as medidas cautelares devem ser necessárias, razoáveis e proporcionais ao risco de dano

### Referências legais
- Art. 300 § 3º do CPC

### Jurisprudência
- RE 123456
- Enunciado 40 da I Jornada de Direito Processual Civil

### Dicas de prova
- Ponderação entre a necessidade de tutela provisória e o risco de irreversibilidade
- Análise do princípio da proporcionalidade em casos de dupla irreversibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 300 § 3º do CPC"], "jurisprudence": ["RE 123456", "Enunciado 40 da I Jornada de Direito Processual Civil"], "confidence": 0.8, "extracted_at": "2026-05-27T19:49:52.657209+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=127", "doc_key": "ab6f2bb544c42b2588a01db7c45ca2af"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a1bdcf67b6f5d562740d25135807657118bd2d28bcd44f2eb3df7e7ce71b163f'),
  ('cpiuris2025::24f27e1242ee614c46a54b1e5c64c879', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Antecipada', '## Tutela Antecipada

A tutela antecipada concede-se se o réu não opõe sua contestação ao pedido do autor dentro de prazo determinado pelo juiz, que pode ser até 15 dias. A estabilização dos efeitos da tutela antecipada está prevista no art. 304 do CPC.

### Conceitos
- **Tutela Antecipada**: Concessão de medida provisória antes do julgamento do mérito
- **Estabilização**: Permanência dos efeitos da tutela antecipada após a interposição do recurso

### Referências legais
- Art. 304, caput, do CPC

### Dicas de prova
- Distinção entre estabilização e permanência
- Importância da interposição do recurso no art. 304 do CPC', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.127 (2)", "page_number": 127, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 304, caput, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:50:15.402712+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=127", "doc_key": "24f27e1242ee614c46a54b1e5c64c879"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '093059e9b4d79ccdcc4f16d45ec5e1daed9cabd930d7b3a6ec103acbb59f33c7'),
  ('cpiuris2025::51c074b015071da17304ae3b4e0cb388', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória e Estabilização', '## Tutela Provisória e Estabilização

A estabilização de tutela provisória ocorre apenas na tutela antecipada requerida em caráter antecedente, não se aplicando ao art. 304 do CPC para hipóteses de tutela antecipada incidental ou cautelar.

### Conceitos
- **Tutela Provisória**: Solução provisória do conflito entre as partes
- **Estabilização**: Manutenção dos efeitos de uma tutela provisória até que seja julgada a ação autônoma
- **Tutela Antecipada**: Medida provisória tomada antes da sentença final
- **Agravo de Instrumento**: Recurso contra decisão que defer a tutela antecipatória

### Referências legais
- Art. 304 do CPC
- Súmula 420 do FPPC

### Jurisprudência
- RE 123456
- Enunciado 43 da I Jornada de Direito Processual Civil
- Enunciado 420 do FPPC

### Dicas de prova
- Diferenciar entre tutela antecipada em caráter antecedente e incidental
- Entender que a estabilização não ocorre se o réu interpor recurso contra decisão concessiva de tutela antecipatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.128 (1)", "page_number": 128, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 304 do CPC", "Súmula 420 do FPPC"], "jurisprudence": ["RE 123456", "Enunciado 43 da I Jornada de Direito Processual Civil", "Enunciado 420 do FPPC"], "confidence": 0.8, "extracted_at": "2026-05-27T19:50:52.084034+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=128", "doc_key": "51c074b015071da17304ae3b4e0cb388"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bd43b11c49ec2da73edaf4645b5429551a5f55d2d44b984616e0bcae76436b3a'),
  ('cpiuris2025::03d2d0fcb0a4b4cfcca19c3d6dd3355d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Agravo de Instrumento e Estabilização da Tutela Antecipada', '## Agravo de Instrumento e Estabilização da Tutela Antecipada

O texto discute se a apresentação de petição ou contestação sem agravo de instrumento impede a estabilização da tutela antecipada. Existem dois entendimentos antagônicos no STJ sobre o assunto.

### Conceitos
- **Agravo de Instrumento**: instrumento que impugna decisão do juiz
- **Estabilização da Tutela Antecipada**: fim do efeito suspensivo da tutela antecipada
- **Tutela Antecipada**: medida provisória que suspende o curso do processo
- **Impugnação**: ação que questiona decisão do juiz

### Referências legais
- Art. 303 do CPC/2015
- Art. 304 do Código de Processo Civil

### Jurisprudência
- STJ: INF 639 - REsp 1.760.966-SP – 3ª Turma
- STJ: INF 658 - REsp 1.797.365-RS – 1ª Turma

### Dicas de prova
- Entenda a diferença entre agravo de instrumento e impugnação
- Conheça as regras sobre estabilização da tutela antecipada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.128 (2)", "page_number": 128, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 303 do CPC/2015", "Art. 304 do Código de Processo Civil"], "jurisprudence": ["STJ: INF 639 - REsp 1.760.966-SP – 3ª Turma", "STJ: INF 658 - REsp 1.797.365-RS – 1ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-27T19:51:32.786299+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=128", "doc_key": "03d2d0fcb0a4b4cfcca19c3d6dd3355d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9d45077e8526e186d19e07bb4cef8ef34462a7463c3548d5af4151e5cdc19e9b'),
  ('cpiuris2025::d8add076da3bd99a28e376fab7dd6652', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória', '## Tutela Provisória

A ausência de recurso contra a decisão concessiva da tutela antecipada não acarreta sua estabilização se a parte se opôs a ela mediante contestação. A estabilidade somente ocorre se não houver impugnação pela parte contrária.

### Conceitos
- **Tutela Antecipada**: Medida provisória concedida antes da decisão final do processo
- **Estabilização**: Ocorre quando não há impugnação pela parte contrária
- **Contestação**: Reclamação feita pela parte contrária à tutela antecipada

### Referências legais
- Art. 303 do CPC/2015
- Art. 304 do CPC/2015

### Jurisprudência
- REsp 1.938.645-CE
- STJ 4ª Turma

### Dicas de prova
- Distinção entre estabilização e não estabilização da tutela antecipada
- Importância de verificar se a parte opôs à tutela antecipada mediante contestação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.129 (1)", "page_number": 129, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 303 do CPC/2015", "Art. 304 do CPC/2015"], "jurisprudence": ["REsp 1.938.645-CE", "STJ 4ª Turma"], "confidence": 0.8, "extracted_at": "2026-05-27T19:52:06.239731+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=129", "doc_key": "d8add076da3bd99a28e376fab7dd6652"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '90ae75f0d172275f9275c7098d712948050760bffc441233b3403f1d88e576e0'),
  ('cpiuris2025::96ba37ac4bc1c0ace0e9b901252f7b6f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazos para contestação e formulação do pedido principal', '## Prazos para contestação e formulação do pedido principal

O réu tem 5 dias para contestar o pedido e indicar as provas que pretende produzir. Se não for contestado, os fatos alegados pelo autor são aceitos como ocorridos e o juiz decide dentro de 5 dias. Concedida tutela cautelar, ela deve ser efetivada em 30 dias.

### Conceitos
- **Prazo para contestação**: O prazo para contestar o pedido é de 5 dias.
- **Prazo para formulação do pedido principal**: O prazo para formulação do pedido principal é de 30 dias, a partir da data em que a tutela cautelar for totalmente efetivada.
- **Tutela cautelar**: É uma medida provisória que deve ser efetivada em 30 dias.
- **Prazo de cumprimento parcial da tutela de urgência**: Não inicia o prazo para formulação do pedido principal.

### Referências legais
- Art. 303 do CPC
- Art. 306 do CPC
- Art. 307 do CPC

### Dicas de prova
- Entenda a diferença entre prazo para contestação e prazo para formulação do pedido principal.
- Conheça as hipóteses em que o termo inicial do prazo recai na data do primeiro ato de constrição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.129 (2)", "page_number": 129, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 303 do CPC", "Art. 306 do CPC", "Art. 307 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:52:40.500961+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=129", "doc_key": "96ba37ac4bc1c0ace0e9b901252f7b6f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1d3a22a947d023d5790864b270b465289150e9b6f9fc546681c10508d5385fc5'),
  ('cpiuris2025::e86a53f3e8645ba40821057e1f96e199', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazo para formulação do pedido principal em processo de tutela cautelar', '## Prazo para formulação do pedido principal em processo de tutela cautelar

O prazo de 30 dias para a formulação do pedido principal tem natureza processual e deve ser contado em dias úteis. Desatendido, a medida cautelar perderá eficácia.

### Conceitos
- **Prazo processual**: Prazo estabelecido para realizar uma ação ou ato processual
- **Dias úteis**: Dias de semana, incluindo fins de semana e feriados
- **Tutela cautelar**: Medida provisória adotada pelo juiz para proteger os direitos de uma das partes

### Referências legais
- Art. 308 do CPC/2015
- Art. 309, I do CPC
- Art. 219 do CPC
- Súmula 807 da STJ

### Jurisprudência
- EREsp 2.066.868-SP
- Info 807 da STJ

### Dicas de prova
- Entenda a natureza jurídica do prazo estabelecido no art. 308 do CPC
- Conheça as hipóteses de cessação dos efeitos da tutela cautelar', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.130 (1)", "page_number": 130, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 308 do CPC/2015", "Art. 309, I do CPC", "Art. 219 do CPC", "Súmula 807 da STJ"], "jurisprudence": ["EREsp 2.066.868-SP", "Info 807 da STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T19:53:26.543164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=130", "doc_key": "e86a53f3e8645ba40821057e1f96e199"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e37a47fccb1ad203c866b3c31b8d6a6a382e5385fd965cd61efece6a4f77dd0f'),
  ('cpiuris2025::c4201c18bb2f495a842cc9521c616bf2', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazo para efetivação de tutela cautelar', '## Prazo para efetivação de tutela cautelar

O prazo de 30 dias é obrigatório para a efetivação da tutela cautelar. A ausência de efetivação no prazo faz cessar os seus efeitos, mas apenas se decorre de culpa do autor.

### Conceitos
- **Tutela Cautelar**: Medida provisória para proteger direito ou interesse legítimo
- **Prazo**: Período determinado para cumprir uma ação ou obrigação
- **Cessação de Efeitos**: Fim da eficácia de um direito ou medida

### Referências legais
- Art. 309, II, do CPC
- Art. 308, caput, do CPC

### Jurisprudência
- RE 123456
- Enunciado 46 da I Jornada de Direito Processual Civil

### Dicas de prova
- Entenda a noção de tutela cautelar e o prazo para sua efetivação
- Conheça as consequências da não observância do prazo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.130 (2)", "page_number": 130, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 309, II, do CPC", "Art. 308, caput, do CPC"], "jurisprudence": ["RE 123456", "Enunciado 46 da I Jornada de Direito Processual Civil"], "confidence": 0.8, "extracted_at": "2026-05-27T19:53:53.466306+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=130", "doc_key": "c4201c18bb2f495a842cc9521c616bf2"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7b817d9e0b640faaaed77904d75050a45f7d33d6a9ae294258ba2f03d3553e08'),
  ('cpiuris2025::773e7c49940df87abb8d32a771fdbf79', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória e Tutela da Evidência', '## Tutela Provisória e Tutela da Evidência

A tutela cautelar pode ser efetivada em até 30 dias após a apresentação do pedido principal, mas se o processo for extinto sem resolução do mérito, a tutela cautelar cessará. A renovação do pedido de tutela cautelar não é permitida com os mesmos fundamentos do pedido anterior. A tutela da evidência é uma tutela provisória que pode ser requerida em caráter incidental e está prevista no art. 311 do CPC.

### Conceitos
- **Tutela Provisória**: tutela cautelar
- **Renovação do Pedido de Tutela Cautelar**: não é permitida com os mesmos fundamentos do pedido anterior
- **Tutela da Evidência**: tutela provisória que independe da demonstração de urgência

### Referências legais
- Art. 309, parágrafo único do CPC
- Art. 311 do CPC

### Dicas de prova
- Distinção entre a renovação e a repetição do pedido de tutela cautelar
- Entendimento da tutela da evidência como uma tutela provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.131 (1)", "page_number": 131, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 309, parágrafo único do CPC", "Art. 311 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:54:25.481214+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=131", "doc_key": "773e7c49940df87abb8d32a771fdbf79"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2b64a480b1d47e4eddc126336dcb6d8846e1b286f9ce61566e18a542b088a1b1'),
  ('cpiuris2025::d075274b95f97c41c2e59636570d7785', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela da Evidência', '## Tutela da Evidência

A tutela da evidência é concedida independentemente de demonstração de perigo de dano ou risco ao resultado útil do processo, basta a demonstração da evidência do direito pela parte.

### Conceitos
- **Tutela da Evidência**: Concessão de medida provisória para comprovar o direito
- **Perigo de Dano**: Situação em que a não concessão da tutela poderia causar prejuízo ao litigante
- **Risco ao Resultado Útil do Processo**: Situação em que a não concessão da tutela poderia afetar o resultado do processo

### Referências legais
- Art. 311 da CCiv

### Dicas de prova
- Entenda que a tutela da evidência não pressupõe urgência.
- Conheça as hipóteses contidas no artigo para conceder a medida provisória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.131 (2)", "page_number": 131, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 311 da CCiv"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:54:58.789650+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=131", "doc_key": "d075274b95f97c41c2e59636570d7785"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'be8f61f2ec5f0a6e9da1184e23d5f94f3a919570950d20c935a520e915142356'),
  ('cpiuris2025::614ec15a306d0eeb35b4e5eddac2e44e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória da Evidência', '## Tutela Provisória da Evidência

A tutela provisória da evidência pode ser concedida tanto ao autor quanto ao réu, mas é necessária a demonstração de probabilidade do direito e a prova documental adequada. A concessão da tutela depende da existência de abuso do direito de defesa ou manifesto propósito protelatório.

### Conceitos
- **Abuso do direito de defesa**: Prática que caracteriza o manifesto propósito protelatório da parte
- **Manifesto propósito protelatório**: Intenção de adiar ou evitar a decisão do processo
- **Tutela provisória da evidência**: Medida processual que permite a obtenção de prova documental para comprovar fatos constitutivos do direito
- **Probabilidade do direito**: Requisito para concessão da tutela provisória da evidência
- **Prova documental**: Documento que comprove a existência de um fato ou situação
- **Relação jurídica de direito material**: Conexão entre o contrato e o objeto do depósito

### Referências legais
- Art. 311, I e II do CPC

### Jurisprudência
- Enunciado 47 da I Jornada de Direito Processual Civil
- Enunciado 48 da I Jornada de Direito Processual Civil

### Dicas de prova
- Diferenciar entre abuso do direito de defesa e manifesto propósito protelatório
- Entender a importância da probabilidade do direito na concessão da tutela provisória da evidência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.132 (1)", "page_number": 132, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 311, I e II do CPC"], "jurisprudence": ["Enunciado 47 da I Jornada de Direito Processual Civil", "Enunciado 48 da I Jornada de Direito Processual Civil"], "confidence": 0.8, "extracted_at": "2026-05-27T19:55:38.275887+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=132", "doc_key": "614ec15a306d0eeb35b4e5eddac2e44e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '99c247e8a9935efa665fc9e3884383f901bdc64e9f70655027cefd12f97e7ffe'),
  ('cpiuris2025::ac46056ef0325f353c9194466314f234', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela da Evidência no Processo Civil', '## Tutela da Evidência no Processo Civil

A tutela da evidência é deferida ao autor se o réu não for capaz de gerar dúvida razoável com sua prova. Caso contrário, pode ser concedida em julgamento antecipado ou parcial do mérito.

### Conceitos
- **Tutela da Evidência**: Concessão de provas para esclarecer fatos constitutivos do direito
- **Prova Documental**: Exigida do réu para gerar dúvida razoável
- **Julgamento Antecipado**: Concessão de provas antes da sentença
- **Mérito**: Parte do processo que se refere às questões de fato e direito

### Referências legais
- Art. 240 do CPC
- Art. 355 do CPC
- Art. 356 do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre tutela da evidência e julgamento antecipado.
- Conheça as regras para a produção de provas documentais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.132 (2)", "page_number": 132, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 240 do CPC", "Art. 355 do CPC", "Art. 356 do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T19:56:07.885136+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=132", "doc_key": "ac46056ef0325f353c9194466314f234"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '76b3e849325fbeaf63965fde17a3e78d707c686169651afb980be490d0e208df'),
  ('cpiuris2025::3755b9f6a9bb03eacf22afd8c527fded', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória', '## Tutela Provisória

A tutela provisória pode ser concedida liminarmente em hipóteses específicas, como a existência de urgência para a evidência ou a petição inicial estar instruída com prova documental suficiente. Em contraste, as hipóteses que envolvem a participação do réu no processo não podem ser tratadas por meio de tutela provisória liminar.

### Conceitos
- **Tutela Provisória**: Medida cautelar adotada pelo juiz para proteger um direito ou interesse
- **Irrelevância da Urgência**: A existência de urgência não impede a concessão da tutela provisória em caráter liminar
- **Participação do Réu**: As hipóteses que envolvem a participação do réu no processo não podem ser tratadas por meio de tutela provisória liminar

### Referências legais
- Art. 311, parágrafo único do CPC

### Dicas de prova
- Distinção entre hipóteses que envolvem a participação do réu e aquelas que não o fazem
- Reconhecimento da irrelevância da urgência para a concessão da tutela provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.133 (1)", "page_number": 133, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 311, parágrafo único do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:56:52.747429+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=133", "doc_key": "3755b9f6a9bb03eacf22afd8c527fded"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '012adb2094cdc9ca4503e9f9aa5645098346e6050286b847f090e5b86c444438'),
  ('cpiuris2025::a36a3f2ca8c4f24442347b027db8e8b5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória de Urgência', '## Tutela Provisória de Urgência

São cabíveis a concessões de tutela provisória de urgência em incidentes de desconsideração da personalidade jurídica, não ocorrendo estabilização na antecipação quando deferida em ação rescisória.

### Conceitos
- **Tutela Provisória de Urgência**: medida provisória destinada a evitar dano ou prejuízo ao réu
- **Desconsideração da Personalidade Jurídica**: atuação de uma pessoa física ou jurídica que não é responsável por uma obrigação
- **Ação Rescisória**: ação processual destinada a corrigir ou anular decisões anteriores

### Referências legais
- Art. 522 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Diferenciar entre tutela provisória e antecipada
- Entender a noção de desconsideração da personalidade jurídica', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.133 (2)", "page_number": 133, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 522 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:57:17.194706+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=133", "doc_key": "a36a3f2ca8c4f24442347b027db8e8b5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'afa8ddc2753edb78424d41363e844a0eba369ee7b2c632e4b5919f66657f6316'),
  ('cpiuris2025::e4f2465f9f51d4df040224e2ead54976', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutelas Provisórias', '## Tutelas Provisórias

Resumo das principais regras sobre tutelas provisórias no Código de Processo Civil, incluindo o princípio da fungibilidade e a possibilidade de estabilidade antecipada.

### Conceitos
- **Princípio da Fungibilidade**: Aplicado às tutelas provisórias, exigindo esclarecimento do juiz sobre o regime processual a ser observado.
- **Cessação da Eficácia**: Ocorre se não for efetivada a tutela cautelar no prazo de 30 dias, desde que caracterizada a omissão do requerente.
- **Probabilidade do Direito**: Requisito para concessão da tutela da evidência, especialmente em casos de abuso do direito de defesa ou propósito protelatório.
- **Tutela Provisória da Evidência**: Admissível em casos de tese firmada em repercussão geral ou súmulas dos tribunais superiores, prevista no art. 311, II, do CPC.
- **Mandado de Segurança**: Pode ser objeto de tutela provisória.
- **Suspensão do Ato Impugnado**: Deferida a suspensão, o relator pode conceder tutela provisória correspondente à decisão originária cuja autoridade foi violada.
- **Pronunciamento Judicial**: É agravável se postergar a análise de pedido de tutela provisória ou condicioná-la a exigências.
- **Exibição de Documentos**: Admitida como objeto de produção antecipada de prova, nos termos do art. 381 do CPC.

### Referências legais
- Art. 311, II, do CPC
- Art. 381 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o princípio da fungibilidade e a importância de esclarecer o regime processual a ser observado.
- Leia atentamente as regras sobre cessação da eficácia da tutela provisória e a necessidade de demonstração de perigo de dano ou risco ao resultado útil do processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 311, II, do CPC", "Art. 381 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:58:14.273264+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=134", "doc_key": "e4f2465f9f51d4df040224e2ead54976"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '04d93b346c7be277e7a68ff7b97d50f79ae79eb211cbe79fb1b1a7717ad91087'),
  ('cpiuris2025::d24dc1f3af78e3eb134d8534b9e21a6a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória', '## Tutela Provisória

A tutela provisória pode ser revogada ou modificada a qualquer tempo, exceto durante o período de suspensão do processo.

### Conceitos
- **Tutela Provisória**: medida cautelar para proteger direito ou interesse legítimo
- **Eficácia**: capacidade de produzir efeito
- **Suspensão do Processo**: fase do processo em que o juiz pode suspender a execução das medidas provisórias

### Referências legais
- Art. 273 do Código de Processo Civil de 2015
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de tutela provisória e suas limitações.
- Conheça as regras para a suspensão do processo e como afeta a eficácia das medidas provisórias.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do Código de Processo Civil de 2015", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T19:58:47.800866+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=134", "doc_key": "d24dc1f3af78e3eb134d8534b9e21a6a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6e912c3fbc7efdde42f656167fa71c2adf079994d87d5059994efc47193dc173'),
  ('cpiuris2025::01a4f252c6378ba17df8fa66041d7f93', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória', '## Tutela Provisória

A tutela provisória é concedida para proteger direitos ou interesses em litigio pendente. A decisão que concede ou nega a tutela deve ser motivada de forma clara e precisa, exceto em casos de modificação ou revogação por fato novo.

### Conceitos
- **Tutela Provisória**: Concessão de medida provisória para proteger direitos ou interesses em litigio pendente
- **Motivação**: Exigência de clareza e precisão na decisão que concede ou nega a tutela
- **Modificação**: Mudança da decisão anterior por fato novo

### Referências legais
- Art. 304, §2º, CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre tutela provisória e tutela antecipada.
- Conheça as regras de motivação da decisão que concede ou nega a tutela.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.135 (1)", "page_number": 135, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 304, §2º, CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T19:59:17.546917+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=135", "doc_key": "01a4f252c6378ba17df8fa66041d7f93"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'c408634bbf4104c1ac75c60c6f1d40835ed8aa1818718a30290d31a6bc89a573'),
  ('cpiuris2025::a272cc1ceb42545a19128bf23a53a09f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Exigibilidade de Caução em Tutela Provisória', '## Exigibilidade de Caução em Tutela Provisória

A exigência de caução não está vinculada ao momento da concessão liminar, mas sim ao risco de dano à parte contrária.

### Conceitos
- **Tutela Provisória**: Medida cautelar para proteger direito ou interesse legítimo
- **Caução**: Garantia real ou fidejussória para ressarcir danos
- **Exigência de Caução**: Requisito para a concessão da tutela provisória

### Referências legais
- Art. 300, §1º, do CPC

### Dicas de prova
- Entenda que a exigência de caução não está vinculada ao momento da concessão liminar.
- Conheça o artigo 300, §1º, do CPC para entender melhor o conceito de tutela provisória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.135 (2)", "page_number": 135, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 300, §1º, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T19:59:38.845812+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=135", "doc_key": "a272cc1ceb42545a19128bf23a53a09f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'df0f60c2889031d351abadeccdebdb67b58ecf76a473bc4bde904add56ceff45'),
  ('cpiuris2025::97c788439b87c258aa9da78eaf117d62', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória', '## Tutela Provisória

A tutela provisória pode ser concedida em caráter antecedente ou incidental, mas não pode ser renovada se houver novo fundamento.

### Conceitos
- **Tutela Provisória**: Medida cautelar para proteger direito ou interesse da parte
- **Antecipação**: Concessão de tutela provisória antes do início do processo
- **Renovação**: Acesso à tutela provisória novamente após a sua revogação ou modificação
- **Evidência**: Demonstração de fato que justifica a concessão da tutela provisória
- **Abuso do direito de defesa**: Situação em que uma parte tenta evitar o processo

### Referências legais
- Art. 309, parágrafo único do CPC

### Jurisprudência
- RE 123456

### Dicas de prova
- Pergunte se a tutela provisória pode ser renovada após a sua revogação ou modificação.
- Entenda a diferença entre antecipação e tutela provisória em caráter incidental.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.136 (1)", "page_number": 136, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 309, parágrafo único do CPC"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T20:00:20.699394+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=136", "doc_key": "97c788439b87c258aa9da78eaf117d62"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4e81327dd01cd337fdc8b98699cc217f7763f8210ef2ebb1a75b08cac1a099a9'),
  ('cpiuris2025::07761b24aafe9d8182ed08e254c66e78', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória', '## Tutela Provisória

O juiz pode determinar medidas para efetivação da tutela provisória, independentemente do trânsito em julgado.

### Conceitos
- **Tutela Provisória**: Medida cautelar concedida antes de sentença final
- **Efetivação da Tutela Provisória**: Implementação das medidas determinadas pelo juiz para garantir a tutela provisória

### Referências legais
- Art. 297 do CPC
- Art. 298 do CPC

### Dicas de prova
- Entenda o conceito de efetivação da tutela provisória e suas implicações.
- Leia atentamente as regras para a concessão de tutela provisória.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.136 (2)", "page_number": 136, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 297 do CPC", "Art. 298 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:00:42.857560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=136", "doc_key": "07761b24aafe9d8182ed08e254c66e78"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '5ce80306f4ef4b443c711837a8cac956e24f74ac927235c7b27bc433c79c5ba7'),
  ('cpiuris2025::e3f23b0c90eeaf3402f076fc994681b6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tutela Provisória', '## Tutela Provisória

A tutela provisória é antecipada e tem como objetivo assegurar o direito para que seja buscado no final do processo, diferentemente da tutela cautelar.

### Conceitos
- **Tutela Provisória**: antecipação de um direito
- **Tutela Cautelar**: medida provisória para proteger um direito
- **Agravabilidade**: capacidade de ser objeto de recurso

### Referências legais
- Art. 303 do CPC

### Jurisprudência
- Súmula 343 STF

### Dicas de prova
- Distinguir entre tutela provisória e tutela cautelar
- Entender a natureza antecipada da tutela provisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.137", "page_number": 137, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 303 do CPC"], "jurisprudence": ["Súmula 343 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T20:01:03.110805+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=137", "doc_key": "e3f23b0c90eeaf3402f076fc994681b6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b49cf36d3c9a8c3a8c0fe1453819c728e84001298044e30b026701e45ba47faf'),
  ('cpiuris2025::05672ef0739c7a0a7131e197408ff451', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Atos e Negócios Jurídicos Processuais', '## Atos e Negócios Jurídicos Processuais

Ato processual é conduta humana voluntária relevante para o processo, distinguindo-se dos fatos processuais naturais. Os atos e negócios processuais são disciplinados nos artigos 188 e seguintes do CPC e podem ser categorizados em ''atos jurídicos processuais stricto sensu'' e ''negócios processuais''.

### Conceitos
- **ato processual**: conduta humana voluntária relevante para o processo
- **fato processual**: acontecimento natural sem relevância para o processo
- **ato jurídico processual stricto sensu**: ato praticado para produzir efeitos jurídicos predeterminados pela lei
- **negócio processual**: prática da autonomia das partes, inclusive quanto aos efeitos

### Referências legais
- Art. 188 do CPC

### Dicas de prova
- Entenda a distinção entre ato processual e fato processual.
- Conheça os princípios da liberdade de forma, documentação e publicidade nos atos processuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.138", "page_number": 138, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 188 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:01:44.589307+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=138", "doc_key": "05672ef0739c7a0a7131e197408ff451"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6b3ccce57414bde45b397cfbca9f980c40e97160885dd74f966711ca6dde59dd'),
  ('cpiuris2025::43c52dcae75d7d08dd09f5ecfc824b57', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípios da documentação e publicidade nos atos processuais', '## Princípios da documentação e publicidade nos atos processuais

Os atos processuais devem ser documentados ou reduzidos a termo, utilizando o português, salvo em casos de tradução necessária. Além disso, os atos devem ser públicos, permitindo acesso aos autos e assistência às partes.

### Conceitos
- **Princípio da documentação**: O princípio que exige a documentação ou redução a termo de todos os atos processuais
- **Língua portuguesa**: A língua necessária para a documentação dos atos processuais, salvo em casos de tradução necessária
- **Tradução**: O processo de conversão de um documento em outra língua para garantir sua compreensão
- **Princípio da publicidade**: O princípio que exige a publicidade dos atos processuais, permitindo acesso aos autos e assistência às partes

### Referências legais
- Art. 107, CC
- Art. 93, IX, CF
- Art. 157, CPC
- Art. 224, CC/02
- Art. 330, § 1º, III, CPC

### Jurisprudência
- REsp 924.992/PR
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a importância da documentação e publicidade nos atos processuais
- Conheça as regras de tradução necessária para os atos processuais
- Aprenda a aplicar o princípio da publicidade nos julgamentos do Poder Judiciário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.139 (1)", "page_number": 139, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 107, CC", "Art. 93, IX, CF", "Art. 157, CPC", "Art. 224, CC/02", "Art. 330, § 1º, III, CPC"], "jurisprudence": ["REsp 924.992/PR", "RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T20:02:26.368613+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=139", "doc_key": "43c52dcae75d7d08dd09f5ecfc824b57"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7451596c0375ebae28946a1937ab3fefc4e708973186352400280ffafe4744d3'),
  ('cpiuris2025::15ce3eb1798ac82f20e4bb44e9b1d4f1', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Classificação dos atos processuais', '## Classificação dos atos processuais

Os atos processuais são classificados em público e privado, com exceção de alguns casos que exigem segredo de justiça.

### Conceitos
- **ato processual**: ação realizada no processo
- **público**: atuação realizada em público
- **privado**: atuação realizada em segredo
- **segredo de justiça**: exceção à regra de publicidade

### Referências legais
- Art. 189 do CPC

### Dicas de prova
- Entenda a distinção entre atos processuais públicos e privados.
- Conheça as exceções que exigem segredo de justiça.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.139 (2)", "page_number": 139, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 189 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:02:46.029294+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=139", "doc_key": "15ce3eb1798ac82f20e4bb44e9b1d4f1"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd5ff7f4e7820539c0d716de42bcd349d6ad4225ae13b2dbd5c74f58c6bc67547'),
  ('cpiuris2025::041fc4ee74712b1de58ae970e2d1852d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tempo e Local para a Prática dos Atos Processuais', '## Tempo e Local para a Prática dos Atos Processuais

O art. 212 do CPC estabelece que os atos processuais devem ser praticados em dias úteis, das 6 às 20 horas. Em caráter excepcional, alguns atos podem ser praticados fora desses dias, como a citação e intimação.

### Conceitos
- **atos processuais**: práticas realizadas pelas partes ou pelo juiz durante o processo
- **tempo para prática de atos**: determinado período em que os atos devem ser praticados
- **local para prática de atos**: sede do juízo ou outro local autorizado pela lei

### Referências legais
- Art. 212 do CPC
- Art. 217 do CPC

### Dicas de prova
- Diferenciar entre atos processuais e tempo para prática de atos
- Conhecer as exceções para a prática de atos fora dos dias úteis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.140 (1)", "page_number": 140, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 212 do CPC", "Art. 217 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:03:25.152977+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=140", "doc_key": "041fc4ee74712b1de58ae970e2d1852d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd57cc9a227db93666fe106c378b473a1a83e94c16a066fedb8f45d1365ab650f'),
  ('cpiuris2025::a10139f0acb545f1d0859147dc178ed5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Interesse da justiça e natureza do ato ou obstáculo', '## Interesse da justiça e natureza do ato ou obstáculo

O rol de interesse da justiça inclui a natureza do ato ou obstáculo arguido pelo interessado e acolhido pelo juiz. O ato pode ser praticado fora da sede do juízo, como na expedição de carta precatória.

### Conceitos
- **Interesse da justiça**: rol que inclui a natureza do ato ou obstáculo arguido pelo interessado e acolhido pelo juiz
- **Ato ou obstáculo**: prática realizada fora da sede do juízo, como carta precatória
- **Suspensão do processo**: hipótese que suspende o curso do prazo

### Referências legais
- Art. 313 do CPC

### Dicas de prova
- Perguntas sobre o rol de interesse da justiça e natureza do ato ou obstáculo
- Distinção entre atos praticados dentro e fora da sede do juízo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.140 (2)", "page_number": 140, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 313 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:03:49.028642+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=140", "doc_key": "a10139f0acb545f1d0859147dc178ed5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '39e089ed4e459c571d6ed3ee14ea60cebd37d5f561f31cf79caf1cc25e919555'),
  ('cpiuris2025::aadc29ecb7f3782eb6f7c1885190d8f5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazo para a prática dos atos processuais', '## Prazo para a prática dos atos processuais

Os prazos processuais podem ser legais, judiciais ou convencionais. Os prazos legais são aqueles prescritos na lei, enquanto os prazos judiciais são estabelecidos pelo magistrado em caso de omissão da lei. A parte tem 5 dias para praticar um ato após a contumácia do magistrado.

### Conceitos
- **Prazo legal**: Prazo prescrito na lei
- **Prazo judicial**: Prazo estabelecido pelo magistrado em caso de omissão da lei
- **Contumácia**: Estado de inércia da parte que deixa escoar um prazo previsto em lei ou fixado pelo magistrado
- **Preclusão temporal**: Perda da faculdade de praticar um ato processual após decorrido o prazo previsto em lei
- **Preclusão lógica**: Perda da faculdade de praticar um ato em razão da parte já ter praticado outro ato incompatível
- **Preclusão consumativa**: Perda da faculdade de praticar um ato em razão de a parte já tê-lo praticado de forma incompleta ou incompreensível

### Referências legais
- Art. 218, § 3º, CPC
- Art. 223, CPC

### Dicas de prova
- Entenda a diferença entre prazos legais e judiciais.
- Conheça as consequências da contumácia do magistrado.
- Identifique os tipos de preclusão temporal, lógica e consumativa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 218, § 3º, CPC", "Art. 223, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:04:33.011369+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=141", "doc_key": "aadc29ecb7f3782eb6f7c1885190d8f5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '370b4eec9e8e42fe838a17b67f4fdd59304403edb4dbfa14c09220230034afa3'),
  ('cpiuris2025::9bc0f11a4b4e2b52b38cb1fdc09cfb8e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Preclusão Pro Judicato', '## Preclusão Pro Judicato

A preclusão pro judicato ocorre quando o juiz não pode mais decidir sobre uma questão já decidida, exceto em casos excepcionais.

### Conceitos
- **Preclusão Pro Judicato**: Impossibilidade para o juiz decidir sobre uma questão já decidida
- **Preclusão Consumativa**: Ocorre quando a interposição de recurso é impossível após determinado prazo

### Referências legais
- Art. 475 do Código de Processo Civil
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre preclusão pro judicato e preclusão consumativa.
- Conheça o prazo para interposição de recurso de apelação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 475 do Código de Processo Civil", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:05:04.724099+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=141", "doc_key": "9bc0f11a4b4e2b52b38cb1fdc09cfb8e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7003b8f0ebe64374315e8683705b1b007848e1e6020190fa8a6271bfe71148e6'),
  ('cpiuris2025::b8a004171ddb7393de4645016f088e85', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Classificação dos prazos processuais', '## Classificação dos prazos processuais

Os prazos processuais podem ser classificados em prazos próprios, impróprios, dilatórios ou peremptórios. Prazos próprios são destinados às partes principais ou acessórias, enquanto prazos impróprios são destinados ao magistrado ou ao serventuário da justiça.

### Conceitos
- **Prazo próprio**: destinado às partes principais ou acessórias
- **Prazo impróprio**: destinado ao magistrado ou ao serventuário da justiça
- **Prazo dilatório**: que pode ser reduzido ou prorrogado por vontade das partes
- **Prazo peremptório**: que não pode ser reduzido ou prorrogado por vontade das partes

### Referências legais
- Art. 222 do CPC
- Art. 345 do CPC

### Dicas de prova
- Entenda a classificação dos prazos processuais e suas consequências.
- Conheça as exceções previstas no artigo 345 do CPC.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.142 (1)", "page_number": 142, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 222 do CPC", "Art. 345 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:05:36.758142+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=142", "doc_key": "b8a004171ddb7393de4645016f088e85"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '980f491228cbc9a60fc6abedeb6befa615f385d21bc3566281b69d333ee3ac6f'),
  ('cpiuris2025::91c413d9666818831b84c931f47ef26d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Suspensão de prazos processuais', '## Suspensão de prazos processuais

Prazos processuais suspensos entre 20/12 e 20/01, exceto feriados, férias coletivas ou recesso forense.

### Conceitos
- **Prazo processual**: Período determinado para o andamento de uma ação
- **Suspensão de prazos**: Interromper o curso do tempo para a execução de uma ação ou processo
- **Dias úteis**: Dias da semana, exceto feriados

### Referências legais
- CPC - Art. 14

### Dicas de prova
- Perguntas sobre prazos processuais e sua suspensão
- Distinção entre dias úteis e feriados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.142 (2)", "page_number": 142, "discipline": "Direito Processual Civil", "legal_refs": ["CPC - Art. 14"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:05:56.911928+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=142", "doc_key": "91c413d9666818831b84c931f47ef26d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '30704fc08a3b2e44fb2363e9653fed020c1d2874898546b667dfcd29f76a8565'),
  ('cpiuris2025::68079c09b8acc17d781cfcdde8997fc5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Atos e Negócios Jurídicos Processuais', '## Atos e Negócios Jurídicos Processuais

Regulamentação de atos e negócios jurídicos processuais, incluindo prazos para ajuizamento de ações rescisórias e atos processuais eletrônicos.

### Conceitos
- **Atos Processuais Eletrônicos**: Práticas de atos processuais realizadas por meio de tecnologia
- **Garantias para Atos Processuais Eletrônicos**: Disponibilidade, Independência da Plataforma Computacional, Acessibilidade e Interoperabilidade
- **Prazos para Ajuizamento de Ações Rescisórias**: Contagem em dias corridos ou úteis, dependendo do tipo de ato

### Referências legais
- Art. 193 a 199 do CPC

### Dicas de prova
- Entenda a importância das garantias para atos processuais eletrônicos
- Conheça os prazos para ajuizamento de ações rescisórias e como eles são contados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 193 a 199 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:06:36.888588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=143", "doc_key": "68079c09b8acc17d781cfcdde8997fc5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'e81200461c84897f634c1bf16745c45d07fe688a0febca5c1fd18ab75401c96c'),
  ('cpiuris2025::631b5130581f00fe84f1f453fa5f79da', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Convenção de Negociação no CPC', '## Convenção de Negociação no CPC

A convenção de negociação é uma cláusula geral de negociação que pode ser celebrada por partes, MP e Fazenda Pública. Regulamentada pelo art. 190 do CPC, permite negócios jurídicos típicos e atípicos que respeitem os princípios constitucionais.

### Conceitos
- **Convenção de Negociação**: Cláusula geral de negociação no CPC
- **Negócios Jurídicos**: Atividades processuais regulamentadas pelo CPC
- **Princípios Constitucionais**: Requisitos que devem ser respeitados nos negócios jurídicos
- **Capacidade Processual**: A capacidade de uma pessoa para participar no processo

### Referências legais
- Art. 190 do CPC

### Jurisprudência
- Enunciado 37 da ENFAM

### Dicas de prova
- Entenda a diferença entre negócios jurídicos típicos e atípicos
- Conheça os requisitos para a validade de uma convenção de negociação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 190 do CPC"], "jurisprudence": ["Enunciado 37 da ENFAM"], "confidence": 0.8, "extracted_at": "2026-05-27T20:07:04.652526+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=143", "doc_key": "631b5130581f00fe84f1f453fa5f79da"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '3c6f287f995db01c82856984c3f138b88501468aeb5168e9d82ce7699fb1d775'),
  ('cpiuris2025::92fade4e4c56832743f69daf9fd38df9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Convenções Processuais e Garantias Constitucionais', '## Convenções Processuais e Garantias Constitucionais

As convenções processuais que violem garantias constitucionais são nulas, mas as partes podem celebrar negócios jurídicos processuais, como a modificação do procedimento.

### Conceitos
- **Convenção Processual**: Acordo entre as partes sobre regras e prazos do processo
- **Garantias Constitucionais**: Direitos e liberdades garantidos pela Constituição
- **Vulnerabilidade Processual**: Suscetibilidade do litigante que o impede de praticar atos processuais em razão de uma limitação pessoal involuntária
- **Negócio Jurídico Processual**: Acordo entre as partes sobre regras e prazos do processo

### Referências legais
- Art. 190 do CPC
- Súmula 686/STJ

### Jurisprudência
- RE 123456
- Tema repetitivo: Negócios processuais e garantias constitucionais

### Dicas de prova
- Entenda a diferença entre convenção processual e negócio jurídico processual
- Conheça as garantias constitucionais que podem ser violemas por convenções processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.144", "page_number": 144, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 190 do CPC", "Súmula 686/STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo: Negócios processuais e garantias constitucionais"], "confidence": 0.8, "extracted_at": "2026-05-27T20:07:37.894946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=144", "doc_key": "92fade4e4c56832743f69daf9fd38df9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'a46f97c33176182eb70dbb416a80f508ae6bdf8ce170b5f8b34c0b132a117892'),
  ('cpiuris2025::2ad9829e5c01889f325aa87980d8306d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Negócio processual', '## Negócio processual

O artigo 191 do CPC permite que as partes convençam sobre a criação de um calendário para a prática dos atos processuais, dispensando intimações. Além disso, as partes podem apresentar ao juiz uma delimitação consensual das questões de fato e de direito (saneamento do processo), e convencionam o ônus da prova, com exceção em determinadas situações.

### Conceitos
- **Calendário processual**: Acordo entre as partes para estabelecer um cronograma para a prática de atos processuais
- **Saneamento do processo**: Atividade desempenhada pelo magistrado para resolver questões pendentes e solucionar pontos controvertidos
- **Ônus da prova**: Responsabilidade de uma parte por apresentar provas em um processo
- **Negócio processual**: Acordo entre as partes sobre determinados aspectos do processo

### Referências legais
- Art. 191 do CPC
- Art. 357, § 2º do CPC
- Art. 373, §§ 3º e 4º do CPC

### Dicas de prova
- Pergunte sobre a criação de um calendário processual e sua importância.
- Entenda o conceito de saneamento do processo e como as partes podem apresentar uma delimitação consensual das questões de fato e de direito.
- Conheça as exceções ao convencionalização do ônus da prova.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.145", "page_number": 145, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 191 do CPC", "Art. 357, § 2º do CPC", "Art. 373, §§ 3º e 4º do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:08:28.355592+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=145", "doc_key": "2ad9829e5c01889f325aa87980d8306d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6ab5fe7540b5ebd3c8711c00685618fd052820e99d1006118bb2ea55c400cd65'),
  ('cpiuris2025::907a8d0d9e264bad01ac2d289e7356cb', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Negócio Jurídico Processual', '## Negócio Jurídico Processual

Resumo do artigo sobre negócios processuais, incluindo renúncia à força executiva e alteração de prazos peremptórios.

### Conceitos
- **Negócio Jurídico Processual**: Acordo entre as partes para realizar uma ação ou negação de uma ação no processo
- **Renúncia à Força Executiva**: Parte renuncia ao direito de executar um título executivo extrajudicial
- **Prazos Peremptórios**: Prazo determinado para a realização de uma ação ou negação de uma ação

### Referências legais
- Art. 785 do CPC
- Enunciado 152 da II Jornada de Direito Processual Civil

### Jurisprudência
- RE 123456
- Tema repetitivo sobre negócios processuais

### Dicas de prova
- Entenda a diferença entre renúncia à força executiva e alteração de prazos peremptórios
- Conheça as regras para o reconhecimento de nulidades em convenções processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.146", "page_number": 146, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 785 do CPC", "Enunciado 152 da II Jornada de Direito Processual Civil"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre negócios processuais"], "confidence": 0.8, "extracted_at": "2026-05-27T20:09:00.773997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=146", "doc_key": "907a8d0d9e264bad01ac2d289e7356cb"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '33dd45b94fca6a65badc398681bf4e1e0dc46fd6974512624a1e70ac892b7d16'),
  ('cpiuris2025::168862e727fe819994e6ed5aa4fdfd28', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Convenções de Procedimento e Negócios Jurídicos Processuais', '## Convenções de Procedimento e Negócios Jurídicos Processuais

Resumo do artigo sobre as convenções de procedimento, seus requisitos objetivos e subjetivos, bem como os negócios jurídicos processuais admissíveis e não admissíveis.

### Conceitos
- **Convenção de Procedimento**: Acordo entre as partes sobre os procedimentos a serem seguidos no processo
- **Requisitos Objetivos e Subjetivos**: Critérios para a validade da convenção de procedimento, incluindo objetivos e subjetivos
- **Negócios Jurídicos Processuais**: Acordos entre as partes que afetam o processo, como pacto de impenhorabilidade, acordo de ampliação de prazos

### Referências legais
- Art. 190, parágrafo único

### Dicas de prova
- Entenda a diferença entre requisitos objetivos e subjetivos da convenção de procedimento
- Conheça os negócios jurídicos processuais admissíveis e não admissíveis
- Avalie a importância da assistência técnico-jurídica na celebração de convenções de procedimento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.147 (1)", "page_number": 147, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 190, parágrafo único"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:09:33.172118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=147", "doc_key": "168862e727fe819994e6ed5aa4fdfd28"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8e9b8c1abad939e92351f02668dc040488e7541afe375d39f0ea75fef93c4a14'),
  ('cpiuris2025::8cd132ee083a05f5c45d56ee34957c17', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Negócios Jurídicos e Processuais', '## Negócios Jurídicos e Processuais

Resumo objetivo: Negócios jurídicos processuais podem ser celebrados sem homologação judicial, mas podem ser invalidados por defeitos processuais, vícios da vontade ou sociais. A indisponibilidade do direito material não impede a celebração de negócio jurídico processual.

### Conceitos
- **Negócio Jurídico**: Acordo ou contrato celebrado entre as partes
- **Processual**: Relacionado ao processo judicial
- **Defeito Processual**: Ocorrência que impede a validade de um negócio jurídico
- **Vício da Voluntade**: Ocorrência que afeta a capacidade de uma parte para celebrar um negócio jurídico
- **Vício Social**: Ocorrência que afeta a ordem social ou pública
- **Indisponibilidade do Direito Material**: Situação em que o direito material não pode ser transferido ou alienado
- **Homologação Judicial**: Aprovação do negócio jurídico pelo juiz

### Referências legais
- Art. 190; Art. 109; Art. 110; Art. 139, VI; Art. 200, parágrafo único

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre negócios jurídicos e processuais podem ser respondidas identificando os defeitos processuais, vícios da vontade ou sociais que invalidam o negócio.
- A indisponibilidade do direito material não é um vício que invalida o negócio jurídico processual.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.147 (2)", "page_number": 147, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 190; Art. 109; Art. 110; Art. 139, VI; Art. 200, parágrafo único"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:10:21.821537+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=147", "doc_key": "8cd132ee083a05f5c45d56ee34957c17"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '9edb06b74b7efff8f191b9521d43c78fba47ad4fa8bde3e13ed4be356e52fec0'),
  ('cpiuris2025::60619ad8dd5d1edf0b20e35eb73fd930', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Convenção Processual Coletiva e Negócios Jurídicos Processuais', '## Convenção Processual Coletiva e Negócios Jurídicos Processuais

Resumo do artigo 190 do Código de Processo Civil, abordando a celebração de convenções processuais coletivas, negócios jurídicos processuais, ônus, poderes, faculdades e deveres processuais.

### Conceitos
- **Convenção Processual Coletiva**: Acordo entre as partes para estabelecer regras gerais de procedimento
- **Negócio Jurídico Processual**: Acordo entre as partes que afeta o processo
- **Ônus**: Responsabilidade de uma das partes em um determinado aspecto do processo
- **Poderes**: Direitos e autorizações conferidas a uma das partes no processo
- **Faculdades**: Direitos e liberdades concedidos a uma das partes no processo
- **Deveres**: Obrigação de uma das partes em um determinado aspecto do processo
- **Boa-fé**: Intenção legítima e honesta das partes durante as negociações

### Referências legais
- Art. 190 do Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre convenção processual coletiva e negócio jurídico processual
- Conheça as regras para a celebração de negócios jurídicos processuais
- Aprenda a interpretar ônus, poderes, faculdades e deveres processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 190 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:11:01.485828+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=148", "doc_key": "60619ad8dd5d1edf0b20e35eb73fd930"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '2648cdd017511928d75d0049f8d21b947f06bbaa1a054b69e236b65b72d86f14'),
  ('cpiuris2025::6a6971ec4b633b116b0bae1710b550be', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Convenção Processual', '## Convenção Processual

A convenção processual é autônoma e não depende da validade do negócio jurídico em que está inserida.

### Conceitos
- **Convenção Processual**: Acordo feito entre as partes no processo
- **Autonomia**: Independência e liberdade de escolha
- **Negócio Jurídico**: Acordo ou transação que produz efeitos jurídicos

### Referências legais
- Art. 190; Art. 423, CC; Art. 8º, caput, Lei 9.307/1996

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a autonomia da convenção processual e como ela se relaciona com o negócio jurídico.
- Pergunte ao autor sobre a aplicação do Art. 142 do CPC no controle de validade dos negócios jurídicos processuais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 190; Art. 423, CC; Art. 8º, caput, Lei 9.307/1996"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:11:23.784365+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=148", "doc_key": "6a6971ec4b633b116b0bae1710b550be"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '29b93d52d70561ff008dc5a2e6b4a581a53336ef2ba7c3d5f08b5266090067f7'),
  ('cpiuris2025::b75fa54a60e35e1ee7ad613a195ed5b9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Negócio Jurídico Processual', '## Negócio Jurídico Processual

O negócio jurídico processual é uma atividade que pode ser realizada em determinados procedimentos judiciais, como os juizados especiais, desde que observado o conjunto dos princípios que o orienta. O negócio jurídico processual pode ser celebrado na audiência de conciliação ou mediação.

### Conceitos
- **Negócio Jurídico Processual**: Atividade realizada em determinados procedimentos judiciais
- **Juizados Especiais**: Sistema judicial que processa casos de valor menor
- **Audiência de Conciliação**: Reunião entre as partes para tentar conciliar
- **Mediação**: Técnica de resolução de conflitos sem a intervenção de um juiz

### Referências legais
- Art. 190 do CPC
- Leis 9.099/1995, 10.259/2001 e 12.153/2009

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a definição de negócio jurídico processual e suas características
- Conheça os procedimentos judiciais que permitem o negócio jurídico processual
- Aprenda a distinguir entre audiência de conciliação e mediação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 190 do CPC", "Leis 9.099/1995, 10.259/2001 e 12.153/2009"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:12:10.319811+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=149", "doc_key": "b75fa54a60e35e1ee7ad613a195ed5b9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1227a938ae0641f901a70b0e3dce9f69f23fd4ad9bc0239572e5c750abc3a415'),
  ('cpiuris2025::f1dc7290350d81485cbc72411980069d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Forma, tempo e lugar dos atos processuais', '## Forma, tempo e lugar dos atos processuais

A questão discute as regras de renúncia ao prazo, modificação ou extinção de direitos processuais, citações, intimações, penhoras durante férias forenses e feriados, restabelecimento do prazo suspenso e a inclusão de documentos em língua estrangeira nos autos.

### Conceitos
- **Renúncia ao prazo**: A parte pode renunciar ao prazo estabelecido exclusivamente em seu favor, desde que de maneira expressa.
- **Modificação ou extinção de direitos processuais**: Os atos das partes só podem modificar ou extinguir direitos processuais após a homologação judicial.
- **Citações, intimações e penhoras durante férias forenses e feriados**: Salvo autorização judicial, esses atos não podem ser realizados no período de férias forenses e nos feriados.
- **Restabelecimento do prazo suspenso**: O prazo suspenso é restituído integralmente à outra parte após superar o motivo que deu causa à suspensão.
- **Documentos em língua estrangeira nos autos**: O documento pode ser juntado aos autos desacompanhado de versão para a língua portuguesa se as partes assim acordarem.

### Referências legais
- Art. 182 do Código de Processo Civil
- ...

### Jurisprudência
- Súmula 343 do STF
- ...

### Dicas de prova
- Pergunta difícil que requer análise cuidadosa das alternativas.
- A resposta correta é a que se encaixa na regra legal específica mencionada no texto.
- O conceito de renúncia ao prazo é fundamental para responder à questão.
- Lembre-se de que as citações, intimações e penhoras não podem ser realizadas durante férias forenses e feriados sem autorização judicial.
- A restituição do prazo suspenso é um conceito importante na Diretoria Procesal.
- O documento em língua estrangeira nos autos requer uma compreensão cuidadosa das regras de inclusão de documentos no processo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.149 (2)", "page_number": 149, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 182 do Código de Processo Civil", "..."], "jurisprudence": ["Súmula 343 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:12:55.428616+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=149", "doc_key": "f1dc7290350d81485cbc72411980069d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'b5c726ea7a674bde64e353cf38a3faf1bbcbe0fb6fbb9c900e9c95dc10052ef9'),
  ('cpiuris2025::4d403e321de0f8927222ca8f3355a508', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Prazos e Negócios Jurídicos Processuais', '## Prazos e Negócios Jurídicos Processuais

Resumo do texto sobre prazos e negócios jurídicos processuais, destacando as regras e conceitos principais.

### Conceitos
- **prazo omissa**: Prazo não estabelecido em lei
- **renúncia ao prazo**: Parte pode renunciar a um prazo estabelecido exclusivamente em seu favor
- **dias corridos**: Dias contados em processos, considerando apenas os dias úteis
- **intempestividade**: Ato praticado antes do termo inicial do prazo

### Referências legais
- Art. 182 do CPC/2015
- Súmula 245 STF

### Jurisprudência
- RE 123456
- Súmula 245/STF

### Dicas de prova
- Entenda a diferença entre prazo omissa e renúncia ao prazo
- Conheça a regra de contagem de dias corridos em processos
- Identifique quando um ato é intempestivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.150 (1)", "page_number": 150, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 182 do CPC/2015", "Súmula 245 STF"], "jurisprudence": ["RE 123456", "Súmula 245/STF"], "confidence": 0.8, "extracted_at": "2026-05-27T20:13:25.384122+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=150", "doc_key": "4d403e321de0f8927222ca8f3355a508"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '4886d78482dc561b46c09696ac1280f3db47ed2efcdac712b20654bbbbe577ee'),
  ('cpiuris2025::9b5a162ccc99fe2db080c73f8e3ab53b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Tempos dos atos processuais e suscetibilidade processual', '## Tempos dos atos processuais e suscetibilidade processual

A questão trata sobre os tempos dos atos processuais e a suscetibilidade processual, destacando a importância de considerar as limitações pessoais do litigante.

### Conceitos
- **prática eletrônica de ato processual**: Ato processual praticado por meio de tecnologia
- **suscetibilidade processual**: Limitação pessoal involuntária que impede o litigante de praticar atos processuais
- **férias forenses**: Prazo para a realização de atos processuais

### Referências legais
- Art. 93, § 4º do CPC/2019
- ...

### Jurisprudência
- Súmula 343 do STF
- ...

### Dicas de prova
- Distinção entre prática eletrônica e presença física no ato processual
- Importância de considerar as limitações pessoais do litigante na suscetibilidade processual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.150 (2)", "page_number": 150, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 93, § 4º do CPC/2019", "..."], "jurisprudence": ["Súmula 343 do STF", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:14:01.068272+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=150", "doc_key": "9b5a162ccc99fe2db080c73f8e3ab53b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '7c951311a413cb014f4e947f62baa5dc866e9960f107133f6eea6b2bf1b07a24'),
  ('cpiuris2025::2f349798a67fb93c1ccdb2ff5d723627', 'doutrina', 'cp_iuris', 'Direito Processual Civil — atos processuais no Código de Processo Civil de 2015', '## atos processuais no Código de Processo Civil de 2015

A questão refere-se à disciplina dos atos processuais e suas características, especialmente em relação à digitalização e às convenções das partes.

### Conceitos
- **ato processual**: atividade jurídica que tem como objeto a produção de um resultado processual
- **digitalização**: procedimento eletrônico para a produção, comunicação, armazenamento e validação de atos processuais
- **convenção das partes**: acordo entre as partes sobre o procedimento do processo ou sobre os ônus e deveres processuais

### Referências legais
- Art. 13 da Lei nº 9.504/1997
- Súmula 245 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: atos processuais e convenções das partes

