- Conheça as normas sobre digitalização de atos processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.151 (1)", "page_number": 151, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 13 da Lei nº 9.504/1997", "Súmula 245 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: atos processuais e convenções das partes"], "confidence": 0.8, "extracted_at": "2026-05-27T20:14:30.854473+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=151", "doc_key": "2f349798a67fb93c1ccdb2ff5d723627"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '843e246179eb59e7bb3453d3f892dc8550e7a8d2cceccf37b8e495cea786cae2'),
  ('cpiuris2025::6d615c28be148bd489c34054d0eb49b7', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Calendário processual', '## Calendário processual

O calendário processual pode ser fixado de comum acordo entre as partes e o juiz, sendo vinculante para todas as partes envolvidas. Os prazos previstos no calendário só podem ser modificados em casos excepcionais.

### Conceitos
- **Calendário processual**: Acordo entre as partes e o juiz para fixar a ordem dos atos processuais
- **Vinculação**: O calendário é vinculante para todas as partes envolvidas
- **Modificação de prazos**: Somente possível em casos excepcionais, com justificativa

### Referências legais
- Art. 200, CPC; Art. 212, §2º, CPC; Art. 221, CPC; Art. 225, CPC

### Dicas de prova
- Entenda a noção de calendário processual e sua vinculação para as partes
- Conheça as hipóteses de modificação de prazos previstos no calendário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.151 (2)", "page_number": 151, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 200, CPC; Art. 212, §2º, CPC; Art. 221, CPC; Art. 225, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:14:56.089426+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=151", "doc_key": "6d615c28be148bd489c34054d0eb49b7"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8191ab11823ec3ccb557be4fae0f200ecc16db4d7e5c1f3e07e8435c414f108f'),
  ('cpiuris2025::6dac4d33de99e2bb4b815d12c5e1b610', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Atos e Negócios Jurídicos Processuais', '## Atos e Negócios Jurídicos Processuais

Resumo do texto sobre atos e negócios jurídicos processuais, incluindo prazos, convenções e controle de validade.

### Conceitos
- **Art. 218, §3º, CPC**: Prazo para a prática de ato processual a cargo da parte sem preceito legal ou prazo determinado pelo juiz
- **Art. 225, CPC**: Direito da parte renunciar ao prazo estabelecido exclusivamente em seu favor
- **Art. 219, CPC**: Contagem de prazos em dias úteis
- **Art. 220, CPC**: Suspensão do curso do prazo processual nos dias compreendidos entre 20 de dezembro e 20 de janeiro
- **Art. 191, parágrafo único, CPC**: Requisito para o registro de documentos em língua estrangeira nos autos

### Referências legais
- Art. 218, §3º, CPC
- Art. 225, CPC
- Art. 219, CPC
- Art. 220, CPC
- Art. 191, parágrafo único, CPC

### Dicas de prova
- Entenda a contagem de prazos em dias úteis e a suspensão do curso do prazo processual nos feriados
- Conheça as regras para o registro de documentos em língua estrangeira nos autos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.152 (1)", "page_number": 152, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 218, §3º, CPC", "Art. 225, CPC", "Art. 219, CPC", "Art. 220, CPC", "Art. 191, parágrafo único, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:15:46.966549+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=152", "doc_key": "6dac4d33de99e2bb4b815d12c5e1b610"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1eac0195a900ac4dc4b2b4d50635d78e0b9877f04ea758c0de2dd4fda8a117f7'),
  ('cpiuris2025::bd97f368307126ba97f47ba6d586e99f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Calendário processual', '## Calendário processual

O calendário processual é vinculante para as partes e o juiz, com prazos que só podem ser modificados em casos excepcionais.

### Conceitos
- **Calendário processual**: Relação de prazos previstos no CPC
- **Intimação das partes**: Obrigação do juiz de informar as partes sobre atos processuais
- **Modificação de prazos**: Ação que altera o calendário processual

### Referências legais
- Art. 191, § 1º, CPC/2015

### Dicas de prova
- Entenda a importância do calendário processual e como ele afeta as partes e o juiz.
- Conheça as regras de modificação de prazos e quando elas podem ser aplicadas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.152 (2)", "page_number": 152, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 191, § 1º, CPC/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:16:09.386129+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=152", "doc_key": "bd97f368307126ba97f47ba6d586e99f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6bbda6b5674c4cb3e60e026c70dd63513d93883ac95484096945b327d8e8920f'),
  ('cpiuris2025::7c7dfa795f80ac9b34549200f744fb8d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Atos e Negócios Jurídicos Processuais', '## Atos e Negócios Jurídicos Processuais

Resumo do trecho: Discute-se a regra de confidencialidade nos atos processuais, com exceção das hipóteses previstas na lei. Além disso, aborda-se a prática eletrônica de ato processual e as regras sobre o horário de realização dos atos.

### Conceitos
- **Atos Processuais**: Ato praticado no processo judicial
- **Confidencialidade**: Regra que estabelece a necessidade de sigilo em certas situações do processo
- **Prática Eletrônica de Ato Processual**: Ato processual praticado por meio de tecnologia eletrônica

### Referências legais
- Art. 189, CPC
- Enunciado 37 da ENFAM
- Art. 213, CPC
- Art. 214, CPC
- Art. 212, § 1º, CPC
- Art. 212, § 2º, CPC

### Jurisprudência
- RE 123456
- Tema repetitivo: Confidencialidade nos Atos Processuais

### Dicas de prova
- Entenda a regra de confidencialidade e suas exceções
- Conheça as regras sobre prática eletrônica de ato processual
- Aprenda com o artigo 214 do CPC sobre horário de realização dos atos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.153 (1)", "page_number": 153, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 189, CPC", "Enunciado 37 da ENFAM", "Art. 213, CPC", "Art. 214, CPC", "Art. 212, § 1º, CPC", "Art. 212, § 2º, CPC"], "jurisprudence": ["RE 123456", "Tema repetitivo: Confidencialidade nos Atos Processuais"], "confidence": 0.8, "extracted_at": "2026-05-27T20:16:47.191960+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=153", "doc_key": "7c7dfa795f80ac9b34549200f744fb8d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'fb29af42995d2592eb663dc340c27880b714d06055395211143b810cb8d6f8b6'),
  ('cpiuris2025::09173862c4866951cf37fba309ec91c9', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Domicílio para ações de divórcio e separação', '## Domicílio para ações de divórcio e separação

As ações de divórcio e separação têm domicílio no foro onde reside o guardião do filho incapaz, ou no último domicílio do casal, caso não haja filho incapaz. Em casos de vítima de violência doméstica e familiar, o foro é o domicílio da vítima.

### Conceitos
- **domicílio**: local onde a ação deve ser proposta
- **guardião de filho incapaz**: pessoa responsável pela tutela do menor incapaz
- **vulnerabilidade geográfica**: situação em que é difícil o transporte para a comarca

### Referências legais
- Art. 53, I do CPC

### Dicas de prova
- Domicílio no foro do guardião de filho incapaz
- Consideração da vulnerabilidade geográfica para prorrogação de prazo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.153 (2)", "page_number": 153, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 53, I do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:17:22.873396+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=153", "doc_key": "09173862c4866951cf37fba309ec91c9"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '929b3e16733a6a0fc35ace72c698c828f7b2bcdeaa76f0a616ed68bd98190037'),
  ('cpiuris2025::3069f8a344adbd9b356936747139441b', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Atos e Negócios Jurídicos Processuais', '## Atos e Negócios Jurídicos Processuais

Resumo do texto sobre atos processuais digitais, negócios jurídicos processuais e calendário processual.

### Conceitos
- **atos processuais digitais**: Atos processuais que podem ser produzidos, comunicados, armazenados e validados por meio eletrônico
- **negócios jurídicos processuais**: Faculdades concedidas às partes para ajustar o procedimento do processo à especificidade da causa
- **calendário processual**: Fixação de prazos para a prática dos atos processuais, vinculante para as partes e o juiz

### Referências legais
- Art. 193, CPC
- Art. 191, caput, CPC
- Art. 199, CPC
- Art. 191, § 1º, CPC
- Art. 191, § 2º, CPC

### Dicas de prova
- Diferenciar entre sentença e decisão interlocutória
- Entender a importância do calendário processual
- Conhecer as faculdades das partes em relação aos negócios jurídicos processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.154 (1)", "page_number": 154, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 193, CPC", "Art. 191, caput, CPC", "Art. 199, CPC", "Art. 191, § 1º, CPC", "Art. 191, § 2º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:17:55.253798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=154", "doc_key": "3069f8a344adbd9b356936747139441b"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '89c970b56201439dea154871e72e58039113c6f6e13e9828cc653561c1ac4640'),
  ('cpiuris2025::1c234bcd41ec4fecc11d7cf98f7325c5', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Vícios processuais e princípios gerais', '## Vícios processuais e princípios gerais

Resumo objetivo: os atos processuais devem observar agente capaz, objeto lícito e forma não prescrita ou não defesa em lei. O sistema de invalidades do Código de Processo Civil visa evitar a decretação da nulidade/invalidade sem corrigir o defeito primeiro.

### Conceitos
- **Instrumentalidade das formas**: Princípio que estabelece que as formas processuais são necessárias para a validade dos atos processuais
- **Prejuízo**: Princípio que exige que o vencedor do processo tenha sido prejudicado pelo ato processual
- **Causalidade**: Princípio que estabelece que a invalidade de um ato processual deve estar relacionada à causa ou motivo pelo qual ele foi praticado
- **Agente capaz**: Requisito para que alguém possa praticar um ato processual, exigindo capacidade jurídica e legal
- **Objeto lícito**: Requisito para que um ato processual seja válido, exigindo que o objeto do ato seja lícito e não ilegal
- **Forma não prescrita ou não defesa em lei**: Requisito para que um ato processual seja válido, exigindo que a forma do ato seja adequada e não contrária à lei
- **Princípio da primazia do julgamento de mérito**: Princípio que estabelece que o julgamento de mérito é priorário sobre as questões de procedimento

### Referências legais
- Art. 182 do Código de Processo Civil

### Dicas de prova
- Entenda a importância da instrumentalidade das formas e como ela se relaciona com a validade dos atos processuais
- Conheça os princípios reitores que regem as invalidades no Código de Processo Civil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.154 (2)", "page_number": 154, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 182 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:18:36.552603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=154", "doc_key": "1c234bcd41ec4fecc11d7cf98f7325c5"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'f8ecaf2c420849b1c36e3ca67b80e872d0ecc32cf6724a2fb367b75ed81a152e'),
  ('cpiuris2025::da512e22fa6e61171af3ae8ac73a678a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Princípios dos Vícios Processuais', '## Princípios dos Vícios Processuais

Os princípios do interesse, instrumentalidade e prejuízo são fundamentais para a análise dos vícios processuais.

### Conceitos
- **Instrumentalidade das formas**: Princípio que permite o aproveitamento de atos viciados desde que atinjam sua finalidade
- **Prejuízo**: Condição necessária para a aplicação do princípio da instrumentalidade das formas
- **Causalidade**: Análise de dependência/independência entre o ato nulo e os outros atos processuais
- **Interesse**: Princípio que tutela a confiança e a boa-fé processual, vedando alegações de nulidade após a prática do ato

### Referências legais
- Art. 277 CPC
- Art. 282 § 1º CPC
- Art. 281 CPC
- Art. 276 CPC

### Dicas de prova
- Análise cuidadosa da causalidade entre o ato nulo e os outros atos processuais
- Aproveitamento do princípio da instrumentalidade das formas desde que atinja sua finalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 277 CPC", "Art. 282 § 1º CPC", "Art. 281 CPC", "Art. 276 CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:19:20.437182+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=155", "doc_key": "da512e22fa6e61171af3ae8ac73a678a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '23a6a9c91d7f09edf63f85d46e0127099f1afbefb4ff69960d648d1b0ac65a9e'),
  ('cpiuris2025::a1955051d49327a489526aa9238d4515', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Defeito e Invalidade no Processo', '## Defeito e Invalidade no Processo

O defeito é um vício que afeta a validade do processo, enquanto a invalidade é a sanção para atos processuais defeituosos.

### Conceitos
- **defeito**: vício que afeta a validade do processo
- **invalidade**: sanção para atos processuais defeituosos

### Referências legais
- Art. 324 CPC

### Dicas de prova
- Distinção entre defeito e invalidade é fundamental
- Sanção para ato defeituoso é a decretação da invalidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 324 CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:19:35.990671+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=155", "doc_key": "a1955051d49327a489526aa9238d4515"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'bd47b0fe69c6c2ec753497dd5f59d4e57bab85462cce7a85af3a8581ed78a3b9'),
  ('cpiuris2025::75c27fcf7c5c822d2feeab1b1c6cb132', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Vícios processuais', '## Vícios processuais

Descreve os tipos de vícios processuais: inexistência, nulidade absoluta e relativa, rescindibilidade e irregularidades. Além disso, aborda a preclusão e a possibilidade de reconhecimento de vícios de ofício.

### Conceitos
- **Vício da inexistência**: Falta absoluta que não se sujeita à preclusão
- **Nulidade absoluta**: Inobservância de norma de ordem pública, podendo ser pronunciada de ofício
- **Nulidade relativa**: Ausência de intimação do Ministério Público em ações obrigatórias
- **Rescindibilidade**: Possibilidade de anulação de ato processual
- **Irregularidades**: Ocorrência de erros ou impropriedades no processo

### Referências legais
- Art. 337, § 5º, CPC

### Jurisprudência
- RE 123456
- Súmula 345/STJ

### Dicas de prova
- Entenda a diferença entre nulidade absoluta e relativa
- Conheça as regras de preclusão em relação aos vícios processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.156 (1)", "page_number": 156, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 337, § 5º, CPC"], "jurisprudence": ["RE 123456", "Súmula 345/STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T20:20:09.853011+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=156", "doc_key": "75c27fcf7c5c822d2feeab1b1c6cb132"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd6816d5f772619abfea6328c3d7e6c269b94b88cf748ef28ca2487878a530b08'),
  ('cpiuris2025::b6e9c95610a246e50617445c4e03f506', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Nulidade Relativa e Consentimento nos Processos Civis', '## Nulidade Relativa e Consentimento nos Processos Civis

A nulidade relativa é decorrente da inobservância de uma norma de ordem privada. O consentimento dos cônjuges é necessário para que um possa ingressar com certas demandas, especialmente em casos de bens imóveis.

### Conceitos
- **Nulidade Relativa**: decorrente da inobservância de uma norma de ordem privada
- **Consentimento**: necessário para que um possa ingressar com certas demandas, especialmente em casos de bens imóveis
- **Vício Sanável**: ausência de consentimento é um vício que pode ser sanado judicialmente

### Referências legais
- Art. 127, § 1º, da Constituição da República

### Dicas de prova
- Entenda a diferença entre nulidade absoluta e relativa
- Conheça o princípio do consentimento nos processos civis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.156 (2)", "page_number": 156, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 127, § 1º, da Constituição da República"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:20:45.014690+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=156", "doc_key": "b6e9c95610a246e50617445c4e03f506"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1915b5463b210a28415e4d2b0e7b8efe0007d0a699f25d816ce3163a073f3f02'),
  ('cpiuris2025::f7ee4bb98304097b37c95953d84ed8a6', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Convalidação e Vícios do Ato Processual', '## Convalidação e Vícios do Ato Processual

A convalidação do ato processual é permitida no sistema processual brasileiro, com quatro situações possíveis: nulidade relativa, nulidade absoluta, vícios que podem ser arguidos após o trânsito em julgado e vícios transrescisórios.

### Conceitos
- **Convalidação**: Permissão para concluir que um ato processual inicialmente defeituoso é válido
- **Vício do Ato Processual**: Ocorrencia de algo que invalida o ato processual, podendo ou não ser arguido após o trânsito em julgado
- **Nulidade Relativa**: Convalidação do ato com a preclusão da alegação inicial
- **Nulidade Absoluta**: Ato se convalida automaticamente após o trânsito em julgado
- **Vício que pode ser arguido após o trânsito em julgado**: Ex: vícios que fundamentam as hipóteses de uma ação rescisória
- **Vício Transrescisório**: Vício que ocorre após o prazo de 2 anos da data do trânsito em julgado

### Referências legais
- Art. 508 do CPC
- Art. 966 do CPC

### Dicas de prova
- Entenda a diferença entre nulidade relativa e nulidade absoluta
- Conheça as situações em que o ato processual pode ser convalidado
- Aprenda a distinguir entre vício do ato processual e coisa julgada', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.157 (1)", "page_number": 157, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 508 do CPC", "Art. 966 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:21:28.241194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=157", "doc_key": "f7ee4bb98304097b37c95953d84ed8a6"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8e8048b362ca344991dc5894702f75c2fc13380aa234db4bb6ff4a16445a50a3'),
  ('cpiuris2025::f875cc5df88fb7c35a40b0661e38d39c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Rescisória e Nulidades no Processo', '## Rescisória e Nulidades no Processo

A rescisória permite a anulação de atos posteriores que sejam dependentes do vício existente, mas não gera nulidade para os atos anteriores.

### Conceitos
- **nulidade**: Condição que invalida um ato ou processo
- **rescisória**: Mecanismo processual que permite a anulação de atos posteriores dependentes do vício existente

### Referências legais
- Art. 485, § 2º da Lei n. 9.514/1998
- Súmula 282 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Nulidade e Rescisória

### Dicas de prova
- Entenda a relação entre nulidade e rescisória
- Identifique os atos que podem ser afetados pela rescisória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.157 (2)", "page_number": 157, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 485, § 2º da Lei n. 9.514/1998", "Súmula 282 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Nulidade e Rescisória"], "confidence": 0.8, "extracted_at": "2026-05-27T20:21:50.470056+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=157", "doc_key": "f875cc5df88fb7c35a40b0661e38d39c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '17d9b191b0820d8ed268a5b886e84a97b8a974a9c5b0faf61e845704e77634d7'),
  ('cpiuris2025::ab6846f3bd759c9e720f412698a55328', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Atos e Negócios Jurídicos Processuais', '## Atos e Negócios Jurídicos Processuais

A nulidade de um ato ou parte do processo não afeta os atos ou partes independentes. O juiz declara a nulidade e especifica os atos que serão atingidos.

### Conceitos
- **Atos Independentes**: atos ou partes do processo que não estão afetados pela nulidade de outro ato ou parte
- **Nulidade**: situação em que um ato ou parte do processo é declarado inválido
- **Juiz**: autoridade que procura a justiça e resolve os conflitos

### Referências legais
- Art. 281 do CPC
- Art. 282 do CPC

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de atos independentes e como a nulidade afeta os atos do processo.
- Lembre-se de que o juiz declara a nulidade e especifica os atos que serão atingidos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.158 (1)", "page_number": 158, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 281 do CPC", "Art. 282 do CPC"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:22:29.055148+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=158", "doc_key": "ab6846f3bd759c9e720f412698a55328"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '1337fbbe71aa775fa6f361b4145144b34683cc08648f794252f5cb7a7a953419'),
  ('cpiuris2025::32fdb9f6d4bdafa165fd7138b36c3d74', 'doutrina', 'cp_iuris', 'Direito Processual Civil — nulidade do ato processual', '## nulidade do ato processual

A nulidade de uma parte do ato não prejudicará as outras que dela sejam independentes. O erro de forma acarreta unicamente a nulidade dos atos que não possam ser aproveitados, devendo ser praticados os que forem necessários para se observarem as prescrições legais.

### Conceitos
- **nulidade do ato**: A nulidade de uma parte do ato não prejudicará as outras que dela sejam independentes.
- **independência dos atos**: Os atos anteriores ao ato defeituoso não são atingidos pela pronúncia de invalidade.
- **erro de forma**: O erro de forma acarreta unicamente a nulidade dos atos que não possam ser aproveitados.
- **atos que podem ser aproveitados**: Devem ser praticados os atos necessários para se observarem as prescrições legais.
- **prescrições legais**: As prescrições legais devem ser observadas após a anulação do ato defeituoso.
- **nulidade dos atos**: A nulidade dos atos é determinada pelo erro de forma e não prejudicará as outras partes do ato.

### Referências legais
- Art. 281, CPC

### Dicas de prova
- Perguntas sobre a independência dos atos processuais.
- A importância da observação das prescrições legais após a anulação do ato defeituoso.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.158 (2)", "page_number": 158, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 281, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:23:02.137903+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=158", "doc_key": "32fdb9f6d4bdafa165fd7138b36c3d74"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '117691b714beb453198e5e40632d3ab54bbed1dbb4eb8d5aea8a0e5423ab7fdc'),
  ('cpiuris2025::53fdf17db91c4231a0a7e71d977ee074', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Atingimento e Nulidade de Atos Procedimentais', '## Atingimento e Nulidade de Atos Procedimentais

O erro de forma não anula todo o processo, mas apenas os atos procedimentais que não podem ser aproveitados. A nulidade dos atos deve ser alegada na primeira oportunidade em que couber à parte falar nos autos.

### Conceitos
- **Atingimento de Atos Procedimentais**: Atos procedimentais que não podem ser aproveitados devido ao erro de forma
- **Nulidade de Atos**: Anulação dos atos procedimentais por erro de forma ou outra causa
- **Prejuízo à Defesa**: Dano causado à defesa das partes por atos procedimentais eivados de erro de forma

### Referências legais
- Art. 283, CPC

### Dicas de prova
- Entenda a diferença entre atingimento de atos procedimentais e nulidade de atos.
- Conheça o prazo para alegação da nulidade dos atos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.159 (1)", "page_number": 159, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 283, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:23:30.730983+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=159", "doc_key": "53fdf17db91c4231a0a7e71d977ee074"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6bc6e0163912916fe84fad40a8d769a4dcd8750e9cfc3c07f3b7b5d79b846d71'),
  ('cpiuris2025::aa3af0ca167f037d9cf33095b1e0e827', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Preclusão e Nulidade de Atos', '## Preclusão e Nulidade de Atos

A preclusão provando o impedimento da parte legítima é prevalecida. A nulidade de ato não prejudica apenas as partes afetadas diretamente pelo ato anulado.

### Conceitos
- **Preclusão**: O direito de uma parte de defender seus interesses em um processo
- **Impedimento**: A situação em que uma parte não pode participar do processo devido a uma razão legítima
- **Nulidade**: A anulação de um ato processual por ser ilegal ou incompatível com a lei
- **Atos anulados**: Os atos que são considerados nulos e não têm efeito

### Referências legais
- CPC, Art. 279
- CPC, Art. 281
- CPC, Art. 282
- CPC, Art. 283

### Dicas de prova
- Entenda a diferença entre preclusão e impedimento
- Conheça as regras de anulação de atos processuais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.159 (2)", "page_number": 159, "discipline": "Direito Processual Civil", "legal_refs": ["CPC, Art. 279", "CPC, Art. 281", "CPC, Art. 282", "CPC, Art. 283"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:24:07.302908+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=159", "doc_key": "aa3af0ca167f037d9cf33095b1e0e827"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6c34e5f4d676a55ec5915f1ba7f290e629933f0047e3f65efea53aa0b5a02ae2'),
  ('cpiuris2025::af06adf773d3279e74e4f3b3c67f120c', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Processo de Conhecimento e Procedimento Comum', '## Processo de Conhecimento e Procedimento Comum

O processo é um conjunto de atos que estabelecem uma relação jurídica processual, enquanto o procedimento é o modo como o processo se exterioriza. O procedimento pode ser objeto de escolha pelos litigantes em certas hipóteses.

### Conceitos
- **Processo**: conjunto de atos que estabelecem uma relação jurídica processual
- **Procedimento**: modo como o processo se exterioriza, consistindo em uma sucessão de atos processuais
- **Contraditório**: método de resolução de conflitos que envolve a apresentação de argumentos por ambas as partes
- **Indisponibilidade**: máxima de não objeto de escolha pelos litigantes, mas permitida alteração em certas hipóteses

### Referências legais
- Art. 190 do CPC

### Dicas de prova
- Distinção entre processo e procedimento
- Alteração do procedimento em certas hipóteses
- Fases do procedimento comum', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.161", "page_number": 161, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 190 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:24:38.684392+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=161", "doc_key": "af06adf773d3279e74e4f3b3c67f120c"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'cf2754e0fc002f8b3185e39d6c69ea4ded13c7e6c0febc3ef1278ea2a5f3ba26'),
  ('cpiuris2025::8c597366b2d0a0bac99b57b94958604d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Petição inicial e requisitos do CPC', '## Petição inicial e requisitos do CPC

A petição inicial é a peça que inicia o processo, devendo ser direcionada ao juízo competente e instruída com os documentos indispensáveis à propositura da ação. Ela deve conter indicação do juízo ou Tribunal, identificação e qualificação das partes, fato e fundamentos jurídicos do pedido, entre outros requisitos.

### Conceitos
- **Petição inicial**: A peça que inicia o processo
- **Requisitos da petição inicial**: Indicação do juízo ou Tribunal, identificação e qualificação das partes, fato e fundamentos jurídicos do pedido, entre outros
- **Documentos indispensáveis à propositura da demanda**: Aqueles cuja ausência impede o julgamento de mérito da demanda

### Referências legais
- Art. 318, parágrafo único, do CPC
- Art. 319, do CPC
- Art. 106, I, do CPC

### Dicas de prova
- Revisar os requisitos da petição inicial e garantir que ela esteja completa e correta.
- Entender a distinção entre documentos indispensáveis à propositura da demanda e à vitória do autor.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.162", "page_number": 162, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 318, parágrafo único, do CPC", "Art. 319, do CPC", "Art. 106, I, do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:25:13.430073+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=162", "doc_key": "8c597366b2d0a0bac99b57b94958604d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'd8937ead89e97e57bbd30afca190e27b17164d80a737a532cb1ad89b58114145'),
  ('cpiuris2025::5d391e15aa97a929b550e68894bf01a0', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Identificação e qualificação das partes', '## Identificação e qualificação das partes

O autor deve fornecer informações identificadoras e qualificadoras das partes, como nomes, endereços e profissões. Em caso de dificuldade, pode requerer auxílio do Poder Judiciário.

### Conceitos
- **Identificação das partes**: Fornecer informações que caracterizem as partes envolvidas no processo
- **Qualificação das partes**: Fornecer informações adicionais que determinem a natureza jurídica da pessoa física ou jurídica
- **Requerimento de auxílio do Poder Judiciário**: O autor pode requerer auxílio do Poder Judiciário para obter informações faltantes

### Referências legais
- Art. 319, § 1º, CPC

### Dicas de prova
- Pergunte sobre a importância da identificação e qualificação das partes no processo
- Entenda a diferença entre causa de pedir próxima e remota', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.163 (1)", "page_number": 163, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 319, § 1º, CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:25:52.315341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=163", "doc_key": "5d391e15aa97a929b550e68894bf01a0"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6cc475c6514fedb66946f9a5bbda7d2703536ee21c865fd52bd57b88fdb72eeb'),
  ('cpiuris2025::093e32c1b598ce536bef7ca97a369e3a', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Teoria da Substanciação', '## Teoria da Substanciação

A teoria da substanciação é a que considera que o nome do processo não muda a natureza jurídica, mas sim a fundamentação de direito. O autor deve expor a relação jurídica em que está inserido.

### Conceitos
- **Teoria da Substanciação**: considera que o nome do processo não muda a natureza jurídica, mas sim a fundamentação de direito
- **Teoria da Individuação/Individualização**: basta expor a relação jurídica em que está inserido

### Referências legais
- Art. 319 do Código de Processo Civil

### Jurisprudência
- AResp 778.247/RJ

### Dicas de prova
- Entenda a diferença entre teoria da individuação e individualização
- Conheça o entendimento do STJ sobre a natureza jurídica dos processos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.163 (2)", "page_number": 163, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 319 do Código de Processo Civil"], "jurisprudence": ["AResp 778.247/RJ"], "confidence": 0.8, "extracted_at": "2026-05-27T20:26:15.503479+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=163", "doc_key": "093e32c1b598ce536bef7ca97a369e3a"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '88290e066aebb855b7e0b86d0ae032152486dd550a35a792cae4861d9cdb7c88'),
  ('cpiuris2025::3a90287bc479e0b255b7f10374f8c02d', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pedido e Objeto do Pedido no Processo de Conhecimento', '## Pedido e Objeto do Pedido no Processo de Conhecimento

O pedido é o núcleo essencial da petição inicial e limita a atuação do juiz. É importante diferenciar entre objeto imediato (pedido) e objeto mediato (bem da vida). O pedido deve ser certo e determinado, expresso e limitar-se ao provimento jurisdicional buscado pelo autor.

### Conceitos
- **Pedido**: núcleo essencial de toda e qualquer petição inicial
- **Objeto imediato**: pedido dirigido ao Estado-Juiz para obter uma tutela jurisdicional
- **Objeto mediato**: bem da vida ou providência material buscada pelo autor
- **Congruência**: princípio que limita a atuação do juiz ao pedido formulado pelo autor

### Referências legais
- Art. 322, § 2º, CPC
- Súmula 48 STJ

### Jurisprudência
- RE 123456
- Tema repetitivo da ultra petita

### Dicas de prova
- Diferenciar entre pedido e objeto mediato
- Interpretação lógica e sistemática do pedido inicial
- Princípio da congruência e sua limitação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.164 (1)", "page_number": 164, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 322, § 2º, CPC", "Súmula 48 STJ"], "jurisprudence": ["RE 123456", "Tema repetitivo da ultra petita"], "confidence": 0.8, "extracted_at": "2026-05-27T20:26:50.147998+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=164", "doc_key": "3a90287bc479e0b255b7f10374f8c02d"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '8680d57ee60a60bfcb4a2f6fcefd9d69494faf1818c649c37174e0993c39b6c1'),
  ('cpiuris2025::6379ef899a2e61b3645b38a3801615af', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Reconhecimento de pedido implícito', '## Reconhecimento de pedido implícito

A possibilidade de reconhecer procedente o pleito e condenar ao pagamento das prestações periódicas vencidas, desde que implícito. A ausência de pedido para pagamento de custas processuais e honorários é outro exemplo.

### Conceitos
- **pedido implícito**: reclamação feita sem expressão explícita em documento judicial
- **decisão omissiva**: decisão do juiz que não aborda um ponto específico
- **embargos de declaração**: ação processual para suprir a omissão em decisão do juiz
- **súmula 453 do STJ**: decisão do Superior Tribunal de Justiça que estabelece regras sobre honorários sucumbenciais

### Referências legais
- Art. 85, § 18, do CPC

### Jurisprudência
- REsp 1.537.996/DF
- AgRg no REsp 1.455713/SC
- Súmula 453, STJ

### Dicas de prova
- Distinção entre pedido explícito e implícito
- Importância de expressar decisão omissiva
- O que são embargos de declaração?', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.164 (2)", "page_number": 164, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 85, § 18, do CPC"], "jurisprudence": ["REsp 1.537.996/DF", "AgRg no REsp 1.455713/SC", "Súmula 453, STJ"], "confidence": 0.8, "extracted_at": "2026-05-27T20:27:31.224388+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=164", "doc_key": "6379ef899a2e61b3645b38a3801615af"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '43c6ab0da3bdac76ff0158f2ff3a34ed72360e9b158ea632640e67a2e19f6b97'),
  ('cpiuris2025::63ed25f62d5a9591faf3ff7a42214f1f', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Pedido Genérico', '## Pedido Genérico

O pedido genérico é aquele que não é delimitado, pois o autor não tem condições de individualizar a abrangência do bem da vida que pretende obter. Exemplos incluem ações universais, quando não é possível determinar as consequências do ato ou fato praticado.

### Conceitos
- **Ação Universal**: ação demanda em que se discute a propriedade de um bem sem que seja possível indicar os bens exatamente
- **Universalidade de Fato**: refer-se à universalidade de fato, quando não é possível delimitar o pedido inicialmente
- **Universalidade de Direito**: refere-se à herança, quando não é possível delimitar o pedido inicialmente

### Referências legais
- CPC
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre universalidade de fato e direito para evitar erros.
- Não confunda ações universais com ações genéricas, pois o CPC proibiu expressamente o pedido genérico de danos morais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.165 (1)", "page_number": 165, "discipline": "Direito Processual Civil", "legal_refs": ["CPC", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T20:28:02.448139+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=165", "doc_key": "63ed25f62d5a9591faf3ff7a42214f1f"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ef0e6c460b47421f9366113ca0f76acf6880f398620d4034dce6f6e5a17501fa'),
  ('cpiuris2025::82f99d87c7d8909b00e0503ee0eb3278', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Valor dos danos morais', '## Valor dos danos morais

O valor dos danos morais deve ser determinado pela parte autora, mas se o juiz fixar um valor inferior ao postulado, o demandado arcará exclusivamente com as custas e honorários.

### Conceitos
- **danos morais**: indemnização por dano à dignidade pessoal
- **sucumbência**: obrigação de pagar despesas processuais
- **procedência do pedido**: decisão favorável ao autor

### Referências legais
- Art. 82, § 2º, CPC

### Jurisprudência
- RE 123456
- Súmula 234 STF

### Dicas de prova
- Diferença entre valor postulado e valor fixado pelo juiz
- Consequência da procedência do pedido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.165 (2)", "page_number": 165, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 82, § 2º, CPC"], "jurisprudence": ["RE 123456", "Súmula 234 STF"], "confidence": 0.8, "extracted_at": "2026-05-27T20:28:25.173231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=165", "doc_key": "82f99d87c7d8909b00e0503ee0eb3278"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'dc5ad77ab70bed652cea1ba0f86cb4554b1610117c2e0187612d259f35bf57e5'),
  ('cpiuris2025::8c9b272d34b536b9351e1378efddda57', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumulação de Pedidos', '## Cumulação de Pedidos

A cumulação de pedidos é a formulação de mais de um pedido dentro do mesmo processo. Pode ser comum ou simples, dependendo da independência dos pedidos e da adequação do procedimento.

### Conceitos
- **Cumulação comum**: Há cumulação comum quando o demandante formula mais de um pedido no mesmo processo, e entre estes pedidos há independência.
- **Cumulação simples**: Poderá tanto um quanto o outro ou os dois serem acolhidos. O valor da causa, no caso de cumulação simples, será a soma de ambos os pedidos.
- **Cumulação sucessiva**: Há uma relação de dependência entre os pedidos, de modo que o acolhimento do pedido principal pressupõe o do pedido sucessivo.
- **Compatibilidade dos pedidos**: Os pedidos devem ser compatíveis entre si
- **Competência do juízo**: O juízo competente para ambos os pleitos deve ser identificado.
- **Adequação do procedimento**: Deve ser adequado o mesmo tipo de procedimento para ambos os pedidos

### Referências legais
- Art. 327 do CPC
- Súmula 326 do STJ

### Dicas de prova
- Pergunte sobre a diferença entre cumulação comum e simples.
- Entenda o conceito de compatibilidade dos pedidos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.166 (1)", "page_number": 166, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 327 do CPC", "Súmula 326 do STJ"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:29:14.439726+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=166", "doc_key": "8c9b272d34b536b9351e1378efddda57"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', 'ae7a43ad82ee5df6ede54e5ae5c691ec7d58e76c05274046777a1a282d3e961c'),
  ('cpiuris2025::f712b6e98c166c0924397cb2936c8f4e', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Cumulação de Pedidos', '## Cumulação de Pedidos

A cumulação de pedidos ocorre quando se apresentam vários pedidos em um mesmo processo, com uma ordem hierárquica entre eles. Existem dois tipos: cumulação eventual ou subsidiária e cumulação alternativa.

### Conceitos
- **Cumulação de Pedidos**: Ocorre quando se apresentam vários pedidos em um mesmo processo
- **Ordem Hierárquica**: Existência de uma ordem preferencial entre os pedidos apresentados
- **Cumulação Eventual ou Subsidiária**: O autor apresenta um pedido primário e outro subsidiário, com ordem de preferência
- **Cumulação Alternativa**: O demandante apresenta dois pedidos sem ordem hierárquica, deixando a escolha para o julgador

### Referências legais
- Art. 273 do Código de Processo Civil

### Dicas de prova
- Entenda a diferença entre cumulação eventual e subsidiária
- Conheça o conceito de ordem hierárquica nos pedidos apresentados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.166 (2)", "page_number": 166, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 273 do Código de Processo Civil"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:29:41.406197+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=166", "doc_key": "f712b6e98c166c0924397cb2936c8f4e"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '15e9dd7c92bc5e1c3ea61aeaa35b80c7d153fe8f02febead9e19d7662bf34005'),
  ('cpiuris2025::10f9c87f246a5cb3acc89c71d23ef454', 'doutrina', 'cp_iuris', 'Direito Processual Civil — Indicação do valor da causa e provas', '## Indicação do valor da causa e provas

O autor deve indicar o valor da causa que pretende obter e as provas que pretende produzir, de acordo com o art. 292 do CPC.

### Conceitos
- **Pedido alternativo**: Um pedido único que pode ser prestado de diversas formas
- **Cumulação alternativa**: A combinação de vários pedidos em uma única petição inicial
- **Indicação do valor da causa**: O valor que o autor pretende obter, que deve corresponder ao proveito econômico perseguido
- **Audiência de conciliação ou mediação**: Um procedimento obrigatório que visa resolver a disputa sem julgamento

### Referências legais
- Art. 292 do CPC
- Art. 325 do CPC

### Dicas de prova
- Pegar a distinção entre pedido alternativo e cumulação alternativa
- Entender que o valor da causa deve corresponder ao proveito econômico perseguido pelo autor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf", "source_ref": "IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf · p.167 (1)", "page_number": 167, "discipline": "Direito Processual Civil", "legal_refs": ["Art. 292 do CPC", "Art. 325 do CPC"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T20:30:11.043006+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Processual Civil - Vol. 04 - 2025.pdf#page=167", "doc_key": "10f9c87f246a5cb3acc89c71d23ef454"}'::jsonb, '{"materia": "Direito Processual Civil"}'::jsonb, 'cp_iuris_2025', '6602f91c8090e068e2fa7f2a182dbb7123e53eda9bb36f691677aa7b72eb0632')
